(window.GIM_TS=window.GIM_TS||{})["Yevamot.5"]={"from":120,"a":[["\u0003משאי אפשר\u0004 שהרי אי אפשר שתהיה פריה ורביה בעולם בלא זכר ונקיבה בתחילה, מה שאין כן לאחר מכן, שבדרך הטבע יוולדו בעולם נקבות כנגד זכרים אלו ובכך ימשיך קיום העולם. ושואלים: \u0003ובית הלל נמי, לילפו\u0004 \u0005[גם כן שילמדו]\u0006 \u0003ממשה! אמרי לך\u0004 \u0005[\u0006יכולים \u0005לומר לך\u0006 בית הלל\u0005]:\u0006 \u0003משה מדעתיה\u0004 \u0005[מדעתו]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה]\u0006 כן, שפירש מאשתו, ולא מפני שכך הוא אכן הדין שלאחר לידת שני זכרים אדם רשאי להיבטל ממצות פריה ורביה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלשה דברים עשה משה מדעתו, והסכימה דעתו לדעת המקום: פירש מן האשה, ושיבר\u0004 את \u0003הלוחות\u0004 הראשונים, \u0003והוסיף יום אחד\u0004 להכנה למתן תורה.","ומפרטים: \u0003פירש מן האשה, מאי\u0004 \u0005[מה]\u0006 \u0003דרש,\u0004 מה היה טעמו? \u0003אמר: ומה ישראל, שלא דברה עמהם שכינה\u0004 בזמן מתן תורה \u0003אלא לפי שעה, וקבע להם זמן\u0004 מראש, בכל זאת \u0003אמרה תורה: \"אל תגשו אל אשה\"\u0004 (שמות יט, טו) — \u0003אני, שמיוחד\u0004 ומזומן אני \u0003לדבור\u0004 השכינה \u0003בכל שעה ושעה, ולא קבע לי זמן — על אחת כמה וכמה\u0004 שצריך אני לפרוש. \u0003והסכימה דעתו לדעת המקום, שנאמר: \"לך אמר להם שובו לכם לאהליכם. ואתה פה עמד עמדי\"\u0004 (דברים ה, כז-כח) משמע כל העם חוזרים \"לאהליהם\"=בתיהם ונשיהם, אבל משה נשאר עם ה', שלא ניתנה לו רשות לחזור אל ביתו=אשתו.","\u0003שיבר את הלוחות, מאי\u0004 \u0005[מה]\u0006 \u0003דרש? אמר: ומה\u0004 קרבן \u0003פסח, שהוא\u0004 רק \u0003אחד משש מאות ושלש עשרה מצות\u0004 שבתורה, \u0003אמרה תורה \"כל בן נכר לא יאכל בו\"\u0004 (שמות יב, מג), ומשמעות הכתוב שלא רק גוי, אלא גם ישראל משומד, אסור לאכול מקרבן הפסח — \u0003התורה כולה\u0004 העומדת להינתן, \u0003וישראל\u0004 כשהם עכשיו \u0003משומדים\u0004 לעבודה זרה — \u0003על אחת כמה וכמה\u0004 שאינם ראויים לקבלה.","\u0003והסכימה דעתו לדעת המקום, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004הלוחות הראשונים \u0003אשר שברת\"\u0004 (שם לד, א), \u0003ואמר ריש לקיש: אמר לו הקדוש ברוך הוא למשה\u0004 \"אשר\", לומר לו: \u0003יישר כחך ששברת.\u0004","וזה ש\u0003הוסיף יום אחד מדעתו, מאי\u0004 \u0005[מה]\u0006 \u0003דרש? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וקדשתם היום ומחר\"\u0004 (שם יט, י) והוא דרש: \u0003היום כמחר, מה מחר לילו עמו\u0004 שהרי מהיום והלאה מתקדשים, \u0003אף היום\u0004 צריך שיהיה \u0003לילו עמו, ו\u0004כיון שה\u0003לילה דהאידנא נפק ליה\u0004 \u0005[של עכשיו יצא,\u0006 הלך \u0005לו]\u0006 שהרי ההוראה הזו נאמרה ביום, על כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי צריך \u0003תרי יומי לבר מהאידנא\u0004 \u0005[שני ימים חוץ מעכשיו,\u0006 מהיום הזה\u0005].\u0006 \u0003והסכימה דעתו לדעת המקום — שאכן לא שריא\u0004 \u0005[שרתה]\u0006 ה\u0003שכינה\u0004 על הר סיני \u0003עד שבתא\u0004 \u0005[\u0006יום \u0005השבת],\u0006 שהיה היום השלישי חוץ מהיום שעמדו בו, כפי שאמר משה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר, בית שמאי אומרים:\u0004 מצות פריה ורביה — \u0003שני זכרים ושתי נקבות, ובית הלל אומרים: זכר ונקבה.\u0004","\u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' נתן אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003בית שמאי? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותסף ללדת את אחיו את הבל\"\u0004 (בראשית ד, ב) לשונות \"את\" אלה לשון ריבוי הם, ומשמעם: \u0003הבל ואחותו\u0004 (\"את הבל\"), \u0003קין ואחותו\u0004 (\"את אחיו\"), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי שת לי אלהים זרע אחר תחת הבל כי הרגו קין\"\u0004 (שם כה), משמע שכל עוד אין לאדם ארבעה ילדים לפחות — צריך להשלים אותם. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם דבר זה? לדעתם \u0003אודויי הוא דקא מודית\u0004 \u0005[הודיה היא שמודה\u0006 לה'\u0005]\u0006 על ששת לה זרע אחר, אבל לא שהיתה מחוייבת בדבר.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003ר' נתן אומר: בית שמאי אומרים:\u0004 קיום מצות פריה ורביה הוא ב\u0003זכר ונקבה, ובית הלל אומרים: או זכר או נקבה. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' נתן אליבא\u0004 \u0005[לשיטת]\u0006 \u0003בית הלל — שנאמר: \"לא תהו בראה לשבת יצרה\"\u0004 (ישעיהו מה, יח), \u0003והא עבד\u0004 \u0005[והרי עשה]\u0006 \u0003לה\u0004 לארץ, תרם כבר משהו, לענין של \u0003שבת,\u0004 שיישב את העולם באדם נוסף.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: \u0003היו לו בנים בגויותו\u0004 (בהיותו גוי) \u0003ונתגייר, ר' יוחנן אמר: קיים\u0004 כבר על ידי ילדיו הגויים מצות \u0003פריה ורביה, וריש לקיש אמר: לא קיים פריה ורביה. ר' יוחנן אמר: קיים פריה ורביה — דהא הוו ליה\u0004 \u0005[שהרי היו לו]\u0006 ילדים. \u0003וריש לקיש אמר: לא קיים פריה ורביה,\u0004 כי \u0003גר שנתגייר כקטן שנולד דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 וכאילו מתחילים כל חייו מרגע הגיור.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והלכו לטעמם,\u0006 לשיטתם\u0005]\u0006 במחלוקת דומה. \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003היו לו בנים בגויותו ונתגייר, ר' יוחנן אמר: אין לו בכור לנחלה,\u0004 שהבן הראשון שיוולד לו ביהדותו לא ייחשב בכור לענין נחלה, \u0003דהא הוה ליה\u0004 \u0005[שהרי\u0006 כבר \u0005היה לו]\u0006 \u0003\"ראשית אנו\"\u0004 (דברים כא, יז) בילד אחר. \u0003וריש לקיש אמר: יש לו בכור לנחלה,\u0004 כי \u0003גר שנתגייר כקטן שנולד דמי.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 שיחלקו במפורש בשתי הבעיות, שאינן למדות זו מזו: \u0003דאי אשמעינן בההיא קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005באותה הראשונה]\u0006 לענין מצות פריה ורביה, הייתי אומר: \u0003בההיא קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוחנן\u0004 שבנו בגויותו נחשב לו לענין פריה ורביה כבן \u0003— משום דמעיקרא נמי\u0004 \u0005[שמתחילה גם כן]\u0006 \u0003בני פריה ורביה נינהו\u0004 \u0005[הם],\u0006 ויש גם עליהם מצוה מסויימת בדבר, \u0003אבל לענין נחלה, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני נחלה נינהו\u0004 \u0005[הם],\u0006 שאין דיני נחלות שייכים בהם, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לריש לקיש.\u0004","ולהיפך: \u0003ואי איתמר בהא\u0004 \u0005[ואילו נאמר\u0006 רק \u0005בזו]\u0006 בענין בכור, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ריש לקיש\u0004 שאין להתייחס לבנו בגויותו כבכור, כיון שאין דין נחלות בגויים, \u0003אבל בההיא,\u0004 בענין פריה ורביה, \u0003אימא מודה ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יוחנן,\u0004 על כן, \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה שתי המחלוקות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש,\u0004 הלא נאמר: \u0003\"בעת ההיא שלח בראדך בלאדן בן בלאדן מלך בבל\"\u0004 (מלכים ב' כ, יב), משמע שגם לגבי הגויים מייחסים את הבן אחרי האב! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בגויותן\u0004 (בהיותם גויים) — \u0003אית להו חייס\u0004 \u0005[יש להם ייחוס]\u0006 משפחה, ובודאי הם מתייחסים לבית אבותם, אולם כאשר \u0003נתגיירו לית להו חייס\u0004 \u0005[אין להם ייחוס]\u0006 משום שהגרים שייכים עכשיו למשפחת ישראל, ואין ייחוסם הקודם נחשב.","\u0003אמר רב: הכל מודין בעבד\u0004 כנעני \u0003שאין לו חייס\u0004 \u0005[יחוס\u0006 משפחה\u0005],\u0006 שאין קשרי משפחה נחשבים לגביו, \u0003דכתיב\u0004 \u0005[שנאמר],\u0006 שאמר אברהם לעבדיו: \u0003\"שבו לכם פה עם החמור\"\u0004 (בראשית כב, ה), ודרשוהו: \u0003עם הדומה לחמור. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה שנאמר בציבא עבדו הכנעני של מפיבושת: \u0003\"ולציבא חמשה עשר בנים ועשרים עבדים\"\u0004 (שמואל ב' ט, י), משמע שאף בניו של עבד נחשבים בנים! \u0003אמר רב אחא בר יעקב: כ\"פר בן בקר\",\u0004 כלומר, \"בן\" משמעו — צאצא. ו\"בנים\" פירושו ילדים, אבל אין הם נחשבים בנים לענין יחס המשפחה.","ושואלים: \u0003אי הכי, הכא נמי\u0004 \u0005[אם כך, כאן גם כן],\u0006 לענין גויים, שמה שנאמר בברואדך בלאדן אינו מוכיח שיש להם יחס משפחה! ומשיבים: \u0003שאני התם דיחסינהו בשמייהו ובשמא דאבוהון\u0004 \u0005[שונה שם, שייחסם בשמם ובשם אבותם],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003לא מפרש\u0004 את שמותיהם אלא רק אומר שהיו לו ילדים. \u0003ואיבעית אימא יחסינהו בדוכתא אחריתי באבוהון ובאבא דאבוהון\u0004 \u0005[ואם תרצה אמור\u0006 ש\u0005ייחסם\u0006 את הגויים \u0005במקום אחר באביהם ובאבי אביהם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישלחם המלך אסא אל בן הדד בן טברמן בן חזיון מלך ארם הישב בדמשק לאמר\"\u0004 (מלכים א' טו, יח), הרי כאן ייחוס משפחה, שאנחנו חושבים אותו לפי האב.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003היו לו\u0004 לאדם \u0003בנים, ומתו. רב הונא אמר: קיים\u0004 בכך מצות \u0003פריה ורביה,\u0004 אף שבסופו של דבר מתו. \u0003ר' יוחנן אמר: לא קיים.\u0004","ומסבירים: \u0003רב הונא אמר: קיים,\u0004 וטעמו: \u0003משום\u0004 מה שאמר \u0003רב אסי.\u0004 ש\u0003אמר רב אסי\u0004 טעם למצות פריה ורביה: משום ש\u0003אין\u0004 משיח \u0003בן דוד בא עד שיכלו כל נשמות שבגוף,\u0004 שכל הנשמות שיכולות להיוולד בגופים — צריכות להיוולד, \u0003שנאמר: \"כי רוח מלפני יעטוף\u0004 ונשמות אני עשיתי\u0003\"\u0004 (ישעיהו נז, טז), ולכן, כיון שנולד ילד ונכנסה נשמה לגוף, אף על פי שמת הילד הזה — מכל מקום הנשמה הזו הגיעה לידי ביטוי בתוך גוף, וקיים על ידי כך מצות פריה ורביה. \u0003ור' יוחנן אמר: לא קיים פריה ורביה,\u0004 ומדוע — כי \u0003\"לשבת יצרה\"\u0004 (שם מה, יח) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא ליכא\u0004 \u0005[והרי אין\u0006 כאן\u0005],\u0006 שמתו הילדים הללו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו:"],["\u0003בני בנים הרי הם כבנים\u0004 ולכאורה משמע מכאן שאף אם מתו בניו, אלא שנשארו לו בני בנים מהם, קיים בכך מצות פריה ורביה, אבל אם לא היו בני בנים — לא, והרי שתכלית המצוה היא ביישוב העולם, וזה שיש לו בני בנים, אף שמתו בניו, הלא קיים תכלית זו! ודוחים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא,\u0004 הרי זה \u0003להשלים\u0004 למנין הילדים הראוי, כגון שהיה לו בן אחד והיתה לו ממנו נכדה אחת, שבכך קיים מצוותו, ואולם אם היו לו בן ובת, אף שמתו הם בלא בנים — קיים חובתו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על רב הונא ממה ששנינו: \u0003בני בנים הרי הם כבנים, מת אחד מהם או שנמצא סריס — לא קיים\u0004 מצות \u0003פריה ורביה.\u0004 משמע שלא די בזה שיש לו בני בנים, אלא צריך גם שיחיו ויוכלו לפרות ולרבות, והרי מכאן \u0003תיובתא\u0004 \u0005[קושיה\u0006 \u0005חמורה]\u0006 על \u0003רב הונא!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה\u0006 היא\u0005]\u0006 ונדחו דבריו.","שנינו בברייתא ש\u0003בני בנים הרי הם כבנים. סבר אביי למימר\u0004 \u0005[לומר],\u0006 שהכלל מתקיים רק כאשר יש \u0003ברא לברא\u0004 \u0005[בן לבן]\u0006 \u0003וברתא לברתא\u0004 \u0005[ובת לבת],\u0006 \u0003וכל שכן ברא לברתא\u0004 \u0005[בן לבת]\u0006 שעומד במקום אמו, \u0003אבל ברתא לברא\u0004 \u0005[בת לבן] —\u0006 \u0003לא,\u0004 שאיננה נחשבת במנין מפני שאין היא יכולה למלא מקום אביה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 הלא \u0003\"לשבת יצרה\" בעיא\u0004 \u0005[צריך],\u0006 \u0003והא איכא\u0004 \u0005[והרי יש\u0006 כאן\u0005],\u0006 שהרי נתיישב העולם בילדיו.","ומעירים: \u0003דכולי עלמא מיהת\u0004 \u0005[\u0006לדעת \u0005הכל על כל פנים]\u0006 \u0003תרי מחד\u0004 \u0005[שנים מ\u0006בן \u0005אחד]\u0006 \u0003לא,\u0004 שאם היו לו רק בן אחד או בת אחת, ולהם שני ילדים, זכר ונקיבה — לא קיים על ידם פריה ורביה. ושואלים: \u0003ו\u0004האם \u0003לא? והא אמרי ליה רבנן\u0004 \u0005[והרי אמרו לו חכמים]\u0006 \u0003לרב ששת: נסיב איתתא ואוליד בני\u0004 \u0005[שא אשה והולד בנים],\u0006 שלא היו לו בנים, \u0003ואמר להו\u0004 \u0005[להם]\u0006 רב ששת: \u0003בני ברתי\u0004 \u0005[בתי]\u0006 \u0003בני נינהו\u0004 \u0005[הם],\u0006 משמע שעל ידי בני בתו יוצא ידי חובה!","ומשיבים: \u0003התם דחויי קמדחי להו\u0004 \u0005[שם\u0006 רק \u0005דחה אותם],\u0006 משום שלא רצה לומר להם את הטעם האמיתי שאינו נושא אשה, כי \u0003רב ששת איעקר מפרקיה\u0004 \u0005[נעשה עקר מ\u0006תוך \u0005דרשתו]\u0006 של \u0003רב הונא,\u0004 שהיה מאריך בדרשותיו ולא יכלו אנשים לצאת לעשות צרכיהם, ועל ידי כך נעשו האנשים עקרים.","באותו ענין \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרבא בר מארי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מניין דבר זה שאמרו חכמים]\u0006 \u0003בני בנים הרי הן כבנים? אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]\u0006 בדברי לבן ליעקב על בני \u0003\"הבנות בנתי והבנים בני\"\u0004 (בראשית לא, מג), שמזה משמע שבני יעקב נחשבים כבני לבן סבם — \u0003אלא מעתה \"והצאן צאני\"\u0004 (שם) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא באמת שלו?! \u0003אלא,\u0004 הכוונה היא \u0003דקנית מינאי\u0004 \u0005[שקנית,\u0006 שקיבלת, \u0005ממני],\u0006 \u0003הכא נמי\u0004 \u0005[כאן\u0006 בענין הבנים \u0005גם כן]\u0006 פירושו — \u0003דקנית מינאי\u0004 \u0005[\u0006אלה \u0005שקנית,\u0006 שקיבלת, \u0005ממני],\u0006 שבגללי יש לך עכשיו בנים.","\u0003אלא,\u0004 הראיה היא \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"ואחר בא חצרון אל בת מכיר אבי גלעד\u0004 והוא לקחה והוא בן שישים שנה \u0003ותלד לו את שגוב\"\u0004 (דברי הימים א' ב, כא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"מני מכיר ירדו מחקקים\"\u0004 (שופטים ה, יד) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"יהודה מחקקי\"\u0004 (תהלים ס, ט), נמצא שמחוקקי שבט יהודה מתייחסים גם למכיר, אף שהם רק בני בתו (שנשא אותה חצרון משבט יהודה) ומכאן רואים שבני בנים נחשבים כבנים.","מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 האומרת שכהן לא ישא אילונית אלא אם כן יש לו בנים, ומשמע שאם יש לו כבר בנים יכול לישא אילונית ולהבטל מפריה ורביה, משנה זו היא \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003כ\u0004דעת \u0003ר' יהושע. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהושע אומר: נשא אדם אשה בילדותו — ישא אשה\u0004 אחרת \u0003בזקנותו. היו לו בנים בילדותו — יהיו לו בנים בזקנותו. שנאמר: \"בבקר זרע את זרעך ולערב אל תנח ידך כי אינך יודע אי זה יכשר הזה או זה ואם שניהם כאחד טובים\"\u0004 (קהלת יא, ו), משמע שצריך לעסוק בפריה ורביה אפילו כשיש לו בנים.","\u0003ר' עקיבא אומר\u0004 ומפרש פסוק זה כך: \u0003למד תורה בילדותו — ילמד תורה בזקנותו. היו לו תלמידים בילדותו\u0004 — \u0003יהיו לו תלמידים בזקנותו. שנאמר: \"בבקר זרע את זרעך וגו'\".\u0004 ו\u0003אמרו\u0004 כעין ראיה לדבר: \u0003שנים עשר אלף זוגים\u0004 (זוגות) \u0003תלמידים היו לו לר' עקיבא\u0004 בחבל הארץ ש\u0003מגבת עד אנטיפרס\u0004 בארץ יהודה, \u0003וכולן מתו בפרק\u0004 (זמן) \u0003אחד, מפני שלא נהגו כבוד זה לזה.\u0004","\u0003והיה העולם שמם\u0004 מתורה, \u0003עד שבא ר' עקיבא אצל רבותינו שבדרום ושנאה\u0004 את תורתו \u0003להם,\u0004 ותלמידים אחרונים אלה הם: \u0003ר' מאיר, ור' יהודה, ור' יוסי, ור' שמעון, ור' אלעזר בן שמוע, והם הם העמידו תורה אותה שעה.\u0004 הרי שאף שהיו לו תלמידים רבים כל כך בשנותיו המוקדמות, מכל מקום לא נתקיימו, ומי שנתקיימו היו דווקא תלמידיו האחרונים, שמהם יצאה תורה לישראל.","אגב אותו ענין מעירים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 כל התלמידים \u0003כולם מתו מפסח ועד עצרת. אמר רב חמא בר אבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבין: כולם מתו מיתה רעה.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 מיתה רעה זו? \u0003אמר רב נחמן: אסכרה.\u0004","\u0003אמר רב מתנא: הלכה כר' יהושע,\u0004 שצריך אדם להשתדל להוליד בנים, גם אם כבר קיים מצות פריה ורביה.","אגב הדיון בהלכות פריה ורביה מדברים בשבח הנישואין בכלל. \u0003אמר ר' תנחום אמר ר' חנילאי: כל אדם שאין לו אשה — שרוי בלא שמחה, בלא ברכה, בלא טובה.\u0004 ומביא ראיות לדבריו: \u0003בלא שמחה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמחת אתה וביתך\"\u0004 (דברים יד, כו), משמע שהשמחה היא כאשר מצויים איש וביתו=אשתו. \u0003בלא ברכה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להניח ברכה אל ביתך\"\u0004 (יחזקאל מד, ל), שהברכה באה על הבית=האשה. \u0003בלא טובה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא טוב היות האדם לבדו\"\u0004 (בראשית ב, יח), משמע שטובה היא לו לאדם עם אשתו.","\u0003במערבא אמרי\u0004 \u0005[בארץ ישראל\u0006 מוסיפים ו\u0005אומרים]:\u0006 השרוי בלא אשה שרוי \u0003בלא תורה, בלא חומה. בלא תורה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"האם אין עזרתי בי ותשיה נדחה ממני\"\u0004 (איוב ו, יג), שמי שאין לו אשה שהיא עזר כנגדו (\"אין עזרתי בי\"), אף תורה (\"תושיה\") אין לו. \u0003בלא חומה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נקבה תסובב גבר\"\u0004 (ירמיהו לא, כא), שהנקיבה היא כחומה המסובבת ומגינה על הגבר.","\u0003רבא בר עולא אמר:\u0004 השרוי בלא אשה שרוי \u0003בלא שלום, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידעת כי שלום אהלך ופקדת נוך ולא תחטא\"\u0004 (איוב ה, כד), שהשלום בא לו לאדם רק כשיש לו \"אהל\"=אשה (כפי שנאמר: \"שובו לכם לאהליכם\". דברים ה, כז).","על אותו כתוב \u0003אמר ר' יהושע בן לוי: כל היודע באשתו שהיא יראת שמים\u0004 ומשתוקקת לו, \u0003ואינו פוקדה\u0004 בתשמיש — \u0003נקרא חוטא, שנאמר: \"וידעת כי שלום אהלך\u0004 ופקדת נוך \u0003\". ואמר ר' יהושע בן לוי: חייב אדם לפקוד את אשתו בשעה שהוא יוצא לדרך, שנאמר: \"וידעת כי שלום אהלך\",\u0004 שבצאתו מאהלו צריך גם לפקוד את אשתו, מפני שאז משתוקקת היא לו יותר.","ושואלים: ו\u0003הא, מהכא נפקא\u0004 \u0005[\u0006ודבר \u0005זה, מכאן\u0006 הוא \u0005יוצא,\u0006 נלמד\u0005],\u0006 הלא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 מפסוק אחר, הוא \u0005יוצא,\u0006 נלמד\u0005],\u0006 שנאמר: \u0003\"ואל אישך תשוקתך\"\u0004 (בראשית ג, טז), \u0003מלמד שהאשה משתוקקת על בעלה בשעה שהוא יוצא לדרך. אמר רב יוסף: לא נצרכה\u0004 תוספת אזהרה זו \u0003אלא\u0004 כשיוצא לדרך \u0003סמוך לווסתה.\u0004 שאף שאמרו חכמים שאין ראוי לבוא אז אל אשתו, מחשש שמא יקדים קצת זמן ווסתה — מכל מקום בזמן שהוא יוצא לדרך צריך לפוקדה.","ושואלים: \u0003וכמה\u0004 הוא \"סמוך\" לענין זה? \u0003אמר רבא: עונה.\u0004 כלומר, יום או לילה לפני הזמן הקבוע של ווסתה. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שחייב לפקוד את אשתו כשיוצא לדרך, אמורים דווקא כשיוצא \u0003לדבר הרשות, אבל\u0004 אם יוצא \u0003לדבר מצוה — מיטרידי\u0004 \u0005[\u0006הם \u0005נטרדים]\u0006 מן המצוה, מתוך עיסוקם זה בזה, ולכן לא יפקדנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האוהב את אשתו כגופו\u0004 (כמו את עצמו) \u0003והמכבדה יותר מגופו\u0004 (מעצמו) מפני שהנשים רגישות יותר לכבודן, \u0003והמדריך בניו ובנותיו בדרך ישרה, והמשיאן סמוך לפירקן\u0004 (סמוך לזמן ההתבגרות) — \u0003עליו הכתוב אומר \"וידעת כי שלום אהלך\",\u0004 שעל ידי כך הוא זוכה שבאוהלו=ביתו יהיה שלום ולא יהיו בו מריבה וחטא. \u0003האוהב את שכיניו, והמקרב את קרוביו\u0004 (קרובי משפחתו) \u0003והנושא את בת אחותו\u0004 שנמצא נושא אשה שהוא מכיר ומחבב אותה לא רק מטעם אישות, אלא גם מטעם קירבת המשפחה,"],["\u0003והמלוה סלע\u0004 (כסף) \u0003לעני בשעת דחקו,\u0004 כשהוא זקוק לכסף — \u0003עליו הכתוב אומר: \"אז תקרא וה' יענה תשוע ויאמר הנני\"\u0004 (ישעיהו נח, ט).","\u0003סימן\u0004 לדברים שייאמרו להלן בשם ר' אלעזר: \u0003אש\"ה וקרק\"ע עז\"ר זא\"ת שת\"י הברכו\"ת תגר\"י פחת\"י. אמר ר' אלעזר: כל אדם שאין לו אשה\u0004 — \u0003אינו אדם, שנאמר: \"זכר ונקבה בראם... ויקרא את שמם אדם\"\u0004 (בראשית ה, ב). \u0003ואמר ר' אלעזר: כל אדם שאין לו קרקע\u0004 משלו \u0003אינו אדם, שנאמר: \"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (תהילים קטו, טז).","\u0003ואמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אעשה לו עזר כנגדו\"\u0004 (בראשית ב, יח), פירושו: \u0003זכה\u0004 אדם — \u0003עוזרתו\u0004 אשתו, \u0003לא זכה\u0004 — הרי היא \u0003כנגדו. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בסגנון אחר קצת: \u0003ר' אלעזר רמי\u0004 \u0005[הטיל,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כנגדו\" וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"כניגדו\".\u0004 ומשמעות הדבר, שאם \u0003זכה\u0004 — היא \u0003כנגדו\u0004 ועימו, \u0003לא זכה — מנגדתו\u0004 (מכה אותו).","מסופר: \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003ר' יוסי לאליהו\u0004 הנביא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אעשה לו עזר\", במה אשה עוזרתו לאדם? אמר ליה\u0004 \u0005[לו]\u0006 כפשוטו: \u0003אדם מביא חיטין\u0004 מן השדה — האם \u0003חיטין כוסס\u0004 (אוכל) כמו שהן? ואם מביא \u0003פשתן\u0004 מן השדה, האם \u0003פשתן\u0004 עצמו \u0003לובש?\u0004 והרי האשה היא הטוחנת קודם את החיטה ומעבדת את הפשתן, האם \u0003לא נמצאת\u0004 האשה בכך \u0003מאירה\u0004 את \u0003עיניו ומעמידתו על רגליו?!\u0004","\u0003ואמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"זאת הפעם עצם מעצמי ובשר מבשרי\"\u0004 (שם ב, כג) — \u0003מלמד שבא אדם על כל בהמה וחיה,\u0004 שלא ידע מיהי בת זוגו, \u0003ולא נתקררה\u0004 (נחה) \u0003דעתו,\u0004 כפי שנאמר קודם לכן: \"ולאדם לא מצא עזר כנגדו\", \u0003עד שבא על חוה,\u0004 ולכן אמר \"זאת הפעם\" — להבדיל מפעמים קודמות.","\u0003ואמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ונברכו בך כל משפחת האדמה\"\u0004 (שם יב, ג), \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הקדש ברוך הוא לאברהם: שתי ברכות טובות יש לי להבריך בך,\u0004 שהוא מפרש \"ונברכו\" מלשון הברכה, כדרך שמרכיבים עצים זה בזה, והן: \u0003רות המואביה\u0004 שממנה יצא בית דוד, \u0003ונעמה העמונית\u0004 שממנה ומשלמה יצאה שושלת המלוכה של יהודה בדורות הבאים. \u0003\"כל משפחות האדמה\"\u0004 כוונתו: \u0003אפילו משפחות הדרות באדמה,\u0004 ויש להן קרקע משלהן, \u0003אין מתברכות אלא בשביל ישראל. \"כל גויי הארץ\"\u0004 (שם יח, יח) — \u0003אפילו ספינות הבאות מגליא\u0004 (צרפת) \u0003לאספמיא\u0004 (ספרד), אף על פי שאין להן שום קשר ישיר עם ארץ ישראל — \u0003אינן מתברכות אלא בשביל ישראל.\u0004","\u0003ואמר ר' אלעזר: עתידים כל בעלי אומניות\u0004 שונות \u0003שיעמדו על הקרקע\u0004 ויעסקו בעיבודה, \u0003שנאמר: \"וירדו מאניותיהם כל תפשי משוט מלחים כל חבלי הים אל הארץ יעמדו\"\u0004 (יחזקאל כז, כט). \u0003ואמר ר' אלעזר: אין לך אומנות פחותה מן\u0004 אומנות \u0003הקרקע,\u0004 מעבודת האדמה, \u0003שנאמר: \"וירדו\",\u0004 משמע שגם עבור המלחים עבודת האדמה היא ירידה. וכעין זה מסופר: \u0003ר' אלעזר חזיא לההיא ארעא דשדי ביה כרבא לפותיא\u0004 \u0005[ראה אדמה,\u0006 קרקע, \u0005שהיה זרוע כרוב לרוחב\u0006 הערוגה\u0005]\u0006, שהיתה השדה חרושה לרוחב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לקרקע: \u0003אי תשדייה לאורכיך\u0004 \u0005[\u0006גם \u0005אם יחרשו אותך\u0006 פעם נוספת \u0005לאורכך]\u0006 לטייב אותך יותר — עדיין \u0003הפוכי בעיסקא טב מינך\u0004 \u0005[לעסוק בעסק טוב ממך]\u0006 כי ריווחי המסחר גדולים הרבה מהרווחים שבעבודת האדמה.","כיוצא בו מסופר: \u0003רב על לביני שיבלי\u0004 \u0005[נכנס בין השבלים],\u0006 \u0003חזנהו דקא נייפן\u0004 \u0005[ראה\u0006 אותן \u0005שהן מתנפנפות\u0006 ברוח\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להן]:\u0006 \u0003אי נייפת איתנופי\u0004 \u0005[אם תתנפנפו תתנפנפו],\u0006 אך \u0003הפוכי בעיסקא טב מינך\u0004 \u0005[לעסוק בעסק טוב מכם].\u0006 וכיוצא בו \u0003אמר רבא:\u0004 מי שיש לו \u0003מאה זוזי\u0004 \u0005[דינרים]\u0006 \u0003בעיסקא\u0004 \u0005[בעסק]\u0006 \u0003כל יומא\u0004 \u0005[יום]\u0006 יש לו \u0003בשרא וחמרא\u0004 \u0005[בשר ויין],\u0006 ומי שיש לו שווה \u0003מאה זוזי\u0004 \u0005[דינרים]\u0006 \u0003בארעא\u0004 \u0005[בקרקע] —\u0006 \u0005יש לו\u0006 \u0003מילחא וחפורה\u0004 \u0005[מלח וירקות].\u0006 \u0003ולא עוד אלא\u0004 שעבודת האדמה \u0003מגניא ליה אארעא, ומרמיא ליה תיגרי\u0004 \u0005[משכיבה אותו לארץ\u0006 לשמור, \u0005ומטילה עליו קטטות]\u0006 עם שכניו ועם אחרים.","\u0003אמר רב פפא:\u0004 אם יש בידך — \u0003זרע\u0004 את התבואה למאכל בני ביתך, \u0003ולא תזבין\u0004 \u0005[תקנה\u0006 אותה\u0005]\u0006 מן השוק, ש\u0003אף על גב דכי הדדי נינהו, הני מברכן\u0004 \u0005[\u0006ש\u0005אף על פי שהן זו כמו זו\u0006 בשוויין, \u0005אלה\u0006 שאתה זורע \u0005מבורכות].\u0006 \u0003זבין\u0004 \u0005[קנה]\u0006 בגדים לעצמך \u0003ולא תיזול\u0004 \u0005[תארוג]\u0006 בגדים לעצמך. ומעירים, \u0003הני מילי ביסתרקי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא ב\u0005מצעות],\u0006 \u0003אבל גלימא\u0004 \u0005[גלימה]\u0006 שהוא לובש אותה שמא \u0003לא מיתרמיא ליה\u0004 \u0005[תזדמן לו]\u0006 בדיוק כחפצו, ומוטב שיכין אותה בדיוק לפי מידותיו.","ועוד יעץ רב פפא: אם יש חור קטן בקיר ביתך, \u0003טום\u0004 \u0005[סתום]\u0006 אותו מיד \u0003ולא תשפיץ\u0004 \u0005[תשפץ,\u0006 תתקן\u0005]\u0006 אותו על ידי הרחבת החור כדי למלאותו בטיט ולבנים כדי שיהיה התיקון יפה יותר. ואם מכל מקום רוצה אתה לתקנו בצורה יפה יותר — \u0003שפוץ\u0004 \u0005[שפץ]\u0006 על ידי הרחבת החור ומילויו בלבנים וטיט, \u0003ולא תיבני\u0004 \u0005[תבנה]\u0006 את כל הקיר מחדש, \u0003שכל העוסק בבנין מתמסכן\u0004 (נעשה עני). \u0003קפוץ זבין ארעא\u0004 \u0005[מהר קנה קרקע]\u0006 שלא יקדימוך אחרים, \u0003מתון נסיב איתתא\u0004 \u0005[המתן\u0006 ו\u0005שא אשה]\u0006 עד שתמצא את הראויה לך. \u0003נחית דרגא נסיב איתתא\u0004 \u0005[רד דרגה\u0006 אחת ממעמדך ו\u0005שא אשה]\u0006 ממעמד נמוך יותר, שאם תישא אשה ממעמד גבוה יותר, יתכן ולא תתקבל עליה. \u0003סק דרגא\u0004 \u0005[עלה דרגה]\u0006 ו\u0003בחר\u0004 לך \u0003שושבינא\u0004 \u0005[ידיד].\u0006","\u0003אמר ר' אלעזר בר אבינא: אין פורענות באה לעולם אלא בשביל ישראל\u0004 שחטאו, \u0003שנאמר: \"הכרתי גוים נשמו פנותם החרבתי חוצותם\"\u0004 (צפניה ג, ו) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך: \u0003\"אמרתי אך תיראי אותי תקחי מוסר...\"\u0004(שם ז), משמע שכדי שישראל יקחו מוסר לקו עמים אחרים.","ועוד לענין אשה: \u0003רב הוה מיפטר\u0004 \u0005[היה נפרד]\u0006 \u0003מר' חייא\u0004 שהיה דודו ורבו, כאשר חזר מארץ ישראל לבבל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003רחמנא ליצלך ממידי\u0004 \u0005[ה' יצילך מדבר]\u0006 ש\u0003קשה ממותא\u0004 \u0005[ממוות].\u0006 ותהה רב: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 ש\u0003קשה ממותא\u0004 \u0005[ממוות]?\u0006 \u0003נפק, דק ואשכח\u0004 \u0005[יצא, דקדק\u0006 במקראות \u0005ומצא]\u0006 את הכתוב \u0003\"ומוצא אני מר ממות את האשה\"\u0004 (קהלת ז, כו) וזה שרמז לו ר' חייא. וכך אירע לו: \u0003רב הוה קא מצערא ליה דביתהו\u0004 \u0005[היתה מצערת אותו אשתו],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר לה \"עבידי לי טלופחי\"\u0004 \u0005[\"עשי לי עדשים\"],\u0006 \u0003עבדא ליה חימצי\u0004 \u0005[היתה עושה לו חומצה],\u0006 כשהיה אומר לה \u0003\"\u0004עשי לי \u0003חימצי\"\u0004 \u0005[חומצה],\u0006 \u0003עבדא ליה טלופחי\u0004 \u0005[היתה עושה לו עדשים].\u0006","\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003גדל חייא בריה\u0004 \u0005[בנו],\u0006 \u0003אפיך\u0004 \u0005[היה\u0006 חייא \u0005הופך]\u0006 \u0003לה\u0004 והיה אומר לאמו בשם אביו היפך הדברים שהוא רוצה, ואז היה אביו מקבל כרצונו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב לחייא בנו: \u0003איעליא\u0004 \u0005[השתפרה]\u0006 \u0003לך,\u0004 כלפיך \u0003אמך! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003הוא דקא אפיכנא\u0004 \u0005[שהופך]\u0006 \u0003לה\u0004 את דבריך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היינו דקא אמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם מקובל: \u0003דנפיק מינך, טעמא מלפך\u0004 \u0005[\u0006זה \u0005שיוצא ממך, טעם,\u0006 דעת \u0005מלמד אותך],\u0006 שכן אני עצמי הייתי צריך לעשות זאת. אבל \u0003את\u0004 \u0005[אתה]\u0006 \u0003לא תעביד הכי\u0004 \u0005[תעשה כך]\u0006 עוד, \u0003שנאמר: \"למדו לשונם דבר שקר העוה\u0004 נלאו\u0003\"\u0004 (ירמיהו ט, ד), שאם אתה אומר זאת בשמי — שקר הוא.","כיוצא בו מסופר: \u0003ר' חייא הוה קא מצערא ליה דביתהו\u0004 \u0005[היתה מצערת אותו אשתו].\u0006 אף על פי כן, \u0003כי הוה משכח מידי, צייר ליה בסודריה ומייתי ניהלה\u0004 \u0005[כאשר היה מוצא דבר\u0006 טוב, \u0005היה צורר אותו בסודרו ומביא לה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: והא קא מצערא ליה למר\u0004 \u0005[והרי היא\u0006 \u0005מצערת את אדוני]\u0006 ומדוע אתה משתדל להנות אותה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דיינו שמגדלות\u0004 הנשים את \u0003בנינו, ומצילות אותנו\u0004"],["\u0003מן החטא,\u0004 ומשום כך ראוי לנו להכיר להן תודה. ומספרים עוד באותו ענין: \u0003מקרי ליה\u0004 \u0005[\u0006היה \u0005מקריא לו,\u0006 מלמד אותו מקרא\u0005]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]\u0006 את הכתוב \u0003\"ומוצא אני מר ממות את האשה\"\u0004 (קהלת ז, כו). \u0003אמר ליה\u0004 \u0005[לו]\u0006 בנו: \u0003כגון מאן\u0004 \u0005[כמו מי]?\u0006 אמר לו: \u0003כגון אמך.\u0004","ושואלים: \u0003והא מתני ליה\u0004 \u0005[והרי היה שונה לו]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]\u0006 ברייתא זו: \u0003אין אדם מוצא קורת רוח אלא מאשתו\u0004 ה\u0003ראשונה, שנאמר: \"יהי מקורך ברוך ושמח מאשת נעוריך\"\u0004 (משלי ה, יח), \u0003ואמר ליה\u0004 \u0005[לו]\u0006 בנו: \u0003כגון מאן\u0004 \u0005[מי]?\u0006 השיב לו רב יהודה: \u0003כגון אמך,\u0004 משמע שהיה מוצא בה קורת רוח! ומתרצים: \u0003מתקיף תקיפא, ועבורי מיעברא במלה\u0004 \u0005[תקיפה\u0006 וקשה היתה, אבל \u0005מעבירה\u0006 על מדותיה ומתרצה \u0005בקלות].\u0006","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 דרכה של \u0003אשה רעה? אמר אביי: מקשטא ליה תכא ומקשטא ליה פומא\u0004 \u0005[מקשטת לו שולחן\u0006 לאכול \u0005ומקשטת לו הפה],\u0006 כלומר, מחרפת ומגדפת אותו בזמן האוכל. \u0003רבא אמר: מקשטא ליה תכא ומהדרא ליה גבא\u0004 \u0005[מקשטת לו שולחן ומחזירה,\u0006 ומפנה \u0005לו את גבה]\u0006 להראות שאינה רוצה בחברתו.","\u0003אמר ר' חמא בר חנינא: כיון שנשא אדם אשה — עונותיו מתפקקין\u0004 \u0005[נסתמים]\u0006 ומתבטלים, \u0003שנאמר: \"מצא אשה מצא טוב ויפק רצון מה'\"\u0004 (שם יח, כב), ודורש \"יפק\" מלשון פקק. \u0003במערבא כי נסיב אינש איתתא, אמרי ליה הכי\u0004 \u0005[בארץ ישראל כאשר היה נושא אדם אשה,\u0006 היו \u0005אומרים לו\u0006 ושואלים אותו \u0005כך]:\u0006 \u0003\"מצא או מוצא\"?\u0004 והכוונה: \u0003\"מצא\" — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מצא אשה מצא טוב\",\u0004 או \u0003\"מוצא\" דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומוצא אני מר ממות את האשה\"\u0004 (קהלת ז, כו).","\u0003אמר רבא: אשה רעה — מצוה לגרשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גרש לץ ויצא מדון וישבת דין וקלון\"\u0004 (משלי כב, י), \u0003ואמר רבא: אשה רעה וכתובתה מרובה,\u0004 שאין בעלה יכול לשלם את הכתובה ולגרש אותה — \u0003צרתה בצדה,\u0004 כלומר, אין דרך לתקנה אלא על ידי שישא עליה אשה אחרת. \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 בפתגם מקובל: גורמים סבל לאשה \u0003בחברתא\u0004 \u0005[בחברתה]\u0006 על ידי אשה אחרת, צרה, \u0003ולא בסילתא\u0004 \u0005[ב\u0006דקירת \u0005קוץ].\u0006 \u0003ואמר רבא: קשה אשה רעה כיום סגריר, שנאמר: \"דלף טורד ביום סגריר ואשת מדינים נשתוה\"\u0004 (שם כז, טו), שאשה רעה (\"מדינים\") שווה (\"נשתווה\") ליום סגריר.","\u0003ואמר רבא: בא וראה כמה טובה אשה טובה, וכמה רעה אשה רעה. כמה טובה אשה טובה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מצא אשה מצא טוב\", אי בגוה משתעי קרא\u0004 \u0005[אם בה\u0006 עצמה כפשוטו \u0005מדבר הכתוב]\u0006 אם כן — \u0003כמה טובה אשה טובה, שהכתוב משבחה. אי\u0004 \u0005[אם]\u0006 \u0003בתורה משתעי קרא\u0004 \u0005[מדבר הכתוב]\u0006 והדבר נאמר בלשון משל, אף זה מלמדנו: \u0003כמה טובה אשה טובה, שהתורה נמשלה בה.\u0004 ולהיפך: \u0003כמה רעה אשה רעה — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ומוצא אני מר ממות את האשה\". אי בגוה משתעי קרא\u0004 \u0005[אם בה\u0006 כפשוטו \u0005מדבר הכתוב],\u0006 \u0003כמה רעה אשה רעה שהכתוב מגנה. אי\u0004 \u0005[אם]\u0006 \u0003בגיהנם משתעי קרא\u0004 \u0005[מדבר הכתוב]\u0006 בלשון משל — \u0003כמה רעה אשה רעה, שגיהנם נמשלה בה.\u0004","ועוד באותו ענין, נאמר: \u0003\"הנני מביא\u0004 אליהם \u0003רעה אשר לא יוכלו לצאת ממנה\"\u0004 (ירמיהו יא, יא) \u0003אמר רב נחמן אמר רבה בר אבוה: זו אשה רעה וכתובתה מרובה.\u0004 כיוצא בו על הכתוב: \u0003\"נתנני ה' בידי לא אוכל קום\"\u0004 (איכה א, יד) \u0003אמר רב חסדא אמר מר עוקבא בר חייא: זו אשה רעה וכתובתה מרובה. במערבא\u0004 (בארץ ישראל) \u0003אמרו\u0004 על פסוק זה: \u0003זה שמזונותיו תלוין בכספו,\u0004 שאין לו קרקע משלו, והוא חייב לקנות את מזונותיו בכסף וחושש כל הזמן שמא תתייקר התבואה או שלא תימכר תבואה בשוק.","נאמר: \u0003\"בניך ובנתיך נתנים לעם אחר\"\u0004 (דברים כח, לב), \u0003אמר רב חנן בר רבא אמר רב: זו אשת האב,\u0004 כלומר, אם חורגת. \u0003\"בגוי נבל אכעיסם\"\u0004 (שם לב), \u0003אמר רב חנן בר רבא אמר רב: זו אשה רעה וכתובתה מרובה. ר' אליעזר אומר: אלו המינים\u0004 הכופרים בה'. \u0003וכן הוא אומר\u0004 להוכיח שהכופר בה' נקרא \"נבל\": \u0003\"אמר נבל בלבו אין אלהים וגו'\"\u0004 (תהילים יד, א).","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \"בגוי נבל אכעיסם\" — \u0003אלו אנשי ברבריא ואנשי מרטנאי, שמהלכין ערומים בשוק. שאין לך משוקץ ומתועב לפני המקום יותר ממי שמהלך בשוק ערום. ר' יוחנן אמר: אלו חברים,\u0004 כהני האש הפרסיים שהיו בפרס ובבל. ומסופר: \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן: אתו חברי\u0004 \u0005[באו חברים]\u0006 גם \u0003לבבל, שגא\u0004 \u0005[הזדעזע]\u0006 ו\u0003נפל\u0004 מכסאו מרוב צער על היהודים המצויים שם. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 יש דרך להמתיק את הגזירה כי הם \u0003מקבלי שוחדא\u0004 \u0005[מקבלים שוחד],\u0006 \u0003תריץ יתיב\u0004 \u0005[התיישר\u0006 ו\u0005ישב\u0006 במקומו\u0005]\u0006 שיש תקנה כל שהיא לצרה זו.","כיון שהוזכרו החברים, מביאים מה שאמרו חכמים: \u0003גזרו על שלשה מפני שלשה.\u0004 כלומר, החברים גזרו על היהודים בני בבל שלושה דברים, מפני שלוש עבירות שהיו בהם. \u0003גזרו על הבשר\u0004 לבטל את השחיטה — \u0003מפני המתנות,\u0004 על שאין נותנים מתנות כהונה (זרוע לחיים וקיבה) לכהנים, \u0003גזרו על המרחצאות\u0004 שלא ירחצו בהם יהודים — \u0003מפני הטבילה\u0004 שהיו מזלזלים בה.","\u0003קא מחטטי שכבי\u0004 \u0005[מחטטים\u0006 ומוציאים את ה\u0005מתים]\u0006 מקבריהם — \u0003מפני ששמחים\u0004 היהודים \u0003ביום אידם\u0004 (יום חגם) של הגויים. \u0003שנאמר: \"והיתה יד ה' בכם ובאבותיכם\"\u0004 (שמואל א' יב, טו). \u0003אמר רבה בר שמואל: זו חטוטי שכבי\u0004 \u0005[חיטוט\u0006 בעצמות \u0005מתים]\u0006 שהוא דבר הגורם צער לחיים וגם למתים. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בעון חיים\u0004 — \u0003מתים מתחטטין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מארי: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"לא יאספו ולא יקברו לדמן על פני האדמה יהיו\"\u0004 (ירמיהו ח, ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ונבחר מות מחיים\"\u0004 (שם ג), ואם המוות יהיה מגונה כל כך שאפילו לא יניחו את גוייתו של המת בשלום, איך אם כן נבחר המוות מחיים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין הדבר מתייחס למצב זה, אלא בא לומר: \u0003נבחר מות לרשעים\u0004 מחייהם, שמוטב \u0003שלא יחיו בעולם הזה ויחטאו, ו\u0004כתוצאה מכך \u0003יפלו בגיהנם.\u0004","אגב אותם דברים שדיברנו על הנשים מביאים, \u0003כתוב בספר בן סירא: \"אשה טובה מתנה טובה לבעלה\"\u0004 (בן סירא פרק כו) \u0003וכתיב\u0004 \u0005[ונאמר\u0006 שם\u0005]:\u0006 \u0003\"טובה בחיק ירא אלהים תנתן\"\u0004 (שם). ונאמר שם: \u0003\"אשה רעה צרעת\u0004 היא \u0003לבעלה\". מאי תקנתיה\u0004 \u0005[מה תקנתו] —\u0006 \u0003\"יגרשנה ויתרפא מצרעתו\"\u0004 (שם). \u0003\"אשה יפה — אשרי בעלה, מספר ימיו כפלים\"\u0004 (שם), שמתוך הנאתו מיופיה הרי זה כאילו חי כפליים.","\u0003\"העלם עיניך מאשת חן\u0004 הנשואה לאחר \u0003פן תלכד במצודתה. אל תט\u0004 (תהיה סמוך) \u0003אצל בעלה למסוך עמו\u0004 (לשתות איתו) \u0003יין ושכר,\u0004 כי הדבר יכול לגרום לפיתוי \u0003כי ב\u0004גלל \u0003תואר אשה יפה רבים הושחתו, ועצומים כל הרוגיה\"\u0004 (שם פרק ט). ועוד נאמר שם: \u0003\"רבים היו פצעי רוכל\",\u0004 כלומר, האדם ההולך ממקום למקום ומוכר תכשיטי נשים ומתוך שעוסק עמהן מכים ופוצעים אותו הבעלים. \u0003\"המרגילים\u0004 עצמם \u0003לדבר ערוה — כניצוץ מבעיר גחלת. ככלוב מלא עוף\u0004 — \u0003כן בתיהם\u0004 של הרוכלים \u0003מלאים מרמה\"\u0004 (שם פרק יא).","ועוד נאמר שם: \u0003\"אל תצר צרת מחר,\u0004 כלומר, אל תדאג בשל צרה העלולה לבוא מחר, \u0003כי לא תדע מה ילד יום — שמא מחר בא ו\u0004אותו אדם שהצטער \u0003איננו,\u0004 שמת, ו\u0003נמצא\u0004 שהיה \u0003מצטער על העולם שאין שלו\u0004 (שם פרק ל). \u0003מנע רבים מתוך ביתך,\u0004 שלא יבואו רבים לשם, \u0003ולא הכל תביא ביתך,\u0004 גם מאלה שהם ידידיך, אבל דאג כי \u0003רבים יהיו דורשי שלומך\u0004 והרבה לך ידידים. \u0003\"גלה סוד לאחד מאלף\"\u0004 (שם פרק ה), שרוב בני האדם אינם יודעים לשמור סוד.","\u0003אמר ר' אסי: אין בן דוד בא עד שיכלו כל הנשמות שבגוף,\u0004 כל הנשמות העתידות להיוולד בגופים, \u0003שנאמר: \"כי רוח מלפני יעטוף ונשמות אני עשיתי\"\u0004 (ישעיה נז, טז). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: כל מי שאין עוסק בפריה ורביה — כאילו שופך דמים, שנאמר: \"שפך דם האדם באדם דמו ישפך\"\u0004 (בראשית ט, ו), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 מיד \u0005אחריו]\u0006 כהסבר לדבר: \u0003\"ואתם פרו ורבו\"\u0004 (שם).","\u0003ר' יעקב אומר:\u0004 מי שאינו עוסק בפריה ורביה \u0003כאילו ממעט הדמות\u0004 של הקדוש ברוך הוא, \u0003שנאמר: \"כי בצלם אלהים עשה את האדם\"\u0004 (שם ו), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 מיד \u0005אחריו]:\u0006 \u0003\"ואתם פרו\u0004 ורבו \u0003וגו'\". בן עזאי אומר: כאילו שופך דמים וממעט הדמות\u0004 גם יחד, \u0003שנאמר: \"ואתם פרו ורבו\"\u0004 שה־ו' בראש המלה באה לצרף את הדברים יחד.","\u0003אמרו לו לבן עזאי: יש נאה דורש ונאה מקיים\u0004 מה שדורש, ויש \u0003נאה מקיים ואין נאה דורש, ואתה נאה דורש\u0004 על הצורך לעסוק בפריה ורביה, \u0003ואין נאה מקיים\u0004, שבן עזאי לא היה נשוי. \u0003אמר להן בן עזאי: ומה אעשה שנפשי חשקה בתורה\u0004 ואינני רוצה להתעסק בכל נושא אחר, שכן \u0003אפשר לעולם שיתקיים על ידי אחרים,\u0004 והם יעסקו בפריה ורביה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בדומה לזו, \u0003ר' אליעזר אומר: כל מי שאין עוסק בפריה ורביה כאילו שופך דמים, שנאמר: \"שפך דם האדם\" וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"ואתם פרו\u0004 ורבו \u0003\". ר' אלעזר בן עזריה אומר: כאילו ממעט הדמות. בן עזאי אומר:\u0004 כאילו עשה את שתיהן שפיכת דמים והמעטת הדמות. ו\u0003אמרו לו לבן עזאי: יש נאה דורש וכו'.\u0004","ובאותו ענין של פריה ורביה \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"ובנחה יאמר שובה ה' רבבות אלפי ישראל\"\u0004 (במדבר י, לו) —"],["\u0003מלמד שאין השכינה שורה על פחות משני אלפים ושני רבבות מישראל,\u0004 שהרי נאמר \"רבבות\" ומיעוט רבבות שתיים, וכן \"אלפי\" — מיעוט אלפים שנים, ואם כן, \u0003הרי שהיו ישראל שני אלפים ושני רבבות חסר אחד, וזה לא עסק בפריה ורביה — לא נמצא זה גורם לשכינה שתסתלק מישראל?!\u0004 שהרי, כאמור, הדבר תלוי במספר!","\u0003אבא חנן אמר משום ר' אליעזר:\u0004 הנמנע מפריה ורביה \u0003חייב מיתה, שנאמר\u0004 בבני אהרן: \u0003\"\u0004וימת נדב ואביהוא... \u0003ובנים לא היו להם\"\u0004 (במדבר ג, ד), \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003היו להם בנים — לא מתו. אחרים אומרים:\u0004 הנמנע מפריה ורביה \u0003גורם לשכינה שתסתלק מישראל, שנאמר: \"להיות לך לאלהים ולזרעך אחריך\"\u0004 (בראשית יז, ז) \u0003בזמן ש\"זרעך אחריך\" — שכינה שורה, אין \"זרעך אחריך\" — על מי שורה\u0004 השכינה? וכי \u0003על העצים ועל האבנים?\u0004 ואם כן גורם לסילוק שכינה באופן זה, שאין מי שתשרה שכינה עליו.","\u0003נשא אשה ושהה עמה עשר שנים ולא ילדה — אינו רשאי לבטל\u0004 עוד מפריה ורביה, אלא יגרשנה או ישא אחרת עמה. אם \u0003גירשה — מותרת לינשא לאחר,\u0004 ואין אומרים שדווקא בגללה לא היו להם ילדים. \u0003ו\u0004אם אף לשני לא ילדה — \u0003רשאי השני לשהות עמה עשר שנים. ואם הפילה — מונה\u0004 עשר שנים \u0003משעה שהפילה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשא אשה ושהה עמה עשר שנים ולא ילדה — יוציא\u0004 (יגרש) \u0003ויתן כתובה, שמא לא זכה להבנות ממנה,\u0004 מפני שלא ברור שהדבר תלוי בה, כי שמא אין הזיווג ביניהם יפה לפריה ורביה.","\u0003אף על פי שאין ראיה לדבר\u0004 לענין משך זמן זה, יש \u0003זכר לדבר,\u0004 שנאמר: \"ותקח שרי אשת אברם את הגר המצרית שפחתה \u0003מקץ עשר שנים לשבת אברם בארץ כנען\u0004 ותתן אותה לאברם אישה לו לאשה\" (בראשית טז, ג), שאחרי עשר שנים שלא ילדה — נשא אשה אחרת. ו\u0003ללמדך\u0004 אגב כך \u0003שאין ישיבת חוץ לארץ עולה לו מן המנין,\u0004 שהרי השנים שבהן אברהם ושרה חיו יחד קודם לכן, אינן נמנות להם. \u0003לפיכך,\u0004 אם \u0003חלה הוא או שחלתה היא\u0004 במשך הזמן, \u0003או\u0004 שהיו \u0003שניהם חבושים בבית האסורים\u0004 בנפרד, שאינם יכולים לקיים פריה ורביה — \u0003אין עולין לו מן המנין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ולילף\u0004 \u0005[ונלמד]\u0006 \u0003מיצחק\u0004 שיעור זמן שהוא גדול יותר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי יצחק בן ארבעים שנה בקחתו את רבקה\"\u0004 (שם כה, כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויצחק בן ששים שנה בלדת אתם\"\u0004 (שם כו), משמע שיכול לשהות עשרים שנה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יצחק\u0004 אבינו ידע כי \u0003עקור\u0004 (עקר) \u0003היה,\u0004 וכיון שהדבר אינו תלוי בה לא היתה לו סיבה לשאת אשה אחרת.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הלא \u0003אברהם נמי\u0004 \u0005[גם כן]\u0006 \u0003עקור היה\u0004 כפי שאנחנו יודעים ממדרשים אחרים! אלא, הכתוב \u0003ההוא\u0004 המתייחס לזמן שנולדו יעקב ועשו \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לא ללמדנו ענין הזמן שממתין אדם עד שתלד אשתו, אלא \u0003לכ\u0004 מו שאמר \u0003ר' חייא בר אבא.\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: למה נמנו שנותיו של ישמעאל\u0004 שאינו מענין סיפור התורה — \u0003כדי לייחס בהן שנותיו של יעקב.\u0004 כפי שמבואר אפשר ללמוד את מהלך חייו של יעקב מתוך המאורעות הקשורים בחיי ישמעאל, ולשם מנין השנים נחוץ גם הפסוק המספר מתי נולד יעקב. ואילו מן הכתוב באברהם למדים את הזמן של עשר שנים שממתינים בשביל ילדים.","\u0003אמר ר' יצחק: יצחק אבינו עקור\u0004 (עקר) \u0003היה, שנאמר: \"ויעתר יצחק לה' לנכח אשתו\"\u0004 (שם כא) — \u0003\"על אשתו\" לא נאמר,\u0004 משום שלא רק היא היתה עקרה, \u0003אלא \"לנכח\"\u0004 (ממול, כנגד ובמקביל) — \u0003מלמד ששניהם עקורים\u0004 (עקרים) \u0003היו.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע נאמר \u0003\"ויעתר לו\"? \"ויעתר להם\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר! ומשיבים: ההיעתרות היתה תלויה בו, \u0003לפי שאינו דומה תפלת צדיק בן צדיק\u0004 כיצחק בן אברהם, \u0003לתפלת צדיק בן רשע\u0004 כרבקה בת בתואל.","\u0003אמר ר' יצחק: מפני מה היו אבותינו עקורים\u0004 בתחילה — \u0003מפני שהקדוש ברוך הוא מתאוה לתפלתן של צדיקים,\u0004 ורצה שירבו בתפילה לפניו על בנים. ואגב אותו ענין \u0003אמר ר' יצחק: למה נמשלה תפלתן של צדיקים כעתר\u0004 (רחת), כפי שנאמר \"ויעתר\" — ללמדנו: \u0003מה עתר זה מהפך התבואה ממקום למקום, כך תפלתן של צדיקים מהפכת מדותיו של הקדוש ברוך הוא ממדת רגזנות למדת רחמנות. אמר ר' אמי: אברהם ושרה טומטמין היו\u0004 מתחילה, שלא היו להם אפילו אברי מין ראויים, \u0003שנאמר: \"הביטו אל צור\u0004"],["\u0003חצבתם ואל מקבת בר נקרתם\"\u0004 (ישעיהו נא, א) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 פסוק סמוך המבאר את הראשון, \u0003\"הביטו אל אברהם אביכם ואל שרה תחוללכם\"\u0004 (שם ב), ללמד שכאילו נעשו להם איברים (\"חוצבתם\" ו\"נוקרתם\") לאחר זמן.","\u0003אמר רב נחמן אמר רבה בר אבוה: שרה אמנו אילונית היתה\u0004 מתחילה, \u0003שנאמר: \"ותהי שרי עקרה אין לה ולד\"\u0004 (בראשית יא, ל), ומייתור המילים \"אין לה ולד\" למדים אנו שכוונתו ש\u0003אפילו בית ולד\u0004 (רחם) \u0003אין לה.\u0004","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לא שנו\u0004 ששוהה עשר שנים קודם קידושין \u0003אלא בדורות הראשונים, ששנותיהן\u0004 היו \u0003מרובות, אבל בדורות האחרונים, ששנותיהן מועטות\u0004 — שוהה \u0003שתי שנים ומחצה\u0004 ומגרשה, שהן \u0003כנגד\u0004 זמן של \u0003שלשה עיבורים. רבה אמר\u0004 בשם \u0003רב נחמן: שלש שנים\u0004 שוהה, \u0003כנגד שלש פקידות\u0004 שפקד הקדוש ברוך הוא את העקרות. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בראש השנה נפקדו שרה רחל וחנה,\u0004 ומכאן שיש להמתין עד שיעברו שלוש פעמים ראש השנה, כמספר הפקידות שנפקדו בו.","\u0003אמר רבה\u0004 הוא עצמו: \u0003ליתנהו להני כללי\u0004 \u0005[כללים אלה\u0006 שאמרנו \u0005אין\u0006 לקבלם\u0005]\u0006 כלומר, אין לקבל את הדברים הללו שאמרנו, ומדוע: \u0003מכדי מתניתין מאן תקין\u0004 \u0005[הרי\u0006 את \u0005משנתנו מי תיקן] —\u0006 \u0003רבי, והא\u0004 \u0005[והרי]\u0006 \u0003בימי דוד\u0004 כבר \u0003אימעוט שני\u0004 \u0005[נתמעטו השנים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ימי שנותינו בהם שבעים שנה\u0004 ואם בגבורות שמונים שנה\u0003\"\u0004 (תהלים צ, י), משמע שעד אז היו שנות בני אדם כמו שהם בימינו, והקביעה של עשר שנים היא איפוא אף לזמן הזה.","ושואלים על לשון הברייתא: \u0003והאי\u0004 \u0005[וזה]\u0006 הלשון \u0003\"שמא לא זכה להבנות הימנה\", ודלמא איהי\u0004 \u0005[ושמא היא\u0006 זו\u0005]\u0006 ש\u0003לא זכיא\u0004 \u0005[זכתה]\u0006 להיבנות? ומשיבים: \u0003איהי\u0004 \u0005[היא]\u0006 \u0003כיון\u0004 שהיא \u0003לא מפקדא\u0004 \u0005[מצווה]\u0006 על \u0003פריה ורביה,\u0004 הריהי \u0003לא מיענשה\u0004 \u0005[נענשת],\u0006 משמע שהזכות שבכך תלויה בו ולא בה.","לעצם דברי המשנה שצריך לשאת אשה בזקנתו שואלים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן הוא]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לר' אבא בר זבדא: נסיב איתתא ואוליד בני\u0004 \u0005[שא אשה והולד בנים]\u0006 \u0003ואמר להו: אי זכאי\u0004 \u0005[אילו הייתי זוכה\u0006 וראוי\u0005] —\u0006 \u0003הוו\u0004 \u0005[היו]\u0006 \u0003לי\u0004 כבר \u0003מקמייתא\u0004 \u0005[מתחילה],\u0006 ועכשיו בזקנותי, אינני רוצה לשאת אשה סתם, בלא להוליד. הרי משתמע מזה שאין מצוה לשאת אשה בימי זקנה. ומשיבים: \u0003התם דחוי קא מדחי להו לרבנן\u0004 \u0005[שם\u0006 רק \u0005דחה את החכמים],\u0006 שלא רצה לומר להם את טעמו האמיתי, משום שהיה עקר. שכן ידוע ש\u0003ר' אבא בר זבדא איעקר מפרקיה\u0004 \u0005[נעשה עקר מ\u0006חמת \u0005דרשתו]\u0006 של \u0003רב הונא,\u0004 שהיה מאריך בדרשותיו, ותלמידיו היו מתאפקים בחוזקה מהטלת מי רגליים כל משך הדרשה ודבר זה גרם להם לעקרות.","כיוצא בו מסופר ש\u0003רב גידל איעקר מפרקיה\u0004 \u0005[נעשה עקר מ\u0006חמת \u0005דרשתו]\u0006 של \u0003רב הונא.\u0004 וכן \u0003ר' חלבו איעקר מפרקיה\u0004 \u0005[נעשה עקר מ\u0006חמת \u0005דרשתו]\u0006 של \u0003רב הונא. רב ששת איעקר מפרקיה\u0004 \u0005[נעשה עקר מ\u0006חמת \u0005דרשתו]\u0006 של \u0003רב הונא.\u0004 ומסופר: \u0003רב אחא בר יעקב אחדתיה\u0004 \u0005[אחזה בו]\u0006 \u0003סוסכינתא\u0004 (מחלה מחמת עצירות השתן העשויה לגרום לעקרות), \u0003תליוה בארזא דבי\u0004 \u0005[תלו אותו בארז ש\u0006ב\u0005בית]\u0006 \u0003רב\u0004 לשם רפואה \u0003ונפק מיניה כהוצא ירקא\u0004 \u0005[ויצא ממנו כעלה תמר ירוק]\u0006 ונתרפא. \u0003אמר רב אחא בר יעקב: שיתין סבי הוינא\u0004 \u0005[ששים זקנים,\u0006 חכמים, \u0005היינו]\u0006 שם \u0003וכולהו איעקור מפרקיה\u0004 \u0005[וכולם נעשו עקרים מ\u0006חמת \u0005דרשתו]\u0006 של \u0003רב הונא לבר מאנא, דקיימי בנפשאי\u0004 \u0005[חוץ ממני, שקיימתי בעצמי]\u0006 את הכתוב \u0003\"החכמה תחיה בעליה\"\u0004 (קהלת ז, יב), והשתמשתי בדרך זו של ריפוי כדי שלא איעשה עקר.","שנינו במשנה שאשה ששהתה עשר שנים ולא ילדה, אם \u0003גירשה — מותרת\u0004 להינשא לשני, ושוהה אף עימו עשר שנים. ומעירים: \u0003שני — אין\u0004 \u0005[כן],\u0006 אולם אם אף לשני לא היו ילדים ממנה — ל\u0003שלישי לא\u0004 תינשא, משום שנראה שחזקתה שאינה מסוגלת ללדת.","ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי]?\u0006 כשיטת \u0003רבי היא,\u0004 שסבור ששתי פעמים הרי הן חזקה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003מלה\u0004 אשה את בנה \u0003הראשון ומת\u0004 מחמת המילה, ומלה את בנה ה\u0003שני ומת\u0004 גם הוא — \u0003שלישי לא תמול,\u0004 אלו \u0003דברי רבי,\u0004 שיש חזקה שילדיה מתים מחמת מילה. \u0003רבן שמעון בן גמליאל אומר: שלישי — תמול,\u0004 שעדיין אין חזקה שילדיה מתים, \u0003רביעי — לא תמול.\u0004","ושואלים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005להיפך]\u0006 שהופכת את השיטות, ואם כן \u0003הי מינייהו אחריניתא\u0004 \u0005[איזו מהן אחרונה],\u0006 כלומר, איזו מוסמכת יותר?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה לדבר ממה ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מעשה בארבע אחיות בצפורי שמלה\u0004 אחות \u0003ראשונה\u0004 את בנה \u0003ומת,\u0004 מלה אחות \u0003שניה\u0004 את בנה \u0003ומת,\u0004 מלה \u0003שלישית ומת, רביעית באת\u0004 (באה) \u0003לפני רבן שמעון בן גמליאל\u0004 בשאלה האם למול את בנה. \u0003אמר לה: אל תמולי.\u0004 משמע שרבן שמעון בן גמליאל הוא הסבור שרק שלוש פעמים מהוות חזקה.","ודוחים: משם אין ראיה, \u0003ודלמא אי אתיא\u0004 \u0005[ושמא אם\u0006 היתה \u0005באה]\u0006 ה\u0003שלישית נמי הוה אמר\u0004 \u0005[גם כן היה אומר]\u0006 \u0003לה,\u0004 אלא שלא באה, ולא יכול היה לומר לה את ההלכה. ושואלים: \u0003אם כן, מאי אסהדותיה\u0004 \u0005[מה עדותו]\u0006 של \u0003ר' חייא בר אבא?\u0004 שאם כן לא חידש לנו דבר בזה, שהרי עדיין איננו יודעים ממתי היא חזקה, ומה הטעם לספר את כל המעשה? ומשיבים: \u0003ודלמא הא קא משמע לן\u0004 \u0005[ושמא\u0006 דבר \u0005זה השמיע לנו]\u0006 ש\u0003אחיות מחזקות,\u0004 כלומר, שיש חזקה למחלה כגון זו גם על ידי אחיות, שלא רק אם מתו שלושת ילדיה של אותה אם יש חזקה, אלא גם אם היו הילדים מאחיות שונות, יש לחשוש לכך.","\u0003אמר רבא: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 כי \u0003אחיות מחזקות,\u0004 על כן מאותו טעם \u0003לא ישא אדם אשה לא ממשפחת נכפין\u0004 (חולים במחלת הנפילה) \u0003ולא ממשפחת מצורעים,\u0004 שיש לחשוש שהמחלה היא תורשתית ומצויה בכל בני המשפחה. ומעירים: \u0003והוא דאתחזק תלתא זימני\u0004 \u0005[שהוחזק\u0006 הדבר \u0005שלוש פעמים]\u0006 אצל שלושה אנשים מאותה המשפחה.","שואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 על ההלכה לענין חזקה? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל לבבל, \u0003אמר: עובדא הוה קמיה\u0004 \u0005[מעשה היה לפני]\u0006 \u0003ר' יוחנן בכנישתא\u0004 \u0005[בבית הכנסת]\u0006 של העיירה \u0003מעון ביום הכפורים שחל להיות בשבת, ומלה ראשונה\u0004 את בנה \u0003ומת\u0004 מחמת המילה, ומלה \u0003שניה\u0004 את בנה \u0003ומת,\u0004 וה\u0003שלישית באה לפניו. אמר לה: לכי ומולי,\u0004 שאין לחשוש לחזקה בשתי פעמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יצחק: \u0003חזי\u0004 \u0005[ראה,\u0006 שים לב\u0005],\u0006 למה שאתה אומר ודייק בדבריך, \u0003דקשרית איסורא וסכנתא\u0004 \u0005[ש\u0006הרי \u0005אתה מתיר\u0006 בכך גם \u0005איסור\u0006 וגם \u0005סכנה],\u0006 שהרי התיר את האיסור של מילה ביום הכיפורים, שאם אינו מחוייב בה נמצא שעובר על איסור לחינם וגם עשה מעשה שיש בו סכנת נפשות.","ומעירים: \u0003סמך עלה\u0004 \u0005[עליה]\u0006 \u0003אביי\u0004 על הלכה זו, \u0003ו\u0004עשה מעשה. \u0003אזל נסבה\u0004 \u0005[הלך\u0006 אביי ו\u0005נשא]\u0006 לאשה את \u0003חומה ברתא\u0004 \u0005[הבת]\u0006 של \u0003איסי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה, דנסבה\u0004 \u0005[שנשא אותה\u0006 תחילה\u0005]\u0006 \u0003רחבה דפומבדיתא ושכיב\u0004 \u0005[ומת],\u0006 ונשא אותה אחר כך \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר בר חנה ושכיב\u0004 \u0005[ומת],\u0006 \u0003ונסבה\u0004 \u0005[ו\u0006אחר כך \u0005נשא אותה]\u0006 \u0003הוא,\u0004 אביי, ולא חשש שמא הוחזקה אשה זו שהיא \"קטלנית\", שיש בה דבר הגורם לבעליה למות. וסמך על דברי רב יצחק שאין חזקה אלא בשלוש פעמים. \u0003ו\u0004בסופו של דבר גם הוא \u0003שכיב\u0004 \u0005[מת]\u0006 בעודו נשוי לה.","\u0003אמר רבא: ומי איכא דעביד עובדא בנפשיה כי האי\u0004 \u0005[והאם יש העושה מעשה בעצמו כמו זה],\u0006 כלומר, הסומך על מסורת זו, ונושא אשה שיש סכנה בנישואיה, \u0003והא איהו\u0004 \u0005[והלא הוא\u0006 עצמו\u0005]\u0006 זה ש\u0003אמר:\u0004 כל מה שאמר \u0003אבין\u0004 בשם ר' יוחנן, \u0003דסמכא\u0004 \u0005[\u0006הרי אפשר \u0005לסמוך\u0006 עליו\u0005],\u0006 וכל ענין שאומר \u0003יצחק סומקא\u0004 \u0005[האדום],\u0006 ר' יצחק בר יוסף, בשם ר' יוחנן — \u0003לאו בר סמכא\u0004 \u0005[לא בר סמיכה\u0006 עליו הוא\u0005].\u0006 ומסביר את ההבדל ביניהם: \u0003אבין ישנו בחזרה\u0004 שהוא חוזר לארץ ישראל ושומע אם חזרו בהם בני הישיבה, ואילו \u0003יצחק סומקא אינו בחזרה,\u0004 מאחר שירד לבבל ולא חזר לארץ. \u0003ועוד\u0004 יש לחשוש: \u0003אימר דפליגי\u0004 \u0005[אמור ש\u0006הם \u0005חלוקים]\u0006 \u0003לענין מילה\u0004 אם שתים או שלוש פעמים מהוות חזקה, אולם \u0003בנישואין מי פליגי\u0004 \u0005[האם\u0006 הם \u0005חלוקים]?\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ניסת\u0004 אשה \u0003לראשון ומת, לשני ומת, לשלישי — לא תנשא,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: לשלישי\u0004 — \u0003תנשא, לרביעי\u0004 — \u0003לא תנשא.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גבי\u0004 (אצל) \u0003מילה\u0004 אפשר להסביר מה טעמה של החזקה בזה: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003משפחה דרפי דמא\u0004 \u0005[שדמה רפה]\u0006 ואינו נקרש היטב ושותת בלי להיעצר \u0003ואיכא\u0004 \u0005[ויש]\u0006 \u0003משפחה דקמיט דמא\u0004 \u0005[שדמה נקרש],\u0006 \u0003אלא נישואין מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שנחשוש אפילו כשיש חזקה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבימי מהגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא: מעין גורם,\u0004 כלומר, יש איזה חולי באשה זו, שביאתה גורמת לבעליה למות. \u0003ורב אשי\u0004 עצמו \u0003אמר:\u0004 ה\u0003מזל\u0004 שלה הוא זה ש\u0003גורם\u0004 שבעליה מתים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]\u0006 אם הטעם הוא זה או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, כגון ש\u0003אירסה ומית\u0004 \u0005[ומת]\u0006 אחד מהם, לפני נישואין, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 ש\u0003נפל מדיקלא ומית\u0004 \u0005[מדקל ומת],\u0006 שאם החשש הוא בגלל הביאה — הרי במקרים אלה היה המוות מסיבות אחרות, ולדעת החוששים משום מזל — יש לחשוש גם כאן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרבא: בעי מיניה\u0004 \u0005[שאלתי ממנו]\u0006 \u0003מרב יוסף: הלכה כרבי? ואמר לי: אין\u0004 \u0005[כן].\u0006 ושאלתי אותו: \u0003הלכה כרבן שמעון בן גמליאל? ואמר לי: אין\u0004 \u0005[כן],\u0006 וכי \u0003אחוכי אחיך בי\u0004 \u0005[צחק עלי],\u0006 שהרי אמר לי דברים סותרים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא, סתמי היא\u0004 \u0005[סתמי\u0006 הלכה שונים \u0005הם]\u0006 \u0003ופשיט לך\u0004 \u0005[ופתר לך]\u0006 שצריך לפסוק הלכה פעם כשיטה זו ופעם כשיטה זו, והכלל לפי מה שסתמה המשנה בכל ענין. כיצד? \u0003נישואין ומלקיות\u0004 נסתמה בהם הלכה \u0003כרבי,\u0004 שבשתי פעמים היא חזקה. בענין \u0003וסתות ו\u0004בענין \u0003שור המועד — כרבן שמעון בן גמליאל,\u0004 שרק בשלוש פעמים היא חזקה.","ומסבירים את הפרטים: \u0003נישואין — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 \u0003מלקיות — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שלקה\u0004 מלקות מדין תורה \u0003ושנה\u0004 (וחזר ונתחייב ולקה) — \u0003בית דין כונסין אותו לכיפה\u0004 (לחדר=כלא סגור) \u0003ומאכילין אותו שעורין\u0004 שהוא מאכל שגורם לכך, \u0003עד שתהא כריסו נבקעת.\u0004 שאנחנו אומרים שאדם שחטא חטאים חמורים במזיד פעמיים, חזקה שיחטא פעם שלישית ולא די לו במלקות, אלא עוצרים אותו כדי שלא יחטא עוד, שחזקה שהוא רשע. \u0003וסתות — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין האשה\u0004"],["\u0003קובעת לה וסת\u0004 (זמן קבוע למחזור הדם החודשי שלה), שאפשר יהיה לסמוך שזהו זמן הופעתה הקבועה, \u0003עד שתקבענה שלש פעמים\u0004 ביום מסויים, ואז נעשית זאת חזקה. \u0003ואין מטהרת מן הוסת\u0004 שלא לחשוש ליום זה שמא ראתה בו דם \u0003עד שתעקר ממנה\u0004 וסת זו \u0003שלש פעמים\u0004 שלא ראתה דם בימים שהיתה רגילה לראות בהם. \u0003ושור המועד — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין השור נעשה מועד עד שיעידו בו\u0004 שנגח \u0003שלשה פעמים,\u0004 משמע שרק בשלוש פעמים נוצרת חזקה, כרבן שמעון בן גמליאל.","לענין נישואיה של אשה שלא היו לה בנים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ניסת לראשון ולא היו לה בנים, לשני ולא היו לה בנים,\u0004 ורוצה להינשא \u0003לשלישי — לא תנשא אלא למי שיש לו בנים,\u0004 שקיים כבר מצות פריה ורביה, שהרי יש לה כבר חזקה שאינה מסוגלת ללדת. \u0003נישאת למי שאין לו בנים\u0004 ולא הודיעה לו על חזקתה זו — \u0003תצא בלא כתובה,\u0004 שוודאי היו אלה נישואי טעות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003נישאת לשלישי ולא היו לה בנים\u0004 במשך עשר שנים, \u0003מהו דליתבעוה הנך קמאי\u0004 \u0005[\u0006האם יכולים \u0005לתבוע אותה אותם הראשונים]\u0006 שתחזיר להם את הכתובה שפרעו לה, משום מקח טעות? \u0003מי מצו אמרי\u0004 \u0005[האם\u0006 הם \u0005יכולים לומר]\u0006 \u0003לה: איגלאי מילתא דאת הוא דגרמת\u0004 \u0005[נתגלה הדבר\u0006 עכשיו \u0005שאת היא שגרמת]\u0006 שלא היו לנו ילדים. \u0003או דלמא מצית אמרה להו\u0004 \u0005[שמא יכולה\u0006 היא \u0005לומר להם]:\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דכחשי\u0004 \u0005[שכחשתי],\u0006 שאינני צעירה עוד כבתחילה, אבל אז היו יכולים להיות לי בנים מבעל אחר. ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003מצית אמרה להו\u0004 \u0005[יכולה לומר להם]:\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דכחשי\u0004 \u0005[שכחשתי].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 אם \u0003נישאת לרביעי, והיו לה בנים\u0004 ממנו, \u0003מהו דתיתבעיה\u0004 \u0005[שתתבענו]\u0006 \u0003לשלישי\u0004 שהוציא אותה בלא כתובה, ולומר לו: הרי הוכחה שלא בי היתה האשמה! ומשיבים: \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003לה: שתיקותיך\u0004 \u0005[שתיקתך]\u0006 \u0003יפה מדיבוריך\u0004 \u0005[מדיבורך],\u0006 כלומר, מוטב לך לשתוק ולא להעלות טענה זו. שאם תטען כך \u0003דמצי אמר\u0004 \u0005[שיכול\u0006 הוא \u0005לומר]\u0006 \u0003לה: אנא אדעתא דהכי\u0004 \u0005[אני על דעת כן]\u0006 שאת מסוגלת ללדת \u0003לא גרשתיך,\u0004 ועכשיו שאני יודע זאת — אני מתחרט על הגט, ונמצא הגט בטל ונישואיה לבעל הרביעי בטלים ובניה מן הרביעי ממזרים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: אי איהי שתקא, אנן מי שתקינן\u0004 \u0005[אם היא שותקת האם אנחנו שותקים],\u0006 כלומר, אם יש מקום לחשוש לפסול הגט, הרי החשש אינו נובע רק מחמת טענתה, אלא הוא בעיה לעצמה, ואם כן \u0003נמצא\u0004 ה\u0003גט בטל, ובניה\u0004 מבעלה האחרון \u0003ממזרין! אלא אמרינן\u0004 \u0005[אומרים אנו]\u0006 גם כנגד טענה זו: \u0003השתא הוא דברייתא\u0004 \u0005[עכשיו הוא שהבריאה],\u0006 כלומר, קודם לא היתה מסוגלת ללדת ועכשיו נשתנה גופה.","ובאותו ענין, \u0003הוא,\u0004 הבעל, \u0003אמר\u0004 כי האשמה לחוסר ילדים היא \u0003מינה\u0004 \u0005[ממנה]\u0006 \u0003והיא אמרה: מיניה\u0004 \u0005[ממנו],\u0006 שאיננו מסוגל לבעול כראוי. \u0003אמר ר' אמי:\u0004 ב\u0003דברים שבינו לבינה\u0004 כגון אלה — \u0003נאמנת\u0004 האשה. ומסבירים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מה\u0006 הוא\u0005]?\u0006 \u0003היא — קיימא\u0004 \u0005[מוחזק,\u0006 ברור\u0005]\u0006 \u0003לה\u0004 אם \u0003ב\u0004זמן ביאה הוא \u0003יורה כחץ, הוא — לא קים ליה\u0004 \u0005[מוחזק,\u0006 ברור \u0005לו]\u0006 אם הוא \u0003ב\u0004גדר \u0003יורה כחץ.\u0004","ואם במקרה כזה, \u0003אמר איהו\u0004 \u0005[הוא]:\u0006 \u0003איזיל אינסיב איתתא ואיבדוק נפשאי\u0004 \u0005[אלך אשא אשה\u0006 אחרת \u0005ואבדוק את עצמי]\u0006 אם אמנם הפגם הוא בי. \u0003אמר ר' אמי: אף בזו יוציא\u0004 את אשתו הראשונה \u0003ויתן כתובה. שאני אומר: כל הנושא אשה על אשתו — יוציא ויתן כתובה.\u0004 ואילו \u0003רבא אמר:\u0004 שומעים לו, כי לדעת רבא \u0003נושא אדם כמה נשים על אשתו\u0004 ואין בכך איסור, \u0003והוא דאית ליה למיזיינינהי\u0004 \u0005[שיש לו\u0006 כדי \u0005לפרנסן],\u0006 את כולן,"],["\u0003הוא אמר: אפלת בגו\u0004 \u0005[הפלת בתוך]\u0006 \u0003עשר\u0004 שנים, ולכן איננו רוצה עדיין לגרשה, שהרי נותר עוד זמן להשלים עשר שנים מעת הפלתה. \u0003והיא אמרה: לא אפלית\u0004 \u0005[הפלתי].\u0006 \u0003אמר ר' אמי: אף בזו היא נאמנת.\u0004 ומדוע? — ש\u0003אם איתא\u0004 \u0005[יש]\u0006 אמת בדבר ש\u0003הפילה — נפשה בעקרתא לא מחזקה\u0004 \u0005[לא\u0006 היתה \u0005מחזיקה את עצמה כעקרה],\u0006 שהרי יודעת היא, שעל ידי הכחשה זו היא מודיעה שעקרה היא.","\u0003הפילה, וחזרה והפילה, וחזרה והפילה — הוחזקה לנפלים,\u0004 שחזקתה שהיא מפילה תמיד. \u0003הוא,\u0004 הבעל, \u0003אמר: אפילה תרי\u0004 \u0005[הפילה שתים,\u0006 פעמיים\u0005]\u0006 \u0003והיא אמרה: תלת\u0004 \u0005[שלוש\u0006 פעמים\u0005],\u0006 \u0003אמר ר' יצחק בן אלעזר: עובדא הוה בי מדרשא\u0004 \u0005[מעשה\u0006 כזה \u0005היה ב\u0006בית \u0005המדרש]\u0006 שבאו לשאול, \u0003ואמרו: היא מהימנא\u0004 \u0005[נאמנת],\u0006 ש\u0003אם איתא\u0004 \u0005[יש]\u0006 אמת בדבר ש\u0003לא אפלה\u0004 \u0005[הפילה]\u0006 שלוש פעמים — \u0003נפשה בניפלי לא מחזקה\u0004 \u0005[לא\u0006 היתה \u0005מחזיקה עצמה כמפילה].\u0006","\u0003האיש מצווה על פריה ורביה, אבל לא האשה. ר' יוחנן בן ברוקה אומר:\u0004 אינו כן, אלא \u0003על שניהם הוא אומר: \"ויברך אתם אלהים ויאמר להם אלהים פרו ורבו\"\u0004 (בראשית א, כח).","\u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שאין האשה מצווה על פריה ורביה? \u0003אמר ר' אילעא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר בר' שמעון: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004פרו ורבו \u0003ומלאו את הארץ וכבשה\"\u0004 (שם), ללמדנו: \u0003איש דרכו לכבש ואין אשה דרכה לכבש.\u0004 ולכן מובן שכל ציווי זה וגם מצות פרו ורבו נאמר לאיש ולא לאשה.","ומקשים: \u0003אדרבה\u0004 (להיפך) \u0003\"וכבשה\" תרתי משמע\u0004 \u0005[שניים משמעה]\u0006 שהרי נאמר הדבר בלשון רבים, לשניים! \u0003אמר רב נחמן בר יצחק: \"וכבשה\" כתיב\u0004 \u0005[כתוב]\u0006 שהכתיב כאן הוא חסר. \u0003רב יוסף אמר, מהכא\u0004 \u0005[מכאן]\u0006 הראיה, שנאמר: \u0003\"אני אל שדי פרה ורבה\"\u0004 (שם לה, יא), \u0003ולא קאמר\u0004 \u0005[אמר]\u0006 \u0003\"פרו ורבו\".\u0004","כיון שהבאנו שמועה שנאמרה בדרך זו, מביאים עוד מאמר כזה, \u0003ואמר ר' אילעא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר בר' שמעון: כשם שמצוה על אדם לומר דבר הנשמע,\u0004 דבר שהוא יודע שישמעו ויקבלו ממנו — \u0003כך מצוה על אדם שלא לומר דבר שאינו נשמע,\u0004 שלא ידבר דבריו לריק. \u0003ר' אבא אומר: חובה\u0004 היא שלא לומר, \u0003שנאמר: \"אל תוכח לץ פן ישנאך הוכח לחכם ויאהבך\"\u0004 (משלי ט, ח).","\u0003ו\u0004עוד \u0003אמר ר' אילעא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר בר' שמעון: מותר לו לאדם לשנות\u0004 מן האמת \u0003בדבר השלום,\u0004 שאם יודע שהשינוי, השקר, יכול לעשות שלום — מותר לו לשנות. \u0003שנאמר: \"אביך צוה\u0004 לפני מותו לאמר. \u0003כה תאמרו ליוסף אנא שא נא\u0004 פשע אחיך וחטאתם כי רעה גמלוך\u0003\"\u0004 (בראשית נ, טז-יז), ואביהם לא ציווה כן, אלא שינו ואמרו בשמו דברים שלא אמר, מפני השלום.","\u0003ר' נתן אומר: מצוה\u0004 היא לשנות, \u0003שנאמר: \"ויאמר שמואל איך אלך ושמע שאול והרגני\"\u0004 (שמואל א' טז, ב), ועל כך אמר לו ה' שיאמר שהוא הולך להקריב קרבן (שם ג). משמע שאף הקדוש ברוך הוא מצווהו לעשות כן.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003גדול השלום, שאף הקדוש ברוך הוא שינה בו, דמעיקרא כתיב\u0004 \u0005[שמתחילה נאמר]\u0006 שאמרה שרה: \u0003\"ואדני זקן\"\u0004 (בראשית יח, יב), \u0003ולבסוף,\u0004 כאשר אמר ה' לאברהם מה אמרה שרה, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואני זקנתי\"\u0004 (שם יג), כדי שלא לגרום עלבון לאברהם ולגרום לסיכסוך בינו לבין שרה.","שנינו במשנה ש\u0003ר' יוחנן בן ברוקה אומר\u0004 שגם האשה מצווה על פריה ורביה. \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003ר' יוחנן ור' יהושע בן לוי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הלכה כר' יוחנן בן ברוקה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין הלכה כר' יוחנן בן ברוקה.\u0004","ומוסיפים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תתברר\u0005]\u0006 ש\u0003ר' יוחנן הוא\u0004 ש\u0003אמר\u0004 ש\u0003אין הלכה\u0004 כר' יוחנן בן ברוקה, וראיה לדבר: \u0003דיתיב\u0004 \u0005[שישב]\u0006 \u0003ר' אבהו וקאמר משמיה\u0004 \u0005[ואמר משמו]\u0006 של \u0003ר' יוחנן: הלכה\u0004 כר' יוחנן בן ברוקה, \u0003ואהדרינהו\u0004 \u0005[והחזירו]\u0006 \u0003ר' אמי ור' אסי\u0004 שישיבו לפניו \u0003לאפייהו\u0004 \u0005[את פניהם]\u0006 אחורנית, לרמוז שאין הדבר נכון. אף שלא אמרו זאת במפורש, מפני כבודו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 אותו ענין בגירסה אחרת: ש\u0003ר' חייא בר אבא אמר\u0004 זאת בשם ר' יוחנן, \u0003ואהדרינהו\u0004 \u0005[והחזירו]\u0006 \u0003ר' אמי ור' אסי לאפייהו\u0004 \u0005[את פניהם]\u0006 אחורנית. \u0003אמר רב פפא\u0004 לגבי בירור גירסות אלה: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003ר' אבהו אמרה,\u0004 מובן הדבר כי \u0003משום כבוד בי\u0004 \u0005[בית]\u0006 \u0003קיסר\u0004 שר' אבהו היה מקורב אליו \u0003לא אמרו ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום],\u0006 אלא שתקו, ורק רמזו שאינם מקבלים את דבריו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003ר' חייא בר אבא אמרה — לימרו ליה\u0004 \u0005[שיאמרו לו]\u0006 במפורש: \u0003לא אמר ר' יוחנן הכי\u0004 \u0005[כך].\u0006 ומכל מקום למדנו שגם תלמידי ר' יוחנן נחלקו מה היתה דעתו של רבם.","ושואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר ר' אחא בר חנינא אמר ר' אבהו אמר ר' אסי: עובדא הוה קמיה\u0004 \u0005[מעשה היה,\u0006 בא, \u0005לפני]\u0006 \u0003ר' יוחנן בכנישתא\u0004 \u0005[ב\u0006בית \u0005הכנסת]\u0006 של \u0003קיסרי,\u0004 באשה שבקשה להתגרש מבעלה אחרי עשר שנים שלא ילדה, \u0003ואמר: יוציא\u0004 הבעל \u0003ויתן כתובה,\u0004 כשהיה ברור שהאשה אינה יולדת בגללו. \u0003ואי סלקא דעתך לא מפקדה\u0004 \u0005[ואם עולה על דעתך\u0006 לומר \u0005שאינה מצווה] —\u0006 \u0003כתובה מאי עבידתה\u0004 \u0005[מה מעשיה],\u0006 כלומר, מדוע מגיעה לה כתובה?","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר שם \u0003ב\u0004מקרה שהיא \u0003באה מחמת טענה.\u0004 שלא באה האשה לתבוע גט משום קיום מצות פריה ורביה, אלא שהיא רוצה בנים מחמת טענה אחרת — טענתה זו יש בה ממש, וכופים את הבעל לגרש ולתת כתובה.","\u0003כי ההיא דאתאי לקמיה\u0004 \u0005[כמו\u0006 אשה \u0005אחת שבאה לפני]\u0006 \u0003ר' אמי\u0004 וביקשה להתגרש, מפני שבעלה אינו מסוגל להוליד. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כתובה! אמר לה: זיל, לא מיפקדת\u0004 \u0005[לכי, אינך מצווה]\u0006 על פריה ורביה! \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מסיבו דילה מאי תיהוי עלה דהך אתתא\u0004 \u0005[בזקנותה שלה מה יהא עליה,\u0006 על \u0005אשה זו]?\u0006 ועל עצמה אמרה, שאם לא יהיו לה בנים — מי ידאג לה לעת זקנותה. \u0003אמר: כי הא\u0004 \u0005[\u0006במקרה \u0005כמו זה] —\u0006 \u0003ודאי כפינן\u0004 \u0005[אנו כופים]\u0006 להוציא ולתת לה כתובה.","כעין זה מסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת שבאה לפני]\u0006 \u0003רב נחמן\u0004 לתבוע גט וכתובה מבעלה, בטענה שאינו מוליד. \u0003אמר לה: לא מיפקדת\u0004 \u0005[אינך מצווה]\u0006 על פריה ורביה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא בעיא הך אתתא חוטרא\u0004 \u0005[\u0006וכי \u0005אין צריכה אשה זו מקל]\u0006 \u0003לידה ומרה\u0004 \u0005[ומעדר]\u0006 \u0003לקבורה,\u0004 כלומר, שיהיו לה ילדים לתמוך בה בזקנותה ולטפל בה אחרי מותה? \u0003אמר: כי הא ודאי כפינן\u0004 \u0005[\u0006במקרה \u0005כמו זה ודאי אנו כופים]\u0006 להוציא.","מסופר: \u0003יהודה וחזקיה\u0004 בני ר' חייא \u0003תאומים היו,\u0004 אלא ש\u0003אחד נגמרה צורתו לסוף תשעה\u0004 חודשים להריון, \u0003ואחד נגמרה צורתו לתחלת שבעה,\u0004 ונולדו בהפסק זמן. \u0003יהודית, דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' חייא, הוה\u0004 \u0005[היה]\u0006 \u0003לה צער לידה\u0004 בגלל הלידות הבלתי־רגילות הללו, \u0003שנאי מנא\u0004 \u0005[שינתה\u0006 את \u0005בגדיה]\u0006 באופן שלא יכיר בה שהיא אשתו, \u0003ואתיא לקמיה\u0004 \u0005[ובאה לפני]\u0006 \u0003ר' חייא\u0004 לשאול אותו שאלה בהלכה, ו\u0003אמרה:\u0004 האם \u0003אתתא מפקדא\u0004 \u0005[אשה מצווה]\u0006 על \u0003פריה ורביה? אמר לה: לא. אזלא אשתיא סמא דעקרתא\u0004 \u0005[הלכה\u0006 ו\u0005שתתה סם עקרות]\u0006 שלא תלד יותר.","\u0003לסוף איגלאי מילתא\u0004 \u0005[נגלה הדבר]\u0006 שהיא היתה זו ששאלה, ושעשתה כפי שפסק. \u0003אמר לה: איכו ילדת לי חדא כרסא אחריתא\u0004 \u0005[ולואי היית יולדת לי עוד בטן אחת,\u0006 עוד זוג אחד של ילדים\u0005]\u0006 כמו אלה שילדה, שהיו ילדיו מוצלחים ביותר, ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003יהודה וחזקיה\u0004 החכמים בני ר' חייא \u0003אחי\u0004 \u0005[\u0006היו \u0005אחים\u0006 תאומים\u0005],\u0006 וכן \u0003פזי וטוי\u0004"],["\u0003אחוותא\u0004 \u0005[אחיות]\u0006 תאומות היו, ומבניהן יצאו אנשים גדולים.","ושואלים: \u0003ולא מיפקדי\u0004 \u0005[ו\u0006כי \u0005אין\u0006 הנשים \u0005מצוות]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אחא בר רב קטינא אמר רבי אמר רב יצחק: מעשה באשה אחת ש\u0004היתה \u0003חציה שפחה וחציה בת חורין\u0004 ולכן לא היתה יכולה להינשא לא לעבד ולא לבן חורין, \u0003וכפו את רבה\u0004 (האדון שלה) \u0003ועשאה בת חורין!\u0004 והאם אין זו הוכחה שכפו אותו כדי שתוכל לקיים מצות פריה ורביה? \u0003אמר רב נחמן בר יצחק:\u0004 לא זה היה הטעם לכפיית אדוניה לשחררה, אלא כיון שידעה שאיננה יכולה להינשא לא לעבד ולא לבן חורין התנהגה כך ש\u0003מנהג הפקר נהגו בה,\u0004 שהיתה מביאה אנשים לזנות איתה והכשילה את הרבים, וכדי להציל אותה ואותם מן החטא, כפו את האדון לשחררה.","","\u0003אלמנה\u0004 שנישאה \u0003לכהן גדול\u0004 שהיא אסורה עליו מן התורה, או \u0003גרושה\u0004 או \u0003חלוצה\u0004 שנישאה \u0003לכהן הדיוט,\u0004 אם \u0003הכניסה לו\u0004 בתוך נדונייתה \u0003עבדי מלוג\u0004 שאינם נעשים נכסי הבעל, אלא יש לו רק זכות ליהנות מעבודתם כמו מפירות (רווחים) של שאר נכסי מלוג, \u0003ועבדי צאן ברזל\u0004 שהם עבדים שקיבל הבעל על עצמו את האחריות למחירם והם נעשים על ידי זה כקניינו, במקרה כזה \u0003עבדי מלוג — לא יאכלו בתרומה\u0004 מכוח היותה נשואה לכהן, ואילו \u0003עבדי צאן ברזל — יאכלו.\u0004","\u0003ואלו הן עבדי מלוג:\u0004 אם התנו בני הזוג ביניהם ש\u0003אם מתו\u0004 העבדים — \u0003מתו לה,\u0004 כלומר, על חשבונה, \u0003ואם הותירו\u0004 ועלו במחירם — \u0003הותירו לה, אף על פי שהוא חייב במזונותן — הרי אלו לא יאכלו בתרומה. ואלו הן עבדי צאן ברזל:\u0004 אם התנו בני הזוג ביניהם ש\u0003אם מתו — מתו לו, ואם הותירו — הותירו לו, הואיל והוא חייב באחריותן\u0004 בכל מקרה — \u0003הרי אלו יאכלו בתרומה,\u0004 שהם נחשבים קניינו שלו ולא שלה.","\u0003בת ישראל שניסת לכהן\u0004 ונישואין אלה כשרים הם, \u0003והכניסה לו עבדים, בין עבדי מלוג בין עבדי צאן ברזל — הרי אלו,\u0004 כולם, \u0003יאכלו בתרומה. ובת כהן שניסת לישראל\u0004 בנישואין כשרים, אם \u0003הכניסה לו\u0004 לבעלה הישראלי \u0003עבדים, בין עבדי מלוג בין עבדי צאן ברזל — הרי אלו לא יאכלו בתרומה\u0004 אף על פי שקודם לכן היא ועבדיה אכלו בתרומה מכוח היותה בת כהן. שנינו במשנה, כי כאשר יש איסור בנישואין של הכהן, \u0003עבדי מלוג\u0004 של אשתו — \u0003לא יאכלו בתרומה.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003להוי\u0004 \u0005[שיהא]\u0006 הדבר \u0003כ\u0004מו \u0003קנינו שקנה קנין! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין לכהן שנשא אשה וקנה עבדים שיאכלו\u0004 כולם \u0003בתרומה — שנאמר: \"וכהן כי יקנה נפש קנין כספו הוא יאכל בו\"\u0004 (ויקרא כב, יא).","","\u0003ומנין לאשה\u0004 שהיא אשת כהן \u0003שקנתה עבדים, ו\u0004כן \u0003עבדיו\u0004 של כהן \u0003שקנו עבדים, שיאכלו\u0004 גם הם \u0003בתרומה — שנאמר: \"וכהן כי יקנה נפש קנין כספו הוא יאכל בו\",\u0004 ומייתור המילים \"קנין כספו\" דורשים: \u0003קנינו שקנה קנין — אוכל.\u0004 ואף כאן, כיון שעבדי מלוג שייכים לאשת הכהן והיא עצמה נחשבת כקניינו — יכולים הם לאכול כקנין קניינו של כהן!","ומשיבים, הכלל הוא: \u0003כל האוכל — מאכיל,\u0004 כלומר, מי שהוא עצמו ראוי לאכול בתרומה — יכול להאכיל גם אחרים בתרומה מכוחו, \u0003כל שאין אוכל — אינו מאכיל.\u0004 וכיון שהאשה עצמה אינה אוכלת בתרומה משום נישואיה הפסולים — אף עבדיה אינם אוכלים בתרומה.","ומקשים: \u0003ולא,\u0004 האם מי שאינו אוכל אינו מאכיל? \u0003והרי\u0004 כהן \u0003ערל\u0004 (שלא נימול מחמת סכנה), שאסור בתרומה, \u0003ו\u0004כן \u0003כל\u0004 הכהנים \u0003הטמאים שאינן אוכלין\u0004 בתרומה — \u0003ו\u0004מכל מקום \u0003מאכילין\u0004 הם את נשיהם ועבדיהם! ומשיבים: יש לחלק, כי \u0003התם\u0004 \u0005[שם]\u0006 במקרים אלה הטעם שאינם אוכלים אינו משום שנפסלו מקדושת כהונה, אלא משום שרואים אותם כאילו \u0003פומייהו כאיב להו\u0004 \u0005[פיהם כואב להם]\u0006 ואינם מסוגלים למעשה לאכול, אבל יש להם זכות אכילה שאיננה יכולה להתממש מסיבה חיצונית ולכן הם מאכילים אחרים. מה שאין כן באשה זו שנישואיה פסולים, אין לה כלל זכות אכילה בתרומה, ולכך גם אינה יכולה להאכיל עבדיה. ומקשים: \u0003והרי\u0004 אם יש לה צאצאים מן הכהן אף על פי שאותו צאצא הוא ישראל, ואפילו \u0003ממזר,\u0004 וכגון שנישאה בת ישראל לכהן ונולדה לה בת, ואותה בת נישאה לישראל, ואפילו ממזר, ונולד לה בן ומתה, שלמרות שהצאצא הזה אינו אוכל בתרומה שהרי הוא ישראל, מכל מקום, אם אמו, כיון שיש לה זרע כלשהו מן הכהן — עדיין היא אוכלת בתרומה. הרי שהילד הזה אף על פי \u0003ש\u0004הוא עצמו \u0003אין אוכל\u0004 בתרומה, מכל מקום הריהו \u0003מאכיל\u0004 אחרים, הרי שגם מי שאינו אוכל, מאכיל!","","\u0003אמר רבינא:\u0004 יש לפרש את הכלל הזה ולומר כך: \u0003קנין אוכל קאמר\u0004 \u0005[אמר],\u0006 כלומר, אם ה\u0003קנין\u0004 של הכהן \u0003אוכל\u0004 בעצמו — \u0003מאכיל\u0004 גם אחרים שהם קניינו, וקנין כהן \u0003שאינו אוכל,\u0004 כגון אשתו הפסולה — \u0003אינו מאכיל.\u0004","\u0003ורבא אמר\u0004 הסבר אחר: \u0003מדאורייתא מיכל אכלי\u0004 \u0005[מן התורה\u0006 באמת \u0005אוכלים]\u0006 גם עבדי מלוג שלה, שהם כלולים בהגדרה של \"קניינו שקנה קנין\", \u0003ו\u0004אולם \u0003רבנן הוא דגזרי בהו\u0004 \u0005[חכמים הם שגזרו בהם]\u0006 שלא יאכלו, \u0003כדי שתאמר\u0004 אותה אשה שנישאה לכהן בעבירה: \u0003אני איני אוכלת\u0004 משלו, ו\u0003עבדי\u0004 גם הם \u0003אינם אוכלין\u0004 — אם כן \u0003זונה היא אצלו?! הלכך אתי לאפוקה\u0004 \u0005[על כן יבוא\u0006 בעלה \u0005להוציאה]\u0006 מביתו, והרי אנו רוצים שימהר לגרשה.","\u0003רב אשי אמר:\u0004 לא מטעם זה, אלא \u0003גזירה\u0004 היא: \u0003שמא תאכיל\u0004 את העבדים הללו גם \u0003לאחר מיתה\u0004 של בעלה הכהן, שאמנם כל עוד בעלה חי יכולים הם לאכול בתרומה, שהרי היא קניינו של הכהן, והם קניינה שלה. אבל לא לאחר מותו, שכוח קניינו ממנה בטל.","ומקשים: \u0003אלא מעתה,\u0004 שאנו גוזרים איסור על קנין אשת כהן בחייו משום לאחר מותו, גם \u0003בת ישראל שנשאת\u0004 נישואין כשרים \u0003לכהן לא תאכיל\u0004 עבדי מלוג שלה, \u0003גזירה שמא תאכיל\u0004 גם \u0003לאחר מיתה!\u0004","\u0003אלא אמר רב אשי:\u0004 כאן מדובר \u0003באלמנה\u0004 או גרושה \u0003כהנת,\u0004 כלומר, שהיא בת כהן, \u0003דאתיא לאורויי\u0004 \u0005[שתבוא להורות]\u0006 לעצמה היתר ותאמר: \u0003מעיקרא אכלי\u0004 \u0005[מתחילה אכלו]\u0006 העבדים שלי \u0003בתרומה דבי נשא\u0004 \u0005[של בית אבי],\u0006 \u0003אינסבי ליה להאי\u0004 \u0005[נישאתי לו לזה]\u0006 — \u0003אכלי\u0004 \u0005[אכלו]\u0006 \u0003בתרומה דגבראי\u0004 \u0005[של בעלי]\u0006 שהם כקנין שקנה קנין, \u0003והשתא הדרי לי למילתיה קמייתא\u0004 \u0005[\u0006ו\u0005עכשיו\u0006 כשמת בעלי \u0005חוזרת אני לדבר הראשון]\u0006 ושוב יאכלו בתרומת אבי. \u0003ולא ידעה\u0004 \u0005[ואינה יודעת]\u0006 שאינו כן, \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003לא שויתה לנפשה\u0004 \u0005[עשתה\u0006 את \u0005עצמה]\u0006 \u0003חללה,\u0004 שהרי קודם לכן כשרה היתה, ורשאית היתה לאכול. ואולם \u0003השתא\u0004 \u0005[עכשיו],\u0006 שנישאה בעבירה, \u0003שויתא לנפשה\u0004 \u0005[עשתה\u0006 את \u0005עצמה]\u0006 \u0003חללה,\u0004 ונאסרה לאכול, וממילא גם עבדיה אסורים.","ושואלים: אם כן, \u0003תינח\u0004 \u0005[נניח]\u0006 דבר זה לגבי \u0003אלמנה כהנת,\u0004 אבל אם היתה אותה \u0003אלמנה\u0004 שנישאה לכהן גדול \u0003בת ישראל, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אין מקום לגזירה זו! ומשיבים: \u0003באלמנותה\u0004 \u0005[באלמנות]\u0006 \u0003לא פליגי רבנן\u0004 \u0005[חילקו חכמים]\u0006 בין אלמנה לאלמנה, כיון שהיה מקרה שגזרו בו, עשו זאת כגזירה כללית.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003המכנסת שום לבעלה,\u0004 שהכניסה לבעלה בתוך כתובתה דברים מסויימים ששמו (העריכו אותם) ועשו אותם כנכסי צאן ברזל, ואחר כך כשבאה ליטול את כתובתה \u0003היא אומרת: כלי,\u0004 אותם כלים עצמם שהכנסתי, \u0003אני נוטלת, והוא אומר: דמים\u0004 (את מחירם) \u0003אני נותן,\u0004 שהוא רוצה להחזיק בכלים עצמם, \u0003הדין עם מי? רב יהודה אמר:\u0004"],["\u0003הדין עמה,\u0004 ותיטול את הכלים עצמם, \u0003ור' אמי אמר: הדין עמו\u0004 ויכול להחזיק בכלים ולשלם בעבורם.","ומפרשים: \u0003רב יהודה אמר\u0004 כי \u0003הדין עמה\u0004 — \u0003משום שבח בית אביה.\u0004 שכיון שהם שייכים למשפחתה, זלזול הוא בכבודם שיהיו ברשות אחר, ולכן \u0003דידה הוי\u0004 \u0005[שלה הם].\u0006 \u0003ר' אמי אמר: הדין עמו, כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנתנו: על עבדים שהכניסה לו כנכסי צאן ברזל ש\u0003אם מתו — מתו לו, ואם הותירו — הותירו לו, הואיל וחייב באחריותן — יאכלו\u0004 בתרומה, משמע שגופם נחשב קנוי לו, ומכאן מובן שקנין הבעל בנכסי צאן ברזל הוא קנין גופם של הדברים ולא ערכם בלבד, ולכן אינו חייב להחזיר לאשה אלא דמים. \u0003אמר רב ספרא: מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה \u0003\"והן שלו\"?\u0004 הלא רק \u0003\"הואיל וחייב באחריותן\" קתני\u0004 \u0005[שנה],\u0006 \u0003ולעולם\u0004 באמת \u0003לאו דידיה נינהו\u0004 \u0005[לא שלו הם].\u0006","ושואלים: \u0003וכל היכא\u0004 \u0005[היכן]\u0006 ש\u0003חייב באחריותן\u0004 של קנייניו \u0003אכלי\u0004 \u0005[אוכלים\u0006 הם\u0005]\u0006 \u0003בתרומה\u0004 ואין צורך בקנין גופם ממש? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ישראל ששכר פרה מכהן\u0004 שתעבוד אצלו — \u0003הרי זה יאכילנה כרשיני תרומה,\u0004 שהם מאכל בהמה שמפרישים מהם לעתים תרומה, וכיון שבהמת כהן אוכלת בתרומה — רשאי השוכר להאכיל את הבהמה הזו כרשיני תרומה. ואילו \u0003כהן ששכר פרה מישראל, אף על פי שמזונותיה עליו — לא יאכילנה כרשיני תרומה,\u0004 לפי שאינה שלו. והרי הכהן השוכר יש לו אחריות על הבהמה ששכר, ובכל זאת אינו מאכיל אותה תרומה!","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שזו קרויה אחריות שלימה? \u0003נהי נמי דמחייב\u0004 \u0005[אם אמנם גם כן שמחויב\u0006 הוא\u0005]\u0006 \u0003בגנבה ואבדה,\u0004 שאם נגנבה הבהמה או אבדה חייב להחזיר את דמי הבהמה, אבל \u0003באונסיה,\u0004 אם אירע בה אונס, שמתה או נפצעה, או \u0003בכחשה,\u0004 שרזתה או נחלשה מחמת סיבה כלשהי, \u0003ו\u0004כן \u0003בנפחת דמיה — מי מיחייב\u0004 \u0005[האם\u0006 הוא \u0005חייב]?\u0006 הרי שאין כאן אחריות שלימה, ולהיפך: \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא לסיפא\u0004 \u0005[לסופה]\u0006 של אותה משנה, ששנינו: \u0003ישראל ששם פרה מכהן,\u0004 כלומר, שקבע והעריך לה מחיר כששאל אותה ממנו, שאם תמות או תיפגע או מחירה ישתנה, יחזיר לו כפי ערכה בשעת לקיחה, ובאופן כזה \u0003לא יאכילנה כרשיני תרומה,\u0004 משום שהיא נחשבת כאילו היתה של ישראל. \u0003אבל כהן ששם פרה מישראל — יאכילנה כרשיני תרומה.\u0004 ולכאורה מכאן ראיה להיפך, שרק אם הוא חייב באחריות גמורה לשמור על ערך החפץ לעולם — הרי זה נחשב כבעלות כדי להתיר להאכילו תרומה.","\u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003רבה ורב יוסף בשילהי פרקיה\u0004 \u0005[בסוף דרשתו]\u0006 של \u0003רב נחמן ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה, ותניא כותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי.\u0004 ומפרטים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי: עבדי צאן ברזל יוצאין\u0004 לחירות \u0003בשן ועין\u0004 שהוציא להם האדון. וזהו דווקא \u0003לאיש,\u0004 כלומר, אם האיש, הבעל, עשה זאת, \u0003אבל לא לאשה.\u0004 ומכאן ראיה גמורה שגופם קנוי לאיש.","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה: המכנסת שום לבעלה\u0004 כלומר, שהכניסה לו נדוניה, כצאן ברזל, ששמו את ערכה, ואם יצטרך לשלם את כתובתה — יחזיר לפי ערך זה. \u0003אם רצה הבעל למכור — לא ימכור\u0004 אותם נכסים, משום שגופם של הנכסים שייך לה. \u0003ולא עוד אלא אפילו הכניס לה\u0004 הבעל \u0003שום משלו\u0004 שהוסיף מתנה משלו על הנדוניה שלה וקבעו לה ערך וצירפו אותה לנדוניה, \u0003אם רצה הבעל למכור — לא ימכור.\u0004 עברו \u0003ומכרו שניהם\u0004 או הבעל או האשה את החפצים הללו \u0003לפרנסה, זה היה מעשה לפני רבן שמעון בן גמליאל, ואמר:\u0004 אף על פי כן \u0003הבעל מוציא מיד הלקוחות,\u0004 משום שלשניהם אין רשות למכור בזמן ששניהם קיימים, והמכר בטל.","וסיכומה של ההלכה, \u0003אמר רבא אמר רב נחמן: הלכה כרב יהודה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: והתניא כותיה\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי!\u0004 אמר לו: \u0003אף על גב דתניא כותיה\u0004 \u0005[אף על פי ששנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי — מסתברא טעמא\u0004 \u0005[מסתבר טעמו]\u0006 של \u0003רב יהודה, משום שבח בית אביה.\u0004","מסופר: \u0003ההיא איתתא דעיילה ליה לגברא איצטלא דמילתא\u0004 \u0005[אשה אחת שהכניסה לבעלה גלימה של צמר מובחר]\u0006 \u0003בכתובתה\u0004 כנכסי צאן ברזל. \u0003שכיב\u0004 \u0005[מת]\u0006 אותו האיש, \u0003שקלוה יתמי ופרסוה אמיתנא\u0004 \u0005[לקחו היתומים אותה\u0006 גלימה \u0005ופרסו אותה על המת]\u0006 כעין תכריכים. ואחר כך תבעה האשה את הגלימה עצמה.","\u0003אמר רבא: קנייה מיתנא\u0004 \u0005[קנה אותה המת],\u0006 כלומר, היא נחשבת כשייכת לתכריכי המת, ודבר שניתן למת שוב אסור להשתמש בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003נאנאי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, לרב כהנא: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא אמר רב נחמן: הלכה כרב יהודה\u0004 משמע שגופם של נכסים אלה הם של האשה, ואיך היו היתומים רשאים לתת אותה למת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודה רב יהודה\u0004 שעל כל פנים נכסים אלה \u0003דמחוסר גוביינא\u0004 \u0005[מחוסרים גבייה]\u0006 ועדיין אינם ברשותה, ורק לכשתיטול כתובתה זכאית היא לקבלם. \u0003וכיון דמחוסר גוביינא\u0004 \u0005[ש\u0006הם \u0005מחוסרים גבייה]\u0006 — \u0003ברשותיה קאי\u0004 \u0005[ברשותו\u0006 הם \u0005עומדים]\u0006 לענין זה.","ומעירים: כי בענין זה \u0003רבא לטעמיה\u0004 \u0005[\u0006הולך \u0005לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: הקדש\u0004 שמקדיש אדם דבר, או איסור \u0003חמץ\u0004 שחל על דבר,"],["\u0003ושחרור\u0004 של עבד — \u0003מפקיעין מידי שעבוד,\u0004 שאם שיעבד חפץ מסויים לאדם אחר בחובו, ואחר כך הקדיש בעל החפץ את החפץ הזה, או שהיה הדבר המשועבד חמץ והגיע חג הפסח, או ששיחרר את העבד ששועבד לגביית החוב — הופקע השיעבוד, והמלווה יגבה את חובו ממקום אחר. ואף כאן, פריסת הגלימה על המת היא מעין הקדש, שהרי נאסרה על ידי כך בהנאה, ולכן היא מפקיעה מידי שיעבודה לאשה.","\u0003אמר רב יהודה: הכניסה לו\u0004 בכתובתה \u0003שני כלים,\u0004 שהיו \u0003ב\u0004שווי של \u0003אלף זוז, ושבחו\u0004 (ועלה מחירם) \u0003ועמדו על שני אלפים. אחד\u0004 מהם \u0003נוטלתו בכתובתה\u0004 (עם כתובתה), שהרי עכשיו שווה חפץ זה כדי תשלום הנדוניה שלה, שהוא אלף זוז, \u0003ואחד נותנת דמים\u0004 (משלמת מחירו) \u0003ונוטלתו\u0004 מבעלה, \u0003מפני שבח בית אביה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005] —\u0006 ש\u0003שבח בית אביה דידה הוי\u0004 \u0005[שלה הוא] —\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה רב יהודה\u0004 להלכה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת]\u0006 בלשון אחרת! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הני מילי היכא דמטיא למשקל\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום ש\u0006הדבר \u0005מגיע לקחת]\u0006 \u0003בכתובתה\u0004 שהוא שלה עכשיו, \u0003אבל מיתן דמי ומישקל\u0004 \u0005[לתת דמים ולקחת]\u0006 דבר שהוא בעצם לא שלה — \u0003לא,\u0004 שעד כדי כך אין מקפידים בגלל שבח בית אביה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם בזה אומרים שמשום שבח בית אביה יכולה לקחת את החפץ, אלא שצריכה לשלם עבורו.","\u0003בת ישראל שניסת לכהן ומת, והניחה מעוברת — לא יאכלו עבדיה בתרומה\u0004 כל זמן ההריון, \u0003מפני חלקו של עובר.\u0004 שכיון שהעובר יש לו חלק וזכות באותם עבדים שהוא יורש אותם, הרי הוא גורם שייאסר להם לאכול בתרומה, \u0003שהעובר פוסל,\u0004 בת כהן שנישאה לישראל ומת, והיה לה עובר ממנו, הרי הוא פוסל אותה מלאכול בתרומה. \u0003ואינו מאכיל\u0004 בתרומה לבת ישראל שנישאת לכהן, וכן אינו מאכיל את העבדים, אלו \u0003דברי ר' יוסי.\u0004","\u0003אמרו לו\u0004 חכמים: \u0003מאחר שהעדת לנו על בת ישראל לכהן\u0004 — אם כן \u0003אף בת כהן\u0004 שנישאה \u0003לכהן, ומת, והניחה מעוברת\u0004 — גם אז \u0003לא יאכלו עבדיה בתרומה, מפני חלקו של עובר\u0004 בעבדים, שכיון שהעובר פוסל ואינו מאכיל גם כאן אינו מאכיל.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005],\u0006 שאלה זו: האם \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יוסי\u0004 הוא \u0003משום דקסבר\u0004 \u0005[שהוא\u0006 \u0005סבור]\u0006 ש\u0003עובר\u0004 ש\u0003במעי זרה — זר הוא,\u0004 לפי שהוא חלק מגופה וכל עוד הוא עובר הרי הוא זר, ורק כשיוולד ייעשה כהן, ורק אז יוכלו אותם עבדים שיש לו חלק בהם לאכול בתרומה, — \u0003או דלמא\u0004 \u0005[שמא]\u0006 סבור ר' יוסי כי דווקא \u0003ילוד\u0004 (ילד שנולד) — \u0003מאכיל, שאינו ילוד — אינו מאכיל,\u0004 אף שאינו נחשב לזר?","\u0003למאי נפקא מינה\u0004 \u0005[ומה יוצא מזה]\u0006 מבירור טעמו של ר' יוסי — \u0003ל\u0004גבי השאלה של \u0003עובר במעי כהנת\u0004 (בת כהן) המעוברת מכהן, \u0003מאי\u0004 \u0005[מה]\u0006 דינו? שהרי אם העובר נחשב כחלק מגופה של האם — הרי עוברה של כהנת הוא ככהן, והטעם של זרות אינו קיים בו, אולם הטעם שצריך שיהיה ילוד עדיין קיים בו. \u0003אמר רבה: היינו טעמא\u0004 \u0005[זה הוא הטעם]\u0006 של \u0003ר' יוסי: דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003עובר במעי זרה — זר הוא. רב יוסף אמר,\u0004 הטעם הוא: כי \u0003ילוד — מאכיל, שאין ילוד — אינו מאכיל.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממשנתנו: \u0003אמרו לו לר' יוסי: מאחר שהעדת לנו על בת ישראל לכהן, בת כהן לכהן מהו? אמר להם: זו שמעתי, וזו לא שמעתי.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003עובר במעי זרה זר הוא — היינו דקאמר להו\u0004 \u0005[זהו שאמר להם]\u0006 \u0003\"זו שמעתי וזו לא שמעתי\",\u0004 ולכן יש הבדל בין ההלכות, שעוברה של בת כהן הנשואה לכהן — מאכיל בתרומה, שהרי אינו זר, אבל זה של בת ישראל אינו מאכיל. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם הוא ש\u0003ילוד מאכיל, שאין ילוד אין מאכיל — מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זו שמעתי וזו לא שמעתי\"?\u0004 הרי \u0003איהי היא\u0004 \u0005[היא היא\u0006 אותה ההלכה\u0005]!\u0006 ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 על רב יוסף.","\u0003אמר רב יהודה אמר שמואל:\u0004 הלכה \u0003זו — דברי ר' יוסי\u0004 היא. \u0003אבל חכמים אומרים: יש לו בנים — אוכלים\u0004 העבדים \u0003משום\u0004 ה\u0003בנים. אין לו בנים — אוכלים משום\u0004 ה\u0003אחים\u0004 של הכהן שיורשים אותו. \u0003אין לו אחים — אוכלים משום משפחה כולה\u0004 שהיא יורשת את נכסיו, אבל משום העובר אינם אוכלים והעובר גם אינו פוסלם, שעובר אינו יורש עדיין, ואין לו חלק בעבדים.","על דברי שמואל תוהים: כיון שאמר \u0003\"זו\"\u0004 דברי ר' יוסי, משמע מכאן לכאורה כי \u0003ולא סבירא ליה\u0004 \u0005[ו\u0006הוא \u0005אינו סבור\u0006 כך\u0005]\u0006 וקשה: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003פוק אייתי לי בי עשרה, דאימא לך באנפייהו\u0004 \u0005[צא הבא לי עשרה\u0006 אנשים, כדי \u0005שאומר לך בפניהם]\u0006 הלכה זו בפירסום גדול: \u0003המזכה לעובר — קנה.\u0004 שלדעת שמואל עובר יש לו קנין ויש לו זכיה, והיא היא שיטת ר' יוסי! ומשיבים: \u0003אלא\u0004 כוונת שמואל \u0003\"זו\u0004 דברי ר' יוסי \u0003\"\u0004\u0003וסבירא ליה\u0004 \u0005[ו\u0006כן \u0005סבור הוא\u0006 שמואל\u0005].\u0006 ו\u0003מאי קא משמע לן\u0004 \u0005[\u0006ו\u0005מה השמיע לנו]\u0006 שמואל בדבריו אלה — רק \u0003דפליגי רבנן עליה\u0004 \u0005[שחלוקים חכמים עליו]\u0006 על \u0003ר' יוסי.\u0004","ושואלים: \u0003ומי פליגי\u0004 \u0005[והאם\u0006 באמת \u0005חלוקים\u0006 הם\u0005]?\u0006 \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זכאי\u0004 מברייתא: \u0003זו עדות העיד ר' יוסי מפי שמעיה ואבטליון, והודו לו,\u0004 משמע שלא נחלקו עליו! \u0003אמר רב אשי: מי קתני\u0004 \u0005[האם שנה\u0006 שם\u0005]\u0006 \u0003\"וקבלו\"\u0004 ממנו? \u0003\"והודו לו\" קתני\u0004 \u0005[שנה]\u0006 וכוונתו: \u0003דמסתבר טעמיה\u0004 \u0005[שמסתבר טעמו],\u0006 אבל הם עצמם חלקו בדבר קודם לכן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הניח\u0004 הכהן שנשא בת ישראל \u0003בנים,\u0004 ומת — \u0003אלו ואלו\u0004 גם עבדי מלוג וגם עבדי צאן ברזל \u0003אוכלים\u0004 בתרומה. \u0003הניחה מעוברת\u0004 ולא הניח בנים — \u0003אלו ואלו אין אוכלים. הניח בנים, והניחה\u0004 כשהיא \u0003מעוברת\u0004 — \u0003עבדי מלוג\u0004 השייכים לה \u0003אוכלים כדרך שהיא אוכלת\u0004 (שממשיכה לאכול) משום בניה, \u0003עבדי צאן ברזל\u0004 ששייכים לבעל — \u0003לא יאכלו, מפני חלקו של עובר,\u0004 שהוא גם יורשם ועתיד להיות בעליהם. \u0003שהעובר פוסל ואינו מאכיל,\u0004 אלו \u0003דברי ר' יוסי.\u0004","\u0003ר' ישמעאל בר' יוסי אומר משום אביו:\u0004 אם השאיר אחריו הכהן ילדים ועובר יש הבדל: \u0003הבת — מאכלת\u0004 את עבדיו, אבל \u0003הבן — אינו מאכיל. ר' שמעון בן יוחי אומר:\u0004 אם היו בבניו של הכהן \u0003זכרים — יאכלו כולן\u0004 גם העבדים בשביל אותו זכר, ואם היו \u0003נקבות — לא יאכלו, שמא ימצא\u0004 ה\u0003עובר זכר, ואין לבנות במקום הבן\u0004 חלק בעבדים, כמו בירושה כולה \u0003כלום,\u0004 שהרי הוא היורש, והוא אינו יכול להאכיל.","ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003שמא ימצא\u0004 ה\u0003עובר זכר? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 אותה המסקנה ש\u0003נקבה נמי פסלה\u0004 \u0005[גם כן פוסלת],\u0006 שהרי אם שאר ילדיו הן נקיבות, הרי נקיבה זאת תקבל גם היא חלק בירושה, שבמקום שאין בן — בנות יורשות. ואם כן אף היא פוסלת מאותו טעם! ומשיבים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 \u0003ועוד\u0004 טעם נוסף \u0003קאמר\u0004 \u0005[אמר]\u0006 ולא פירש את כל טעמיו ודבריו; \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 ש\u0003נקבה נמי פסלה\u0004 \u0005[גם כן פוסלת],\u0006 \u0003ועוד, שמא ימצא עובר זכר — ואין לבנות במקום הבן כלום.\u0004","ר' שמעון אמר ש\u0003זכרים יאכלו,\u0004 ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003עובר\u0004 ושמא גם הוא זכר, ויש לו חלק בירושה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' שמעון:"],["\u0003אין חוששין למיעוטא\u0004 \u0005[למיעוט],\u0006 שהרי מתוך כלל העוברים רק מיעוט הנולדים הם זכרים, שכן יש בערך מחצית זכרים ומחצית נקיבות, ועוד חלק הם נפלים, נמצא שהילדים הזכרים הם רק מיעוט. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם קסבר\u0004 \u0005[סבור]\u0006 כי \u0003חוששין למיעוטא\u0004 \u0005[למיעוט],\u0006 אלא \u0003דעבדינן ליה תקנתא\u0004 \u0005[שעושים אנו לו תקנה]\u0006 לוולד הזה \u0003כ\u0004דברי \u0003רב נחמן אמר שמואל.\u0004","ש\u0003אמר רב נחמן אמר שמואל: יתומים\u0004 קטנים \u0003שבאו לחלוק בנכסי אביהם, בית דין מעמידין להם אפוטרופוס\u0004 לכל אחד ואחד, \u0003ובורר להם חלק יפה.\u0004 ולאחר ש\u0003הגדילו\u0004 היתומים — \u0003יכולין למחות\u0004 ולדרוש לחלוק מחדש. \u0003ורב נחמן דידיה\u0004 \u0005[משלו,\u0006 לא בשם שמואל\u0005]\u0006 \u0003אומר:\u0004 אם \u0003הגדילו — אין יכולין למחות,\u0004 ש\u0003אם\u0004 לא \u0003כן מה כח בית דין יפה.\u0004 ואף כאן, אפשר לזכות לעובר חלק מסויים מן הנכסים של אביו המת, ושאר העבדים ייחלקו לבנים הקיימים ויוכלו לאכול בתרומה. מה שאין כן כאשר כולם בנות, שמא יוולד זכר, ונמצא שהכל שייך לו.","כיון שתלינו את דברי ר' שמעון בסברתו של רב נחמן שואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שמה שאמר \u0003רב נחמן תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שר' שמעון סבור כמוהו, וחכמים חולקים על כך? ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא אית להו\u0004 \u0005[הכל,\u0006 כל הדיעות, \u0005יש להם,\u0006 מקבלים את דבריו\u0005]\u0006 של \u0003רב נחמן\u0004 לחלק את הנכסים חלוקה גמורה, שלא מדעת הקטנים ולהוציא את העבדים מחלקו של העובר. \u0003והכא\u0004 \u0005[וכאן]\u0006 רק \u0003ב\u0004שאלה של \u0003חוששין למיעוטא קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 כשלא חילקו את הנכסים.","ועוד בביאורה של אותה ברייתא, \u0003ר' ישמעאל בר' יוסי אומר משום אביו: הבת מאכילה, הבן אינו מאכיל.\u0004 ושואלים \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 ה\u0003בן\u0004 שהוא \u0003לא מאכיל — משום חלקו של עובר,\u0004 שמא יהא העובר זכר ויש לו חלק בנכסים, אם כן \u0003בת נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תאכיל, מפני חלקו של עובר.\u0004 ומדוע חילק בין דיניהם?","\u0003אמר אביי: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שיש \u0003נכסים מועטים\u0004 בירושה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 המספיקים רק לפרנס את הבנות עד שתגדלנה, ובמקרה כזה תיקנו חכמים שהבנות מקבלות את פרנסתן, והבנים אינם מקבלים דבר בירושה. \u0003וכגון דאיכא\u0004 \u0005[שיש]\u0006 כבר \u0003בן בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003בת\u0004 ואז","\u0003מה נפשך\u0004 \u0005[מה רצונך,\u0006 בכל מקרה\u0005]:\u0006 \u0003אי האי דמעברא\u0004 \u0005[אם זה, שמעוברת\u0006 בו\u0005]\u0006 \u0003בן הוא — לא עדיף\u0004 הוא \u0003מהאי דקאי\u0004 \u0005[מזה ש\u0006כבר \u0005עומד],\u0006 שהרי כמו שהבן הקיים אינו זוכה בנכסים המועטים — כך הבן שיוולד לא יהיה לו חלק בנכסים. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003בת היא, אמאי אכלה\u0004 \u0005[על מה,\u0006 בכוח מה, היא \u0005אוכלת] —\u0006 \u0003בתקנתא דרבנן\u0004 \u0005[ב\u0006כוח \u0005תקנת חכמים]\u0006 שתיקנו שהבנות יש להן זכות קדימה על פני הבנים בנכסים, אולם \u0003כמה\u0004 \u0005[כל עוד]\u0006 ש\u0003לא נפק\u0004 \u0005[יצא]\u0006 הוולד \u0003לאויר העולם לא תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 שתירש. לכן הבת הקיימת יכולה להאכיל את העבדים בתרומה, שרק היא יורשת אותם.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את הברייתא — \u0003בנכסים מועטים, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003שמא ימצא העובר זכר, ואין לבנות במקום בן כלום.\u0004 אולם במקרה שהעמדנו \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003נכסים מועטים — של ה\u0004\u0003בנות נינהו\u0004 \u0005[הם]!\u0006 ומשיבים: \u0003סיפא אתאן\u0004 \u0005[\u0006ב\u0005סופה\u0006 של הברייתא \u0005הגענו]\u0006 למקרה אחר, שאנחנו עוסקים בו ב\u0003נכסים מרובין.\u0004","ושואלים לגופו של דבר: \u0003ונכסים מועטים\u0004 האם של ה\u0003בנות נינהו\u0004 \u0005[הם]\u0006 כקנין גמור? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אסי אמר ר' יוחנן:\u0004 בנים \u0003יתומין שקדמו ומכרו בנכסים מועטים,\u0004 אף שהנכסים הללו היו צריכים לשמש לפרנסת הבנות — \u0003מה שמכרו מכרו,\u0004 שהרי מן התורה יורשים הם, ואין מוציאים מן הקונים מהם בשל תקנת חכמים. ואם כן מפני מה אומרים שבנכסים מועטים אין מתחשבים כלל בבנים?","\u0003ואלא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בת\" דקתני\u0004 \u0005[ששנה]\u0006 \"הבת מאכילה והבן אינו מאכיל\" — כוונתו \u0003אם\u0004. כלומר, \"בת\" במובן נקיבה, ומדובר בשני מקרים: שאמו של הילד מאכילה את עבדי מלוג שלה שאין ליורשים חלק בהם, והבן אינו מאכיל את עבדי צאן ברזל מפני חלקו של עובר. ושואלים: \u0003אי הכי, היינו\u0004 \u0005[אם כך הרי זו]\u0006 שיטת \u0003ר' יוסי\u0004 האמורה קודם, ומה הוסיף ושינה ר' ישמעאל בנו? ואומרים: אכן אם כל הברייתא \u0003כולה ר' ישמעאל בר' יוסי קתני לה\u0004 \u0005[שנה אותה]\u0006 ואין מחלוקת בדבר, אלא שבא להסביר מי הוא התנא ששנה ברייתא זו.","\u0003העובר\u0004 שהיתה אשת ישראל מעוברת בו, \u0003והיבם\u0004 שהיא \"שומרת\", ממתינה, לו, \u0003והאירוסין, והחרש\u0004 שקידש אשה, \u0003ובן תשע שנים ויום אחד\u0004 שבא עליה — אם היה אחד מכל אלה ישראל, הרי אלו \u0003פוסלין\u0004 מתרומה את מי שהיתה בת כהן. \u0003ו\u0004אף אחד מהם \u0003לא מאכילין\u0004 בתרומה אם היא ישראלית והם כהנים משום שאף לאחד מהם אין כוח שלם לקנות אותה.","\u0003ספק שהוא בן תשע שנים ויום אחד ספק שאינו,\u0004 שבא על אשה, או \u0003ספק הביא שתי שערות\u0004 ובוגר הוא, \u0003וספק שלא הביא,\u0004 ואירס אשה, וכן","\u0003נפל הבית עליו ועל בת אחיו\u0004 שהיתה גם אשתו, \u0003ואין ידוע אי זה מת ראשון\u0004 — מחמירים מספק ו\u0003צרתה חולצת ולא מתייבמת.\u0004 שאם היתה צרה לאותה אשה שהיא בתו של היבם, הרי הצרה רק חולצת אבל לא מתייבמת, שמא היא מתה אחריו וצרתה היא צרת ערוה, ואסורה באיסור אשת אח.","שנינו במשנה כי \u0003העובר\u0004 פוסל ואינו מאכיל. ומסבירים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בת כהן\u0004 הנשואה \u0003לישראל היא,\u0004 ומת בעלה, והיא נשארה מעוברת — \u0003פסיל לה\u0004 \u0005[פוסל אותה]\u0006 מלשוב ולאכול בתרומה של בית אביה, משום שנאמר: \"ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה ושבה אל בית אביה כנעוריה מלחם אביה תאכל\" (ויקרא כב, יג), שמה שנאמר \u0003\"כנעוריה\"\u0004 בא למעט: \u0003פרט למעוברת,\u0004 שכבר השתנתה ממה שהיתה בנעוריה. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003בת ישראל\u0004 הנשואה \u0003לכהן היא\u0004 ומת בעלה — \u0003לא מאכיל לה\u0004 העובר, כי \u0003ילוד\u0004 (ילד שנולד) — \u0003מאכיל, שאינו ילוד\u0004 — \u0003אינו מאכיל.\u0004","וכן \u0003היבם\u0004 פוסל ואינו מאכיל הוא בשני הצדדים. \u0003אי\u0004 \u0005[אם]\u0006 \u0003בת כהן\u0004 שנישאה \u0003לישראל היא,\u0004 ומת בעלה וממתינה ליבם ישראל שיחלוץ או ייבם אותה — \u0003פסיל לה\u0004 \u0005[פוסל אותה],\u0006 שנאמר: \u0003\"ושבה אל בית אביה\"\u0004 (שם) — \u0003פרט לשומרת יבם,\u0004 שאינה יכולה עדיין לשוב, משום שממתינה ליבם. \u0003אי\u0004 \u0005[אם]\u0006 \u0003בת ישראל\u0004 שנישאה \u0003לכהן היא\u0004 ומת בעלה והיבם כהן הוא — \u0003לא מאכיל לה,\u0004 משום ש\u0003\"קנין כספו\u0004 הוא יאכל בו\u0003\"\u0004 (שם יא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 הרי \u0003קנין\u0004 של \u0003אחיו הוא,\u0004 שהיבם איננו קונה אותה אלא מכוח אחיו.","\u0003והאירוסין\u0004 המוזכרים במשנה שאף הם פוסלים ולא מאכילים; \u0003אי\u0004 \u0005[אם]\u0006 \u0003בת כהן\u0004 שנתארסה \u0003לישראל היא — פסיל לה\u0004 \u0005[פוסל אותה]\u0006 הארוס"],["\u0003דהא קניה\u0004 \u0005[שהרי קנה אותה]\u0006 \u0003בהויה\u0004 (בקידושין), ומשעה זו נפסלה מבית אביה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בת ישראל\u0004 המאורסת \u0003לכהן היא\u0004 — \u0003לא מאכיל לה\u0004 בתרומה עדיין \u0003משום\u0004 הטעם של \u0003עולא,\u0004 שהסביר שמדין תורה ארוסת כהן אוכלת בתרומה, וגזרו חכמים שלא תאכל שמא תבוא להאכיל תרומה לבני משפחתה.","\u0003ו\u0004מה ששנינו במשנה בענין \u0003החרש\u0004 שפוסל מתרומה ואינו מאכיל, מסבירים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בת כהן\u0004 שנישאה \u0003לישראל\u0004 חרש \u0003היא — פסיל לה\u0004 \u0005[פוסל אותה]\u0006 על ידי נישואיו, \u0003דהא קניה בתקנתא דרבנן\u0004 \u0005[שהרי קנה אותה\u0006 מכוח \u0005תקנת חכמים],\u0006 כי אף שמן התורה אין תוקף לנישואי חרש, מכל מקום תיקנו חכמים שיוכל לשאת אשה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בת ישראל\u0004 שנישאה \u0003לכהן\u0004 חרש \u0003היא\u0004 — \u0003לא מאכיל\u0004 אותה בתרומה, כי \u0003\"קנין כספו\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 (ויקרא כב, יא) \u0003והאי\u0004 \u0005[וזה]\u0006 החרש \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בר קנין הוא,\u0004 שכיון שאין לו דעת, אינו יכול לקנות מדין תורה.","שנינו במשנה: \u0003\"ובן תשע שנים\u0004 ויום אחד — פוסלין ולא מאכילין\". \u0003קא סלקא דעתן\u0004 \u0005[עלה על דעתנו]\u0006 לומר, שכוונת המשנה \u0003בשומרת יבם לבן תשע\u0004 שנים \u0003ויום אחד.\u0004 ויש לברר: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נאמר הדבר? \u0003אי למיפסל\u0004 \u0005[אם\u0006 לענין \u0005לפסול]\u0006 אותה מלאכול בתרומה — יבם \u0003קטן,\u0004 פחות מבן תשע, \u0003נמי מיפסל פסיל\u0004 \u0005[גם כן פוסל]\u0006 שהרי היא זקוקה לו ואינה חוזרת לבית אביה, \u0003אי לאכולי\u0004 \u0005[אם להאכילה]\u0006 אותה בתרומה — יבם \u0003גדול נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מאכיל,\u0004 שהרי כבר אמרנו שהיבם אינו מאכיל בתרומה לפני שכנס את היבמה!","\u0003אמר אביי: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003ביבם בן תשע שנים ויום אחד הבא על יבמתו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 לא בשומרת יבם, אלא בנבעלה ליבם בן תשע שנים ויום אחד. \u0003דמדאורייתא קניא ליה\u0004 \u0005[שמ\u0006 דין \u0005תורה\u0006 היא \u0005קנויה לו],\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ומדאורייתא קניא ליה\u0004 \u0005[ומן התורה\u0006 היא \u0005קנויה לו]\u0006 \u0003וביאתו ביאה\u0004 מן התורה, \u0003אימא לוכיל\u0004 \u0005[אמור שיאכיל\u0006 אותה\u0005]\u0006 גם בתרומה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא ש\u0003עשו ביאת בן תשע שנים ויום אחד כמאמר בגדול\u0004 שקונה רק מדברי סופרים, ולכן אינה נקראת \"קנין כספו\", ואינו מאכיל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003סיפא דקתני\u0004 \u0005[סופה\u0006 של המשנה \u0005ששנה\u0006 בה\u0005]:\u0006 \u0003ספק בן תשע שנים ויום אחד ספק שאינו\u0004 — הרי זה פוסל ואינו מאכיל, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לפי פירושך זה שהוא \u0003ודאי בן תשע\u0004 שנים \u0003לא מאכיל\u0004 בביאתו, אם כן זה שאינו אלא \u0003ספק מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006","\u0003אלא אמר רבא:\u0004 לא בזה מדובר, אלא מדובר \u0003ב\u0004ביאת \u0003בן תשע שנים ויום אחד דהנך\u0004 \u0005[של אותם]\u0006 ה\u0003פסולים\u0004 המנויים במשנה \u0003קתני\u0004 \u0005[שנה],\u0006 אותם \u0003דפסלי\u0004 \u0005[שפוסלים]\u0006 \u0003בביאתן. וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003בן תשע שנים ויום אחד\u0004 שהיה \u0003גר עמוני\u0004 או \u0003מואבי\u0004 או \u0003מצרי\u0004 או \u0003אדומי,\u0004 או שהיה זה \u0003כותי\u0004 (שומרוני) או \u0003נתין\u0004 או \u0003חלל\u0004 או \u0003ממזר, שבאו על כהנת\u0004 או על \u0003לויה\u0004 או על \u0003ישראלית — פסלוה.\u0004 ואף משנתנו המדברת בבן תשע שנים ויום אחד — בפסולים אלה היא מדברת.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה בסופה\u0006 של המשנה, במשנה הבאה\u0005]:\u0006 \u0003אם אינן ראוין לבא בישראל — הרי אלו פוסלים, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005ראשה\u0006 של המשנה\u0005]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפסולים עסקינן\u0004 \u0005[עוסקים אנו]\u0006 אלא בכשרים! ומשיבים: לא כך יש לדייק, אלא \u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 שלנו מדובר ב\u0003פסולי קהל,\u0004 כלומר, אלה שפסולים מלבוא בקהל ישראל, ובקשר לזה הובאה ההלכה של בן תשע שנים ויום אחד, ואילו ב\u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף,\u0006 במשנה הבאה\u0005]\u0006 מדובר באלה שהם \u0003פסולי כהונה\u0004 בלבד ולכן היה צורך לחלק ביניהם.","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של הברייתא שהובאה קודם בחלקה, מביאים ומבררים את הברייתא כולה: \u0003בן תשע שנים ויום אחד\u0004 שהיה \u0003גר עמוני\u0004 או \u0003מואבי,\u0004 או \u0003מצרי\u0004 או \u0003אדומי,\u0004 או \u0003כותי,\u0004 או \u0003נתין\u0004 (מבני הגבעונים), או \u0003חלל,\u0004 או \u0003ממזר\u0004 ש\u0003באו על כהנת\u0004 (בת כהן) או \u0003לויה\u0004 או \u0003ישראלית\u0004 — \u0003פסלן\u0004 מלאכול בתרומה, אף לכשינשאו אחר כך לכהן.","\u0003ר' יוסי אומר\u0004 אין הדין כך לגמרי, אלא זה הכלל: \u0003כל שזרעו פסול,\u0004 כלומר, שיש בו פסול כזה שגם זרעו יהיה פסול — הרי הוא \u0003פוסל\u0004 בביאתו, ו\u0003כל שאין זרעו פסול — אינו פוסל\u0004 בביאתו. ואילו \u0003רבן שמעון בן גמליאל אומר\u0004 כלל אחר: \u0003כל שאתה נושא\u0004 את \u0003בתו — אתה נושא\u0004 אף את \u0003אלמנתו,\u0004 כלומר, כל שבתו מותרת לבוא בקהל — אין הוא פוסל את האשה שבא עליה, \u0003וכל שאין אתה נושא\u0004 את \u0003בתו — אי\u0004 \u0005[אין]\u0006 \u0003אתה נושא אלמנתו.\u0004 עד כאן לשון הברייתא. ומעתה מבררים אותה לפרטיה.","ותחילה בבירור ההלכה הכללית שאשה נפסלת לכהונה על ידי ביאת הפסול, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 \u0003אמר רב יהודה אמר רב, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ובת כהן כי תהיה לאיש זר\u0004 היא בתרומת הקדשים לא תאכל\u0003\"\u0004 (שם כב, יב), לומר: \u0003כיון שנבעלה לפסול לה,\u0004 שהוא \"איש זר\" האמור כאן — \u0003פסלה,\u0004 ואסורה לאכול בתרומה.","ומקשים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו\u0006 כפשוטו\u0005]\u0006 \u0003דקאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003בת כהן דמינסבא\u0004 \u0005[שנישאת]\u0006 \u0003לזר,\u0004 למי שאינו כהן, גם אם הוא כשר לגמרי — \u0003לא תיכול\u0004 \u0005[תאכל]\u0006 בתרומה, ומדוע נוציא את הפסוק מפשוטו!","ומשיבים: ההלכה \u0003ההיא\u0004 שבת כהן הנישאת לזר איננה יכולה לאכול בתרומה, \u0003מ\u0004מה שנאמר \u0003\"\u0004ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה \u0003ושבה אל בית אביה כנעוריה מלחם אביה תאכל\"\u0004 (שם יג), \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005].\u0006 שכן \u0003מדקאמר רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמרה התורה]\u0006 \u0003\"ושבה אל בית אביה... תאכל\" מכלל\u0004 הדברים אתה למד \u0003דמעיקרא לא אכלה\u0004 \u0005[שמתחילה\u0006 בהיותה נשואה לזר \u0005אינה אוכלת],\u0006 והפסוק המדבר בזו שהיתה לאיש זר מיותר, ולמדים ממנו לענין פסולים.","ראיה זו דוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ההלכה \u0003ההיא\u0004 האמורה בבת כהן ששבה לבית אביה, \u0003הוה אמינא\u0004 \u0005[היינו אומרים]\u0006 כי איסורה לאכול בתרומה בעודה נשואה לזר הוא רק לאו הבא מכלל עשה, שהרי במפורש נאמר הדבר רק בדרך החיוב, שכאשר היא שבה לבית אביה כנעוריה יכולה היא לאכול מן הקדשים, והשלילה נובעת מכוח העשה, וכלל בידינו: \u0003לאו הבא מכלל עשה — עשה\u0004 הוא, על כן \u0003כתב רחמנא האי\u0004 \u0005[כתבה התורה\u0006 פסוק \u0005זה]\u0006 של \"בת כהן כי תהיה לאיש זר\" \u0003ל\u0004איסור \u0003לאו.\u0004 ומשיבים: הלכה זו שאשת זר עוברת על \u0003לאו\u0004 אם אוכלת בתרומה, מכתוב אחר, \u0003מ\u0004מה שנאמר \u0003\"וכל זר לא יאכל קדש\"\u0004 (שם י) \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005].\u0006"],["\u0003ההוא מיבעי ליה לגופיה\u0004 \u0005[נצרך לו לגופו,\u0006 לעצמו\u0005]\u0006 כדי ללמדנו שזר גמור האוכל בתרומה עובר בלאו, אבל בת כהן אינה בכלל זה! ומשיבים: \u0003תרי\u0004 \u0005[שני]\u0006 \u0003\"וכל זר\" כתיבי\u0004 \u0005[כתובים],\u0006 אחד בפסוק האמור (\"וכל זר לא יאכל קודש\". ויקרא כב, י), והשני — שנאמר \"וכל זר לא יאכל בו\" (שם יג), ומאחד מהם למדים אנו לאסור בזר גמור ומן השני לאסור בבת כהן הנשואה לזר.","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו\u0006 כתוב זה\u0005]\u0006 \u0003לכ\u0004 מו שאמר \u0003ר' יוסי בר' חנינא,\u0004 ש\u0003אמר ר' יוסי בר' חנינא:\u0004 מה שנאמר \u0003\"וכל זר\"\u0004 הרי זה בא לצמצם ולומר: \u0003זרות\u0004 בלבד \u0003אמרתי לך\u0004 שפוסלת את האיש מלאכול בתרומה \u0003ולא אנינות\u0004 (אבילות המיוחדת בדיניה ליום הקבורה)! ומשיבים: הלכה זו של \u0003ר' יוסי בר' חנינא\u0004 נלמדה \u0003מן\u0004 הייתור, שהיה די לכתוב \u0003\"זר\u0004 לא יאכל קודש \u0003\"\u0004ונאמר \u0003\"וכל זר\",\u0004 מכאן \u0003נפקא\u0004 \u0005[יוצאת]\u0006 הלכה זו, שרק זרות פוסלת ולא אנינות.","ומיד מקשים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו\u0006 כתוב זה\u0005]\u0006 של \"כי תהיה לאיש זר\", ללמדנו \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 בת כהן שנישאה לישראל, \u0003כשהיא חוזרת\u0004 לבית אביה כשמת בעלה — \u0003חוזרת ל\u0004אכילת \u0003תרומה,\u0004 אבל \u0003אינה חוזרת ל\u0004אכילת \u0003חזה ושוק\u0004 מן הקרבנות. \u0003ואמר רב חסדא אמר רבינא בר רב שילא: מאי קרא\u0004 \u0005[מהו\u0006 \u0005הכתוב]\u0006 המלמדנו הלכה זו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ובת כהן כי תהיה לאיש זר היא בתרומת הקדשים לא תאכל\"\u0004 (שם יב), ללמדנו שכיון שנישאה לאיש זר — לעולם \u0003לא תאכל\u0004 עוד \u0003במורם מן הקדשים,\u0004 שאותן מתנות שנותנים מן הקדשים עצמם, חזה ושוק, נפסלת באכילתן עם נישואיה לזר.","ומשיבים: \u0003אם כן\u0004 שרק הלכה זו בא הכתוב ללמדנו \u0003לכתוב קרא\u0004 \u0005[שיכתוב\u0006 \u0005הכתוב]\u0006 רק \u0003\"היא בקדשים לא תאכל\" מאי\u0004 \u0005[מה]\u0006 משמעות הביטוי המיותר \u0003\"בתרומת הקדשים\"? שמעת מינה תרתי\u0004 \u0005[למד אתה מכאן שני\u0006 דברים\u0005]:\u0006 גם לענין תרומה, וגם לענין קדשים. ואם כן, מכאן אנו למדים שבת כהן הנבעלת לזר פסול נפסלת מלאכול בתרומה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה לענין \u0003כהנת\u0004 — \u0003לויה וישראלית מנלן\u0004 \u0005[מניין לנו]\u0006 שאם בא עליהם פסול שפוסל אותן מלאכול בתרומה כאשר הן נישאות לכהן? ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003ר' אבא אמר רב\u0004 בענין אחר, שיש מקום ללמוד מן הריבוי \u0003\"בת\" \"ובת\"\u0004 שתוספת ה־ו' באה לרבות נשים נוספות על זו הנזכרת במפורש, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לא נאמר \u0003\"בת\u0004 כהן \u0003\"\u0004אלא \u0003\"ובת\u0004 כהן\u0003\"\u0004— לרבות גם לויה וישראלית.","ושואלים: \u0003כמאן\u0004 \u0005[כמי]\u0006 נדרשת דרשה זו — \u0003כ\u0004דעת \u0003ר' עקיבא, דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 \u0003ווין\u0004 יתירים, ולומד מהם ריבוי להלכה? ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 משום שכאן אין הלימוד מן ה־ו' היתירה דווקא אלא מן המלה כולה, כי \u0003כוליה\u0004 \u0005[כל\u0006 המלה\u0005]\u0006 \u0003\"ובת\" קרא יתירא\u0004 \u0005[כתוב יתר]\u0006 \u0003הוא,\u0004 כי בת הכהן כבר נזכרה בפסוק קודם ואין צורך להזכיר שנית \"ובת כהן\", ואם כן יש מותר של מילים, שבא לרבות גם לויה וישראלית.","ושואלים עוד: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא הוכחה לענין תרומה, שכל אשה, כהנת לויה וישראלית שבא עליהן פסול — פסלן מלאכול \u0003תרומה,\u0004 אולם שנפסלות ונאסרות להינשא \u0003לכהונה מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003אטו\u0004 \u0005[\u0006ו\u0005כי]\u0006 \u0003לויה וישראלית לא\u0004 לענין נישואין \u0003לכהונה מרבנן להו\u0004 \u0005[מרבים אנו אותן]?\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003ל\u0004ענין אכילת \u0003תרומה,\u0004 וכי לויה וישראלית \u0003בנות מיכל\u0004 \u0005(אכילת)\u0006 \u0003תרומה נינהו\u0004 \u0005[הן]?\u0006 אלא ודאי כוונת הכתוב היא שאסור להן להינשא לכהן ולאכול על ידו בתרומה.","את הראיה הזאת דוחים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא,\u0004 הרי \u0003משכחת לה דקאכלה\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות \u0005שאוכלת]\u0006 \u0003בשביל בנה,\u0004 שאם היה לה בן מכהן — הריהי אוכלת בתרומה בגללו, ואם עכשיו נבעלה לפסול, למרות שהיא עצמה אסורה לכהן, היינו אומרים שרשאית לאכול בתרומה בגלל בנה, ואם כן, יש צורך בלימוד מיוחד לפסול אותה גם לענין תרומה וגם לענין פסול נישואין.","ודוחים: \u0003בשביל בנה קל וחומר\u0004 הוא שלא תאכל לאחר שנבעלה לפסול: \u0003ומה כהנת דבקדושה דנפשה אכלה\u0004 \u0005[שבקדושת עצמה\u0006 היא \u0005אוכלת]\u0006 בתרומה, משום שהיא בת כהן ויש בה קדושת כהונה לעצמה, ובכל זאת \u0003פסיל לה\u0004 \u0005[פוסל אותה]\u0006 הפסול בביאתו מלאכול בתרומה — \u0003לויה וישראלית דלא אכלה\u0004 \u0005[שאינה אוכלת]\u0006 \u0003אלא בשביל בנה, לא כל שכן\u0004 שעל ידי ביאת פסול תיפסל מאכילת תרומה?","את ההוכחה הזו דוחים: \u0003והיא הנותנת,\u0004 אדרבא, מפני נימוק זה עצמו אפשר להגיע למסקנה הפוכה: \u0003כהנת דקדיש\u0004 \u0005[שקדוש]\u0006 \u0003גופה,\u0004 עצמה, לכן ביאת הזר עליה \u0003פסיל לה\u0004 \u0005[פוסלת אותה],\u0006 \u0003הא\u0004 \u0005[זו],\u0006 הלויה והישראלית, \u0003דלא קדיש גופה\u0004 \u0005[שאין גופה קדוש]\u0006 ואוכלת רק מכוח בנה — \u0003לא פסיל לה\u0004 \u0005[אין פוסל אותה]\u0006 הפסול שבא עליה. \u0003אלא\u0004 יש לומר כי איסורן של נשים אלה \u0003לכהונה\u0004 נלמד ב\u0003קל וחומר מגרושה,\u0004 ובדרך זו: \u0003ומה גרושה\u0004 בת כהן \u0003שמותרת בתרומה\u0004 — \u0003אסורה\u0004 בכל זאת \u0003לכהונה,\u0004 כמפורש בתורה שגרושה אסורה לכהן, \u0003זו\u0004 הלויה והישראלית שנבעלה לפסול \u0003שאסורה בתרומה — אינו דין שפסולה לכהונה?!\u0004 את ההוכחה הזו מתקיפים מצד אחר: הרי נמצא שעל ידי קל וחומר זה למדנו הלכה חדשה — שיש איסור לא תעשה לכהונה באשה שנבעלה לפסול.","אולם שואלים: \u0003וכי מזהירין מן הדין?\u0004 האם קובעים איסור לאו (\"אזהרה\") רק על ידי קל וחומר?! ומשיבים: כאן אין יצירת אזהרה חדשה, אלא \u0003גלוי מילתא בעלמא\u0004 \u0005[דבר בלבד]\u0006 \u0003הוא,\u0004 שאת עיקר הדין שהיא נפסלת אנו יודעים כבר, שהרי נפסלה מאכילת תרומה, ולא הוצרכנו אלא ללמוד ענין זה שיש בכך איסור לא תעשה לכהונה, ודבר זה אפשר ללמוד על ידי קל וחומר. מצאנו איפוא בתורה את מקור ההלכה העיקרי, ושואלים לגבי פרטי הדין.","אמרנו שהנבעלת לפסול לה פסולה מן הכהונה, \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003נבעלה לפסול לה\u0004 — הוא דווקא בזו שנבעלה ל\u0003חייבי כריתות,\u0004 אבל לא באיסור לאו ועשה? ודוחים: \u0003\"כי תהיה\" אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 לומר: \u0003הנך דאית בהו\u0004 \u0005[אלה שיש בהם]\u0006 \u0003הויה,\u0004 קידושין, כלומר הקידושין תופסים, ואילו \u0003חייבי כריתות לאו\u0004 \u0005[לא]\u0006 \u0003בני הויה\u0004 הם, ואם כן מדבר הכתוב בחייבי לאוין שתופסים בהם קידושין, שגם בנבעלה להם נפסלה מלאכול בתרומה.","ומקשים: אם הפסול תלוי רק בהוויה של קידושין \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גוי ועבד\u0004 שבאו על אשה \u0003לא ליפסלו\u0004 \u0005[יפסלו]\u0006 אותה מלאכול בתרומה, שהרי ברור לנו שאינם בני קידושין! ומשיבים: \u0003הנך פסלי\u0004 \u0005[אלה פוסלים]\u0006 \u0003מ\u0004הטעם שהסביר \u0003ר' ישמעאל.\u0004 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: מנין לגוי\u0004 או \u0003עבד שבא על בת ישראל,\u0004 או \u0003על כהנת,\u0004 או על \u0003לויה, שפסלוה\u0004 על ידי ביאתם — \u0003שנאמר: \"ובת כהן כי תהיה אלמנה וגרושה\u0004 וזרע אין לה ושבה אל בית אביה כנעוריה\u0003\"\u0004 (שם יג),"],["ולמדו: \u0003מי שיש לו אלמנות וגירושין בה, יצאו גוי ועבד שאין לו אלמנות וגרושין,\u0004 שהרי אין להם נישואין כלל בבת ישראל.","ואומרים: מפסוק זה \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה ב\u0003כהנת\u0004 — ב\u0003לויה ו\u0004ב\u0003ישראלית מנא לן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003כדאמר\u0004 \u0005[כפי\u0006 \u0005שאמר]\u0006 \u0003ר' אבא אמר רב: \"בת\" \"ובת\"\u0004 שהוא לשון ריבוי, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"בת\" \"ובת\"\u0004 הוא מרבה אף את הלויה והישראלית.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא — האם לא \u0003כר' עקיבא, דדריש ווי\u0004 \u0005[שדורש ואוי\"ם]\u0006 יתירים ללמוד מהם הלכה?! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו — \u0003כולה\u0004 \u0005[כל\u0006 המלה\u0005]\u0006 \u0003\"ובת\" קרא יתירא\u0004 \u0005[כתוב יתר]\u0006 \u0003הוא,\u0004 שאיננו נחוץ לעניינו, שהרי בה, בבת, מדבר הכתוב ולדעת הכל בא הכתוב לדרשה.","ומקשים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהדרשה תידרש כך: \u0003מי שיש לו אלמנות וגירושין בה, כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 לבעלה \u0003זרע\u0004 ממנה — \u0003קאכלה\u0004 \u0005[אוכלת]\u0006 שוב בתרומה, \u0003כי אית ליה\u0004 \u0005[כאשר יש לו]\u0006 לבעלה \u0003זרע\u0004 ממנה — \u0003לא אכלה\u0004 \u0005[אוכלת],\u0006 ו\u0003מי שאין לו אלמנות וגירושין בה, אף על גב דאית ליה\u0004 \u0005[אף על פי שיש לו]\u0006 \u0003זרע נמי תיכול\u0004 \u0005[גם כן תאכל]!\u0006 שכיון שהנישואין אינם תופסים, אין הזרע הבא מהם נחשב כשלו, ואינו פוסל.","ומשיבים: \u0003אם כן, רבויי\u0004 \u0005[לרבות]\u0006 \u0003לויה וישראלית למה לי?\u0004 שהרי ודאי בא הכתוב לרבות דברים שלא למדנו קודם לכן, ואין צורך בכתוב מיוחד להתיר לויה וישראלית אם היתה כהנת עצמה מותרת, אלא ודאי בא הריבוי לאסור.","ושואלים: \u0003ול\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר: אין קדושין תופסין\u0004 אפילו \u0003בחייבי לאוין, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"כי תהיה לאיש זר\"\u0004 — לא בהוויה של נישואין אלא כוונתו \u0003כי תיבעל,\u0004 וכל האסורים — פוסלים, וגם גוי ועבד שאין בהם נישואין נכללים בפסוק זה, אם כן \u0003אלמנה וגרושה למה לי?\u0004","ומשיבים: \u0003אלמנה\u0004 באה \u0003להחמיר עליה, וגרושה להקל עליה. וצריכא\u0004 \u0005[ונצרכו]\u0006 שני הדברים להיאמר. \u0003דאי אשמעינן\u0004 \u0005[שאילו\u0006 היה \u0005משמיע לנו]\u0006 את ההלכה ב\u0003אלמנה\u0004 בלבד, הייתי אומר: \u0003אלמנה הוא דכי לית לה\u0004 \u0005[שכאשר אין לה]\u0006 \u0003זרע אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה, \u0003משום דחזיא\u0004 \u0005[שראויה]\u0006 \u0003לכהונה\u0004 (לכהן הדיוט), \u0003אבל גרושה דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003לכהונה\u0004 כלל, \u0003אימא אף על גב דלית\u0004 \u0005[אמור\u0006 ש\u0005אף על פי שאין]\u0006 \u0003לה זרע לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 עוד בתרומה. \u0003ואי אשמעינן\u0004 \u0005[ואילו\u0006 היה \u0005משמיע לנו]\u0006 ב\u0003גרושה,\u0004 הייתי אומר: \u0003גרושה הוא דכי אית\u0004 \u0005שכאשר אין]\u0006 \u0003לה זרע\u0004 מן הזר \u0003לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 \u0003משום דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003לכהונה, אבל אלמנה דחזיא\u0004 \u0005[שראויה]\u0006 \u0003לכהונה, אימא אף על גב דאית\u0004 \u0005[אמור\u0006 ש\u0005אף על פי שיש]\u0006 \u0003לה זרע\u0004 מן הזר \u0003נמי תיכול\u0004 \u0005[גם כן תאכל],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003נבעלה לפסול לה\u0004 כולל \u0003אף מחזיר גרושתו\u0004 אחרי שנישאה לאחר! ומשיבים: \u0003\"לאיש זר\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003מי שזר אצלה מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003לאפוקי האי\u0004 \u0005[להוציא\u0006 את \u0005זה],\u0006 את בעלה הקודם, שכן \u0003לא זר אצלה מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003הוא.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 בא עליה \u0003חלל, דלאו\u0004 \u0005[שלא]\u0006 \u0003זר הוא מעיקרא\u0004 \u0005[מתחילה],\u0006 שהרי הוא מותר אף בכהנת, ש\u0003לא לפסול\u0004 \u0005[יפסול]\u0006 בביאתו! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא יחלל זרעו בעמיו\"\u0004 (ויקרא כא, טו), \u0003מקיש\u0004 (משווה) הכתוב \u0003זרעו לו, מה הוא\u0004 כהן שנשא אשה האסורה עליו \u0003פוסל\u0004 את אשתו מכהונה — \u0003אף זרעו\u0004 החלל \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל\u0004 את אשתו.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שיהא פסול זה \u0003משעת הויה,\u0004 משעת קידושין. שהרי פסול שמקדש בת כהן, פוסל אותה מיד ואפילו לא בא עליה! ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין של \u0003כהן גדול באלמנה; מה כהן גדול באלמנה, בביאה\u0004 בלבד הוא שפוסל אותה ולא בקידושין, \u0003אף האי נמי\u0004 \u0005[זה גם כן]\u0006 אינו פוסל אלא \u0003בביאה.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003הויה\u0004 של קידושין \u0003ו\u0004גם \u0003ביאה?!\u0004 ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כהן גדול באלמנה; מה כהן גדול באלמנה בביאה לחודה\u0004 \u0005[לבדה]\u0006 פוסל, \u0003אף האי נמי\u0004 \u0005[זה גם כן]\u0006 פוסל \u0003בביאה לחודה\u0004 \u0005[לבדה].\u0006","בברייתא שנינו, \u0003ור' יוסי אומר: כל שזרעו פסול — פוסל, וכל שאין זרעו פסול — אינו פוסל.\u0004 ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 במה ההבדל \u0003בין תנא קמא לר' יוסי?\u0004","\u0003אמר ר' יוחנן:\u0004 בענין \u0003מצרי שני ואדומי שני איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלגביהם הם חלוקים, שהרי דור שלישי שלהם מותר לבוא בקהל ה', ואם כן בניהם אינם פסולים, אבל הם עצמם פסולים. שלדעת תנא קמא כיון שהם פסולים, הריהם פוסלים את האשה בביאתם מלאכול בתרומה. ולדעת ר' יוסי, כיון שזרעם אינו פסול — אף הם אינם פוסלים אשה בביאתם מלאכול בתרומה.","ומעירים: \u0003ושניהם לא למדוה אלא מכהן גדול באלמנה,\u0004 אבל למדו בדרכים שונות: \u0003תנא קמא סבר\u0004 כך: \u0003מה כהן גדול באלמנה, שביאתו\u0004 אותה היא \u0003בעבירה ו\u0004הוא גם \u0003פוסל\u0004 את האשה בביאתו מלאכול בתרומה — \u0003אף האי נמי\u0004 \u0005[אף זה\u0006 מצרי שני \u0005גם כן]\u0006 \u0003פוסל.\u0004","\u0003ור' יוסי סבר: ככהן גדול, מה כהן גדול שזרעו\u0004 מן האלמנה \u0003פסול ופוסל\u0004 עליה בביאתו מלאכול בתרומה, \u0003אף כל שזרעו פסול\u0004 — \u0003פוסל. לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מצרי שני\u0004 ש\u0003אין זרעו פסול. דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנים אשר יולדו להם דור שלישי יבא להם בקהל ה'\"\u0004 (דברים כג, ט).","עוד שנינו בברייתא, \u0003רבן שמעון בן גמליאל אומר: כל שאתה נושא\u0004 את \u0003בתו\u0004 — \u0003אתה נושא\u0004 אף את \u0003אלמנתו,\u0004 ושאין אתה נושא את בתו — אין אתה נושא את אלמנתו. ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין ר' יוסי לרבן שמעון בן גמליאל,\u0004 שלכאורה אומרים הם אותו דבר, ששניהם תולים את פסול האשה בפסול הבנים הנולדים מאותו איש, ומשיבים:","\u0003אמר עולא:\u0004 בענין \u0003גר עמוני ומואבי איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003ושניהם לא למדוה אלא מכהן גדול באלמנה. ר' יוסי סבר: מה כהן גדול באלמנה שזרעו פסול ופוסל — אף כל שזרעו פסול — פוסל.\u0004","ואילו \u0003רבן שמעון בן גמליאל סבר: מה כהן גדול באלמנה שכל זרעו\u0004 שהוא מוליד ממנה \u0003פסול ו\u0004הוא גם \u0003פוסל\u0004 את אשתו בביאה, \u0003אף\u0004 כל מי \u0003שכל זרעו פסול ופוסל, לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003עמוני ומואבי,\u0004 ש\u0003אין כל זרעו פסול,\u0004 שהרי בת גר עמוני או מואבי כשירה לבוא בקהל, והפסול הוא רק לגבי הבנים. שהרי \u0003אמר מר\u0004 \u0005[החכם]\u0006 בזה שההלכה היא: \u0003עמוני ולא עמונית, מואבי ולא מואבית.\u0004","\u0003האונס\u0004 את האשה או \u0003המפתה\u0004 אותה, \u0003והשוטה\u0004 אפילו נשא אותה בחופה וקידושין — אם היו זרים, \u0003לא פוסלין\u0004 בביאתם את הכהנת מאכילת תרומה, \u0003ולא מאכילין\u0004 בת ישראל בתרומה, אם היו כהנים. \u0003ואם אינן ראויין לבא בישראל — הרי אלו פוסלין,\u0004 שכן בפסולים הביאה היא המחללת את האשה. \u0003כיצד?\u0004 הרי \u0003ישראל שבא על בת כהן\u0004 שלא לשם קידושין, אלא באונס או בפיתוי — \u0003תאכל\u0004 אותה אשה \u0003בתרומה,\u0004 שלא נפסלה בביאה זו."],["\u0003עיברה\u0004 (הרתה) מביאה זו — \u0003לא תאכל בתרומה,\u0004 שכן העובר פוסל בכל מקרה. ואם \u0003נחתך העובר במעיה\u0004 ומת, או שמת מיד לאחר שנולד — \u0003תאכל. היה\u0004 האונס, המפתה או השוטה \u0003כהן שבא על בת ישראל — לא תאכל בתרומה, עיברה — לא תאכל, ילדה — תאכל,\u0004 בשל בנה שהוא כהן. \u0003נמצא כחו של בן גדול משל אב,\u0004 שהרי אביו של אותו ילד אינו מאכיל אותה, והבן מאכילה.","\u0003העבד פוסל\u0004 אשה מאכילת תרומה \u0003משום ביאה, ואינו פוסל משום זרע. כיצד\u0004 משום זרע? \u0003בת ישראל\u0004 שנישאה \u0003לכהן,\u0004 או \u0003בת כהן\u0004 שנישאה \u0003לישראל, וילדה הימנו בן, והלך הבן ונכבש\u0004 (בא) \u0003על השפחה,\u0004 ונקט בלשון מגונה, בגלל הגנאי שבדבר, \u0003וילדה\u0004 השפחה \u0003הימנו בן — הרי זה,\u0004 אותו בן, \u0003עבד.\u0004 ואם \u0003היתה אם אביו בת ישראל\u0004 שנישאה \u0003לכהן — לא תאכל בתרומה,\u0004 אם מת בעלה והעבד הוא הזרע היחיד שנשאר ממנו. אולם אם היתה \u0003בת כהן\u0004 שנישאה \u0003לישראל\u0004 ומת, וזה הזרע היחיד שנשאר ממנה — \u0003תאכל בתרומה.\u0004 לפי שאין העבד נחשב כלל כזרעו של אביו.","\u0003ממזר פוסל ומאכיל. כיצד? בת ישראל\u0004 הנשואה \u0003לכהן,\u0004 או \u0003בת כהן\u0004 הנשואה \u0003לישראל, וילדה הימנו בת, והלכה הבת ונישאת לעבד או לגוי וילדה הימנו בן — הרי זה ממזר\u0004 (לשיטת תנא זה). \u0003היתה אם אמו בת ישראל\u0004 הנשואה \u0003לכהן — תאכל בתרומה,\u0004 שהרי נשאר זרע מן הכהן ואוכלת בגללו. ואם היתה \u0003בת כהן\u0004 הנשואה \u0003לישראל — לא תאכל בתרומה\u0004 שהרי יש לה זרע מן הישראלי.","\u0003כהן גדול, פעמים שהוא פוסל. כיצד? בת כהן\u0004 שנישאה \u0003לישראל וילדה הימנו בת, והלכה הבת וניסת לכהן, וילדה הימנו בן — הרי זה ראוי להיות כהן גדול עומד ומשמש על גבי המזבח.\u0004 והרי בן זה \u0003מאכיל את אמו,\u0004 שהיא אוכלת בזכות בנה הכהן, \u0003ופוסל\u0004 את \u0003אם אמו,\u0004 שהרי נשאר לה זרע מבעלה הישראל, ו\u0003זאת\u0004 אם האם \u0003אומרת\u0004 בתרעומת: \u0003לא\u0004 ירבו כאלה שהם \u0003כבני\u0004 (כלומר, נכדי) \u0003כהן גדול, שהוא פוסלני מן התרומה.\u0004","ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 כבר במשנה \u0005לזה ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שוטה וקטן שנשאו נשים, ומתו — נשותיהן פטורות מן החליצה ומן הייבום.\u0004 כמבואר כאן, שנישואי שוטה אינם נחשבים נישואין.","שנינו במשנה: \u0003כיצד? היה ישראל שבא על בת כהן — תאכל בתרומה, עיברה לא תאכל.\u0004 ושואלים: \u0003כיון\u0004 שאם \u0003עיברה לא תאכל? ליחוש\u0004 \u0005[נחשוש]\u0006 אם כן אף באנוסה ומפותה בכל מקרה שאשה נבעלה \u0003שמא עיברה! מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מפרישין אותן,\u0004 את הנשים שהוחלפו בשעת החופה, מבעליהן \u0003שלשה חדשים, שמא מעוברות הן\u0004 בביאה ראשונה. ואם כן, למה לא נחשוש גם כאן שמא התעברו ויפסלו מלאכול בתרומה, ומדוע שנינו במשנה שישראל הבא על בת כהן באונס או בפיתוי — אוכלת?","ומשיבים, \u0003אמר רבה בר רב הונא: ליוחסין חששו,\u0004 ולכן מפרישים אותן, \u0003לתרומה לא חששו.\u0004 ושואלים: \u0003ו\u0004כי \u0003לתרומה לא חששו? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 האומר לאשה: \u0003\"הרי זה גיטיך שעה אחת קודם למיתתי\",\u0004 אם היתה זאת בת ישראל שנישאה לכהן — \u0003אסורה לאכול בתרומה מיד,\u0004 שאנו חוששים מיד שמא ימות בעוד שעה, משמע שאף לתרומה גזרו מפני חשש!","\u0003אלא אמר רבה בר רב הונא: בנישואין — חששו, בזנות — לא חששו.\u0004 משום שהאשה נוקטת באמצעי זהירות שלא תתעבר.","ושואלים: \u0003ובנישואין מי\u0004 \u0005[האם]\u0006 \u0003חששו? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בת כהן שנישאת לישראל, ומת\u0004 בעלה באותו יום — \u0003טובלת\u0004 לטהרה (שהרי היא נטמאה בביאה כמפורש בתורה), \u0003ואוכלת בתרומה לערב,\u0004 אחרי מותו. משמע שאין אנחנו חוששים להתעברות מביאה אחת, אפילו בנישואין!","\u0003אמר רב חסדא: טובלת ואוכלת עד ארבעים\u0004 יום למותו. שעד אז אין לחשוש, ומדוע? \u0003דאי לא מיעברא\u0004 \u0005[שאם איננה מעוברת] —\u0006 \u0003הא לא מיעברא\u0004 \u0005[הרי איננה מעוברת],\u0006 וחוזרת לבית אביה כנעוריה, \u0003ואי מיעברא\u0004 \u0005[ואם מעוברת\u0006 היא\u0005],\u0006 הרי \u0003עד ארבעים\u0004 יום מתחילת ההריון \u0003מיא בעלמא היא\u0004 \u0005[מים סתם הוא],\u0006 כלומר, אין העובר נחשב עדיין לנפש חיה, ואינו פוסל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003הוכר עוברה במעיה\u0004 לאחר זמן — \u0003תהא מקולקלת למפרע.\u0004 שכל אכילותיה בתרומה שאכלה עד היום היו בעבירה. ולכאורה משמע שקלקול זה נחשב משעה שמת בעלה, אפילו בארבעים יום הראשונים! הסביר רב חסדא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקולקלת\"\u0004 — כוונתו מיום שהוכר העובר למפרע \u0003עד ארבעים\u0004 יום לתחילת ההריון, שבאותם ארבעים יום הראשונים אינו נחשב לנפש ולא פוסל.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003הבא על ארוסתו בבית חמיו,\u0004 שעדיין לא נשאה, ונולד ילד, ושניהם אומרים שהילד הוא ממנו — \u0003רב אמר: הולד\u0004 הזה \u0003ממזר\u0004 הוא, שודאי אינו מהארוס, \u0003ושמואל אמר: הולד שתוקי,\u0004 ככל ילד שלא ברור מי הוא אביו. \u0003אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב\u0004 שהוא ממזר ודאי, במקרה \u0003דדיימא מעלמא\u0004 \u0005[ש\u0006היא \u0005חשודה מהכול],\u0006 שיצא קול על אשה זו שהיא מופקרת, \u0003אבל\u0004 כאשר היא \u0003לא דיימא מעלמא\u0004 \u0005[חשודה מן הכול] —\u0006 \u0003בתרא דידיה שדינן ליה\u0004 \u0005[אחריו,\u0006 אחרי הארוס, \u0005אנחנו מטילים אותו]\u0006 את הילד הזה, ומניחים שהוא בנו.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אני אומר זאת]\u0006 — \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנה, שכהן שאנס את בת ישראל, אם \u0003ילדה — תאכל\u0004 בתרומה בשביל הבן, ומעתה יש להבין: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא דדיימא מעלמא\u0004 \u0005[אם תאמר ש\u0006היא \u0005חשודה מן הכול],\u0006 גם אם \u0003ילדה אמאי\u0004 \u0005[מדוע]\u0006 \u0003תאכל?\u0004 שמא הילד הזה איננו בנו של הכהן?! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא ש\u0003מיניה דיימא\u0004 \u0005[\u0006ש\u0005ממנו\u0006 היא \u0005חשודה],\u0006 \u0003ולא דיימא מעלמא\u0004 \u0005[חשודה מן הכול].\u0006","ומעתה קל וחומר הוא: \u0003ומה התם\u0004 \u0005[שם]\u0006 במקרה של אונס ומפתה — \u0003דלהאי איסורא ולהאי איסורא\u0004 \u0005[שלזה,\u0006 לאונס עצמו, היא \u0005אסורה, ולזה,\u0006 לכולם גם כן \u0005אסורה]\u0006 באותה מידה — \u0003בתרא דידיה שדינן ליה\u0004 \u0005[אחריו אנו מטילים אותו,\u0006 את הילד\u0005],\u0006 ומייחסים אותו לו, \u0003הכא, דלהאי איסורא ולהאי היתירא\u0004 \u0005[כאן, שלזה,\u0006 לאחרים, היא \u0005אסורה\u0006 איסור חמור, \u0005ולזה,\u0006 לארוס היא \u0005מותרת\u0006 בעצם\u0005] —\u0006 \u0003לא כל שכן\u0004 שראוי לייחס את הילד אליו?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 \u0003כל היכא דדיימא מיניה\u0004 \u0005[כל מקום ש\u0006היא \u0005חשודה ממנו]\u0006 \u0003אף על גב דלא דיימא מעלמא\u0004 \u0005[אף על פי שאיננה חשודה מן הכול]\u0006 וודאי הוא בנו של הארוס, על כל פנים \u0003אמר רב\u0004 ש\u0003הולד ממזר.\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שבדבר — כיון \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003מדאפקרא נפשה לגבי\u0004 \u0005[מ\u0006אחר \u0005שהפקירה\u0006 את \u0005עצמה אצל]\u0006 ה\u0003ארוס\u0004 שאסורה לו כל זמן שלא נשאה — שמא \u0003אפקרא נפשה לעלמא\u0004 \u0005[הפקירה\u0006 את \u0005עצמה לכול],\u0006 \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 שהבאת ממנה ראיה, מדובר בה \u0003שהיו שניהם\u0004 בלבד \u0003חבושים\u0004 יחד \u0003בבית האסורין\u0004 שאין לחשוש שהפקירה עצמה גם לאחרים, מאחר שלא היה שם איש אחר. זו היתה לשון אחת של המחלוקת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך היתה המחלוקת: \u0003בבא עליה\u0004 הארוס ודאי ומודה בכך — \u0003כולי עלמא לא פליגי דבתריה דידיה שדינן ליה\u0004 \u0005[הכל אינם חולקים שאחריו אנחנו מטילים אותו,\u0006 את הילד\u0005]\u0006 ומייחסים אותו לו. \u0003והכי איתמר\u0004 \u0005[וכך נאמר]:\u0006 \u0003ארוסה שעיברה\u0004 (שהרתה) וטוענת שהוא מן הארוס, והארוס אינו מודה שבא עליה, ש\u0003רב אמר: הולד ממזר. ושמואל אמר: הולד שתוקי. אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב\u0004 כאשר \u0003לא דיימא מיניה ודיימא מעלמא\u0004 \u0005[אינה חשודה ממנו\u0006 אבל \u0005חשודה מן הכל],\u0006 שאז יש להניח שיש בסיס לחשד שהרתה לאחר, והוולד ממזר,"],["\u0003אבל דיימא מניה\u0004 \u0005[\u0006כש\u0005חשודה ממנו],\u0006 \u0003אף על גב דדיימא מעלמא\u0004 \u0005[אף על פי שחשודה\u0006 גם \u0005מהכול]\u0006 \u0003— בתריה דידיה שדינן ליה\u0004 \u0005[אחריו אנחנו מטילים אותו\u0006 את הילד\u0005].\u0006","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אני אומר זאת] —\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בזו שנאנסה או נתפתתה על ידי כהן: \u0003ילדה — תאכל.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר],\u0006 \u0003אילימא דדיימא מניה\u0004 \u0005[אם תאמר ש\u0006היא \u0005חשודה ממנו]\u0006 \u0003ולא דיימא מעלמא\u0004 \u0005[חשודה מהכול] —\u0006 האם \u0003צריכא למימר דתיכול\u0004 \u0005[צריך לומר שתאכל]?!\u0006 הרי מן הסתם הילד הוא בנו של הכהן! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא] —\u0006 \u0003דדיימא נמי מעלמא\u0004 \u0005[ש\u0006היא \u0005חשודה גם כן מהכול],\u0006","\u0003ומה התם\u0004 \u0005[שם],\u0006 \u0003דלהאי איסורא ולהאי איסורא\u0004 \u0005[שלזה,\u0006 לאותו כהן, יש \u0005איסור, ולזה,\u0006 לכל אדם אחר, \u0005איסור\u0006 הוא\u0005] —\u0006 בכל אופן \u0003בתריה דידיה שדינן ליה\u0004 \u0005[אחריו אנחנו מטילים אותו,\u0006 את הילד\u0005],\u0006 \u0003הכא דלהאי איסורא ולהאי היתירא\u0004 \u0005[כאן שלזה,\u0006 לאחרים יש \u0005איסור\u0006 לבוא עליה \u0005ולזה\u0006 הארוס \u0005היתר] —\u0006 \u0003לא כל שכן\u0004 שנאמר שהארוס בא עליה ונייחס את הילד אחריו?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי,\u0004 אפשר לדחות הוכחה זו: \u0003לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 \u0003כל היכא\u0004 \u0005[מקום]\u0006 \u0003דדיימא מעלמא\u0004 \u0005[ש\u0006היא \u0005חשודה מהאחרים],\u0006 \u0003אף על גב דדיימא מניה\u0004 \u0005[אף על פי שחשודה\u0006 גם \u0005ממנו],\u0006 \u0003אמר רב\u0004 ש\u0003הולד ממזר. ומתניתין\u0004 \u0005[ומשנתנו]\u0006 עוסקת \u0003בדלא דיימא\u0004 \u0005[ב\u0006מקרה \u0005שאינה חשודה]\u0006 \u0003כלל,\u0004 שאז, אם שניהם מודים, יש לומר שהוולד הוא שלו.","","שנינו במשנה כי \u0003העבד פוסל משום ביאה,\u0004 אבל אינו פוסל משום זרע. ומבארים: \u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה הטעם]\u0006 שאינו פוסל משום זרע — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"האשה וילדיה תהיה לאדוניה\"\u0004 (שמות כא, ד), משמע שבנה של השפחה (וכמו כן העבד) מתייחס אחר אמו ולא אחר אביו, ולכן גם לא נקרא זרע של אביו, ואינו פוסל מלאכול בתרומה.","עוד שנינו במשנה: \u0003ממזר פוסל ומאכיל. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"וזרע אין לה\"\u0004 (ויקרא כב, יג), \u0003אין לי\u0004 ללמוד מזה שפסולה מלאכול בתרומה \u0003אלא\u0004 בשל \u0003זרעה,\u0004 ואולם שהיא פסולה אף בשל \u0003זרע זרעה מנין? תלמוד לומר: \"וזרע אין לה\" — מכל מקום,\u0004 שאף זרע זרעה בכלל זה. \u0003אין לי\u0004 שפוסל אותה \u0003אלא זרע כשר,\u0004 ואולם שפוסל אותה אף \u0003זרע פסול מנין — תלמוד לומר: \"וזרע אין לה\"\u0004 ואנחנו דורשים: \u0003עיין עלה\u0004 (עליה), וכל שתמצא זרע — הרי הוא נחשב, בין זרע כשר, בין לא.","","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו\u0006 כבר\u0005]?\u0006 שהרי מכתוב זה למדנו \u0003לזרע זרעה\u0004 שפוסלה מתרומה! ומשיבים: \u0003זרע זרעה\u0004 בעצם \u0003לא איצטריך קרא\u0004 \u0005[הוצרך כתוב]\u0006 מיוחד ללמדנו, שכן הכלל הוא כי \u0003בני בנים הרי הן כבנים.\u0004 ו\u0003כי איצטריך קרא\u0004 \u0005[\u0006ו\u0005כאשר הוצרך הכתוב],\u0006 הרי זה \u0003לזרע פסול.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: כמאן\u0004 \u0005[כמי]\u0006 שיטת משנה זו — \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר: יש ממזר מחייבי לאוין?\u0004 ולכן נאמר במשנה שמעבד וגוי הוולד ממזר. ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 ומכל מקום \u0003בגוי ועבד מודו\u0004 \u0005[מודים]\u0006 אף הם שהוולד ממזר. \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יצחק בר אבדימי משום רבינו\u0004 (בשם רבי): \u0003גוי ועבד הבא על בת ישראל — הולד ממזר\u0004. שנינו במשנה: \u0003כהן גדול, פעמים שפוסל. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בהרחבה בברייתא, שיכולה אשה זו לומר: \u0003הריני כפרת,\u0004 כלומר, חביב עלי ואני מוכנה להיות כפרתו ותמורתו של \u0003בן בתי כוזא\u0004 (כד קטן) כלומר, אפילו צאצא פגום כגון ממזר, \u0003שמאכילני בתרומה,\u0004 שהרי בגללו היא אוכלת עדיין בתרומה, משום שהוא נחשב כזרעה. \u0003ואיני כפרת בן בתי כדא\u0004 (הכד) הגדול, החשוב, שהוא כהן גדול — \u0003שפוסלני מן התרומה.\u0004 כמבואר, שפעמים קורה שנכד פסול מכשיר את סבתו בת ישראל לאכול בתרומה, ונכד כשר פוסל את סבתו כשהיא בת כהן מלאכול בתרומה.","","","","הכהן \u0003הערל\u0004 (כגון שמחמת סכנה לא נימול) \u0003וכל הטמאים\u0004 בכל מיני טומאה — \u0003לא יאכלו בתרומה,\u0004 אבל \u0003נשיהן ועבדיהן יאכלו בתרומה.\u0004","\u0003פצוע דכא וכרות שפכה\u0004 שאסורים לבוא בקהל, אם כהנים הם — \u0003הן ועבדיהן יאכלו,\u0004 שדבר זה אינו פוסל אותם ואת רכושם, אבל \u0003נשיהן לא יאכלו,\u0004 שכן, אם באו על נשים אלה — עשו אותן חללות בביאת איסור, שהרי אסורים לבוא בקהל ה'. \u0003ואם לא ידעה\u0004 (לא בא עליה הכהן) \u0003משנעשה פצוע דכא וכרות שפכה — הרי אלו יאכלו,\u0004 מכיון שנישאו לכהנים בהיתר.","\u0003ואי זהו פצוע דכא — כל שנפצעו הביצים שלו, ואפילו\u0004 לא נפצעה אלא \u0003אחת מהן. וכרות שפכה — כל שנכרת הגיד\u0004 (אבר הזכרות), \u0003ו\u0004שיעורו של דבר, \u0003אם נשתייר מעטרה\u0004 (החלק הבולט שבראש הגיד) ומטה לצד הגוף \u0003אפילו כחוט השערה\u0004 — \u0003כשר,\u0004 אף על פי שנכרתה כל העטרה. אבל אם לא נשתייר מן הגיד כלום, הריהו כרות שפכה הכתוב בתורה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: מנין לערל שאין אוכל בתרומה? נאמר \"תושב ושכיר\" ב\u0004קרבן \u0003פסח\u0004 (\"תושב ושכיר לא יאכל בו\". שמות יב, מה) \u0003ונאמר \"תושב ושכיר\" בתרומה\u0004 (\"תושב כהן ושכיר לא יאכל קודש\". שם כב, י), \u0003מה \"תושב ושכיר\" האמור בפסח\u0004 משמעו ש\u0003ערל אסור בו — אף \"תושב ושכיר\" האמור בתרומה\u0004 מלמד ש\u0003ערל אסור בו.\u0004 \u0003ר' עקיבא אומר: אינו צריך\u0004 לראיה זו, אלא \u0003הרי הוא אומר \"איש איש\u0004 מזרע אהרן והוא צרוע או זב בקדשים לא יאכל\u0003\"\u0004 (ויקרא כב, ד), וכפל הלשון \"איש איש\" — \u0003לרבות\u0004 את \u0003הערל,\u0004 שהוא כטמא, שאסור לאכול בתרומה. ומעתה מבררים ברייתא זו לגופה.","","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' אליעזר אומר: נאמר \"תושב ושכיר\" בפסח, ונאמר \"תושב ושכיר\" בתרומה, מה \"תושב ושכיר\" האמור בפסח ערל אסור בו, אף \"תושב ושכיר\" האמור בתרומה ערל אסור בו.\u0004","ומעירים: צריך לומר שהביטוי \"תושב ושכיר\" \u0003מופנה\u0004 (מיותר) ואינו נחוץ לגופו, \u0003דאי לאו\u0004 \u0005[שאם לא]\u0006 \u0003מופנה\u0004 הוא, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך\u0006 ולהקשות\u0005]\u0006 על השוואה זו, ולבטל את הגזירה שווה, בדרך זו: \u0003מה לפסח, שכן\u0004 הוא מן הקדשים ו\u0003חייבין עליו\u0004 באכילתו כרת, וכן \u0003משום פיגול,\u0004 אם חשבו בשעת ההקרבה לאוכלו שלא בזמנו, \u0003ו\u0004משום \u0003נותר,\u0004 אם אוכלים לאחר הזמן המותר, \u0003ו\u0004כן \u0003טמא,\u0004 אסור לו לאכול את הפסח, ויש אם כן לומר שמפני חומרתו וקדושתו גם ערל אסור בו, אבל בתרומה מניין לנו. אלא \u0003לאיי\u0004 \u0005[\u0006אכן, \u0005באמת],\u0006 \u0003אפנויי מופנה\u0004 הוא, ואינו נחוץ לגופו ויש איפוא ללמוד ממנו גזירה שווה.","ושואלים: \u0003הי\u0004 \u0005[איזה\u0006 מהם\u0005],\u0006 מן הביטויים \"תושב ושכיר\", \u0003מופנה,\u0004 לדרשה? \u0003אי\u0004 \u0005[אם]\u0006 זה שנאמר ב\u0003תרומה,\u0004 הלא \u0003מצרך צריכי\u0004 \u0005[נצרכות\u0006 הן המילים הללו\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"תושב\" — זה\u0004 עבד עברי ה\u0003קנוי קנין עולם\u0004 (עבד נרצע), ו\u0003\"שכיר\" — זה\u0004 עבד עברי ש\u0003קנוי קנין שנים,\u0004 ששניהם אינם אוכלים בתרומה בעודם אצל אדונם.","ושואלים: \u0003ויאמר \"תושב\"\u0004 שאסור לו לאכול בתרומה \u0003ואל יאמר \"שכיר\", ואני אומר\u0004 קל וחומר: אם זה ה\u0003קנוי קנין עולם אינו אוכל — זה שאינו קנוי\u0004 אלא \u0003קנין שנים לא כל שכן!\u0004","ומשיבים: \u0003אילו\u0004 היה כתוב \u0003כן, הייתי אומר\u0004 ש\u0003\"תושב\"\u0004 זה שנאמר \u0003זה\u0004 ה\u0003קנוי קנין שנים\u0004 והוא שאינו אוכל בתרומה, \u0003אבל\u0004 ה\u0003קנוי קנין עולם — אוכל,\u0004 לכך כתב את שניהם ו\u0003בא\u0004 ה\u0003\"שכיר\" ולימד על \"תושב\"\u0004 שכוונתו עבד המשועבד לצמיתות לבעליו. \u0003שאף על פי שקנוי קנין עולם — אין אוכל.\u0004","\u0003אלא\u0004 זה של \u0003פסח מופני\u0004 \u0005[מופנה]\u0006 לדרשה, כי \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"תושב ושכיר\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003בפסח מאי ניהו\u0004 \u0005[מהו]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 שהוא \u0003תושב ושכיר ממש,\u0004 כלומר, עבד עברי שנמכר למספר שנים או לעולם — דבר זה אינו מתקבל על הדעת, וכי \u0003משום דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003תושב ושכיר איפטר ליה\u0004 \u0005[נפטר לו]\u0006 \u0003מ\u0004מצות ה\u0003פסח?\u0004 ואם תאמר שכן הוא, שהעבד העברי גם הוא נחשב כקנין גמור (כמו העבד הכנעני) ואינו חייב עוד בכל המצוות כבן חורין, — \u0003והא קיימא לן גבי\u0004 \u0005[והרי מוחזק לנו,\u0006 ויודעים אנו \u0005אצל]\u0006 \u0003תרומה דלא אכיל\u0004 \u0005[שאינו אוכל]\u0006 אצל אדוניו הכהן?"],["\u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003ש\u0004\u0003לא קני ליה רביה\u0004 \u0005[קנה אותו רבו,\u0006 אדונו\u0005]\u0006 לגופו, לשנות את מעמדו, והוא נשאר ישראל גמור לכל דבר. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי פסח \u0003לא קני ליה רביה\u0004 \u0005[קנה אותו רבו]\u0006 שיהא כעבד, ואם כן הביטוי מיותר, \u0003אלא\u0004 ודאי \u0003לאפנויי\u0004 \u0005[להפנות אותו]\u0006 ללימוד לענין אחר.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 הלא \u0003מופנה מצד אחד\u0004 בלבד \u0003הוא, ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' אליעזר\u0004 ש\u0003אמר:\u0004 גזירה שווה ש\u0003מופנה מצד אחד\u0004 בלבד, אמנם \u0003למדין\u0004 ממנה, אבל \u0003ומשיבין\u0004 (דוחים) אותה אם יש מקום לחלק בין הדברים. וכיון שכאן יש מקום לחלק — מדוע תתקיים הגזירה השווה?","ומשיבים: \u0003כיון דלגופיה\u0004 \u0005[שלגופו]\u0006 של הענין \u0003לא צריך\u0004 את הביטוי \"תושב ושכיר\", וכיון שכך יש ייתור של שתי מילים — \u0003שדי חד\u0004 \u0005[הטל\u0006 ייתור \u0005אחד]\u0006 על ה\u0003למד ושדי חד\u0004 \u0005[והטל\u0006 \u0005אחד]\u0006 על ה\u0003מלמד\u0004 כאילו היה ייתור זה מחולק לשני העניינים, \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 כמו \u0003גזירה שוה מופנה משני צדדין\u0004 שאין משיבים עליה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כן, אם אמנם למדים אנו גזירה שווה זו, הרי הכלל הוא שאין גזירה שווה למחצה, ונוכל לומר עוד בגזירה שווה: \u0003מה ב\u0004קרבן \u0003פסח, אונן\u0004 (מי שמת לו מת ועדיין לא נקבר) \u0003אסור בו — אף תרומה\u0004 יהא \u0003אונן אסור בה.\u0004 ואנחנו יודעים שאינו כן!","\u0003אמר ר' יוסי בר חנינא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכל זר\u0004 לא יאכל קודש\u0003\"\u0004 (ויקרא כב, י), הרי זה בא להדגיש: פסול של \u0003זרות אמרתי לך\u0004 שמונע מלאכול בתרומה, \u0003ולא\u0004 פסול \u0003אנינות.\u0004 ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש את המיעוט בדרך אחרת: פסול זרות \u0003ולא ערלות,\u0004 ויהא איפוא הערל מותר באכילת תרומה! ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"תושב ושכיר\"\u0004 בתרומה ו\"תושב ושכיר\" בפסח, ולומדים בגזירה שווה שערל אסור.","ושואלים: \u0003ומה ראית\u0004 להוציא אונן מאיסור אכילת תרומה ולהכניס ערל, אולי יהא הלימוד להיפך? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003ערלות הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לאסור את הערל באכילת תרומה, \u0003שכן\u0004 יש כמה צדדים להחמיר בו, וסימן לדבר: \u0003מעשי\"ם כרותי\"ם בדב\"ר העב\"ד.\u0004 ומפרטים: שכן הערל הוא \u0003מחוסר מעשה\u0004 המילה, \u0003ו\u0004ה\u0003מעשה\u0004 הוא \u0003בגופו\u0004 (\"מעשי\"ם\"), \u0003ו\u0004הוא איסור חמור ש\u0003ענוש כרת\u0004 עליו (\"כרותי\"ם\"), \u0003וישנו לפני הדבור\u0004 בהר סיני (\"בדב\"ר\"), שהרי מצוה זו ניתנה עוד לאברהם אבינו, \u0003ומילת זכריו ועבדיו מעכבת\u0004 את בעליהם מלאכול קרבן פסח (\"העב\"ד\") כמפורש בכתוב!","ומקשים: \u0003אדרבה\u0004 (להיפך) \u0003אנינות הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 שהרי אף בה ישנם כמה צדדי חיוב אחרים; \u0003שכן ישנה בכל שעה\u0004 שמת לו מת, ואינה כמילה שחיובה פעם אחת בלבד, \u0003ונוהגת באנשים ונשים\u0004 שלא כמילה, \u0003ואין בידו לתקן את עצמו\u0004 עד הקבורה! ומשיבים: אף על פי כן, \u0003הנך נפישן\u0004 \u0005[\u0006נימוקים \u0005אלה\u0006 בשביל ערלות \u0005מרובים\u0006 יותר\u0005].\u0006","\u0003רבא אמר: בלא\u0004 הנימוק של \u0003הנך נפישן\u0004 \u0005[אלה מרובים]\u0006 \u0003נמי לא מצית אמרת\u0004 \u0005[גם כן אינך יכול לומר]\u0006 שאנינות היא שנאסרה על ידי הגזירה שווה, שכן האם \u0003שבקינן\u0004 \u0005[עוזבים אנו]\u0006 ענין \u0003ערלות דכתיב בגופיה\u0004 \u0005[שנאמר בגופו]\u0006 של ה\u0003פסח\u0004 לאיסור, \u0003וילפינן\u0004 \u0005[ולומדים אנו]\u0006 דין \u0003אנינות\u0004 בגזירה שווה \u0003מפסח,\u0004 כאשר דין זה שאונן אסור בפסח איננו כתוב בו במפורש?! שאיסור אנינות שב\u0003פסח גופיה\u0004 \u0005[עצמו]\u0006 \u0003מ\u0004דין \u0003מעשר גמרינן\u0004 \u0005[אנחנו למדים]\u0006 לאסרו לאונן.","ומקשים מצד אחר: \u0003אי\u0004 \u0005[אם]\u0006 מצד הגזירה השווה, אם כן נאמר: \u0003מה פסח — מילת זכריו ועבדיו מעכבת\u0004 את האב והאדון מלאכול, \u0003אף\u0004 ב\u0003תרומה — מילת זכריו ועבדיו מעכבת\u0004 את האדון מלאכול!","ודוחים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסח: \u0003\"ומלתה אתו אז יאכל בו\"\u0004 (שמות יב, מד), והדגשה \"בו\" באה ללמד: \u0003מילת זכריו ועבדיו מעכבת בו\u0004 בלבד, כלומר, רק \u0003מלאכול בפסח,\u0004 אבל \u0003אין מילת זכריו ועבדיו מעכבת בתרומה.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה למד מ\"בו\" למעט כל דבר אחר, \u0003אימא\u0004 \u0005[אמור]\u0006 אם כן דרשה זו גם לענין ערלות, שהרי נאמר בפסח \u0003\"\u0004ו\u0003כל ערל לא יאכל בו\"\u0004 (שם, מח) ותדרוש: הערל, \u0003בו,\u0004 בפסח, \u0003אינו אוכל, אבל אוכל הוא בתרומה!\u0004 ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 בתרומה \u0003\"תושב ושכיר\"\u0004 שבא ללמדנו גזירה שווה מפסח לאסור את הערל באכילת תרומה!","ושואלים: \u0003ומה ראית\u0004 לרבות דווקא ערל ולא דבר אחר? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003ערלות דגופיה\u0004 \u0005[ש\u0006ב\u0005גופו]\u0006 \u0003הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 \u0003שכן\u0004 זה הוא \u0003מעשה בגופו, וענוש כרת\u0004 על העדר המילה. ושואלים: \u0003אדרבה\u0004 (להיפך) \u0003מילת זכריו ועבדיו הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לאיסור, \u0003שכן ישנה בכל שעה,\u0004 שבכל שעה שהם אצלו, בבעלותו, חלה המצוה עליו!","ומשיבים: \u0003הנך נפישן\u0004 \u0005[אלה\u0006 הנימוקים של \"ערלות בגופו\" \u0005מרובים].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003בלא הנך נפישן נמי לא מצית אמרת\u0004 \u0005[בלא \"אלה מרובים\" גם כן אינך יכול לומר\u0006 כדבריך\u0005],\u0006 שכן \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003ערלות דגופיה\u0004 \u0005[של גופו,\u0006 עצמו\u0005]\u0006 \u0003לא מעכבא ביה\u0004 \u0005[מעכבת בו],\u0006 כפי שאתה מציע, ו\u0003ערלות דאחריני\u0004 \u0005[של אחרים]\u0006 \u0003מעכבא ביה\u0004 \u0005[מעכבת בו]?!\u0006 אלא ודאי נלמד מכאן שערל עצמו אסור לאכול בתרומה, ואין מילת זכריו ועבדיו מעכבת.","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 ש\u0003\"בו\"\u0004 הכתוב בענין זה \u0003לדרשה הוא דאתא\u0004 \u0005[שבא]\u0006 ולהוציא דברים אחרים — מה שנאמר \u0003\"כל בן נכר לא יאכל בו\"\u0004 (שם מג) \u0003למה לי?\u0004 ומשיבים: גם זה בא ללמד: בקרבן פסח שרק \u0003בו\u0004"],["\u0003משמדות פוסלת,\u0004 כלומר: שהממיר דתו הוא הקרוי \"בן נכר\" ופסול מלאכול בפסח, \u0003ואין משמדות פוסלת במעשר.\u0004","ושואלים: אם כן \u0003\"\u0004ו\u0003כל ערל לא יאכל בו\"\u0004 (שמות יב, מח), שבא להדגיש: בו ולא בדבר אחר, \u0003למה לי?\u0004 ומשיבים: \u0003בו,\u0004 בקרבן פסח, המשומד \u0003אינו אוכל, אבל אוכל הוא במצה ומרור.\u0004","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"ערל\", ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"כל בן נכר\". דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 \u0003\"ערל\"\u0004 בלבד, הייתי אומר \u0003משום דמאיס\u0004 \u0005[ש\u0006הוא \u0005מאוס]\u0006 בזה שיש לו ערלה, ולכן הוא דחוי. \u0003אבל בן נכר, דלא מאיס\u0004 \u0005[שאינו מאוס]\u0006 בגופו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004 ולהיפך: \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"כל בן נכר\"\u0004 הייתי אומר: \u0003משום\u0004 ש\u0003אין לבו לשמים,\u0004 ולכן אסור לו לאכול את הפסח, \u0003אבל ערל\u0004 ישראל ש\u0003לבו לשמים\u0004 ורק מחמת אונס אינו יכול למול, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייכתבו שני הדברים.","ושואלים: מה שנאמר \u0003\"ממנו\" \"ממנו\"\u0004 (\"אל תאכלו ממנו נא\". שמות יב ט. \"ולא תותירו ממנו עד בוקר\". שם י) שהוא לשון מיעוט, \u0003למה לי?\u0004 ומשיבים: \u0003ל\u0004אותם דברים שאמר \u0003רבה אמר ר' יצחק,\u0004 כאשר יבואר להלן.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהובאה לעיל, \u0003ר' עקיבא אומר: אינו צריך\u0004 ללמוד דין ערל מגזירה שווה של \"תושב ושכיר\", אלא \u0003הרי הוא אומר \"איש איש\u0004 מזרע אהרן והוא צרוע או זב בקדשים לא יאכל\u0003\"\u0004 (ויקרא כב, ד), ולשון \"איש איש\" באה \u0003לרבות את הערל\u0004 שאף הוא אסור באכילת קדשים. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003לרבות את האונן\u0004 שאסור בתרומה? \u0003אמר ר' יוסי בר' חנינא: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכל זר\u0004 לא יאכל בו\" (שם י), משמע: \u0003זרות אמרתי לך\u0004 שפוסלת, \u0003ולא אנינות.\u0004","ושואלים: \u0003אימא\u0004 \u0005[אמור],\u0006 למד מן הכתוב, \u0003ולא ערלות\u0004 פוסלת בו? ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 ריבוי \u0003\"איש איש\"\u0004 לרבות אף את הערל לאיסור.","ושואלים: \u0003ומה ראית\u0004 לרבות ערילות ולמעט אנינות, אולי להיפך? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003ערלות הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 \u0003שכן\u0004 יש בה כמה צדדים חמורים שסימנם: \u0003מעשי\"ם כרותי\"ם בדב\"ר העב\"ד.\u0004 ומפרטים: \u0003מחוסר מעשה,\u0004 שצריך למול, \u0003ו\u0004ה\u0003מעשה\u0004 הוא מעשה \u0003בגופו\u0004 (\"מעשי\"ם\")\u0003, וענוש כרת\u0004 אם לא יעשנו (\"כרותי\"ם), \u0003וישנו לפני הדבור\u0004 (\"בדב\"ר\"), \u0003ומילת זכריו ועבדיו מעכבת\u0004 את בעליהם מלאכול בפסח (\"העב\"ד\").","ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003אנינות הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 \u0003שכן\u0004 אף בה יש צדדים חמורים, שהרי \u0003ישנה בכל שעה\u0004 משעות היממה, \u0003ונוהגת באנשים ו\u0004ב\u0003נשים, ואין בידו לתקן עצמו\u0004 עד לקבורה!","ומשיבים: \u0003הנך נפישן\u0004 \u0005[אלה,\u0006 החומרות של ערילות, \u0005מרובות]\u0006 מהחומרות של אנינות. \u0003רבא אמר: בלא\u0004 הנימוק הטוען כי \u0003הנך נפישן\u0004 \u0005[אלה מרובות]\u0006 \u0003נמי לא מצית אמרת\u0004 \u0005[גם כן אינך יכול לומר]\u0006 זאת, כי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"איש איש\"\u0004 ומכאן נלמד שריבוי זה בא לענין מיוחד, ש\u0003איזהו דבר שישנו באיש ואינו באשה — הוי אומר זה ערלות,\u0004 ולכן אין לייחס ריבוי זה לענין אנינות.","ושואלים: \u0003ור' עקיבא האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"תושב ושכיר\"\u0004 שהוא מיותר בפסח, \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה לו]?\u0006 \u0003אמר רב שמעיא: לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003ערבי מהול וגבעוני מהול,\u0004 שאף שהם נימולים — אסורים הם לאכול בפסח.","ושואלים: \u0003והני מולין נינהו\u0004 \u0005[ו\u0006כי \u0005אלה\u0006 נחשבים \u0005נימולים הם]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 אם אמר אדם בנדר: \u0003\"קונם\u0004 (יהא אסור עלי כקודש) \u0003שאני נהנה לערלים\" — מותר\u0004 ליהנות \u0003בערלי ישראל, ואסור במולי\u0004 (במהולי) \u0003אומות העולם.\u0004 שכן שגם המהולים שבין הגויים נקראים ערלים, ולהיפך, אם אמר \u0003\"קונם שאני נהנה למולין\" — מותר במולי אומות העולם ואסור בערלי ישראל,\u0004 משמע שאין מילת גויים נחשבת!","\u0003אלא,\u0004 יש לומר כי הכתוב בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003גר שמל ו\u0004עדיין \u0003לא טבל, וקטן שנולד כשהוא מהול,\u0004 שאמנם אין לו ערלה, אבל עדיין חסר בו מעשה מילה. \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 ש\u0003צריך להטיף ממנו\u0004 על כל פנים \u0003דם ברית,\u0004 כדי להכניסו בבריתו של אברהם אבינו, אף שאין לו ערלה שיהיו חייבים לכרות אותה.","\u0003ור' אליעזר\u0004 שלומד \"תושב ושכיר\" לגזירה שווה הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: גר שמל ולא טבל\u0004 — \u0003גר מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 ולכן לא בא הכתוב למעטו, \u0003ו\u0004לענין קטן שנולד מהול \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003קטן כשנולד מהול אין צריך להטיף ממנו דם ברית,\u0004 שכיון שהוא מהול אין צורך במילה נוספת.","ושואלים: \u0003ור' אליעזר האי\u0004 \u0005[זה]\u0006 הריבוי \u0003\"איש איש\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו]?\u0006 ומשיבים: סבור הוא כי \u0003דברה תורה כלשון בני אדם,\u0004 וכפל זה לא בא ללמדנו לרבות מייתור מילים, ואין זה אלא סגנון הדיבור של הכתוב.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חמא בר עוקבא: קטן\u0004 לפני שהגיע זמנו לימול \u0003מהו לסוכו\u0004 (לסוך אותו) \u0003בשמן של תרומה?\u0004 והשאלה היא: \u0003ערלות שלא בזמנה\u0004 שלפני זמן חיוב המילה, האם \u0003מעכבא\u0004 \u0005[מעכבת],\u0006 שאנחנו אומרים שיש לו דין ערל והוא אסור בתרומה, \u0003או\u0004 שמא \u0003לא מעכבא\u0004 \u0005[אינה מעכבת]?\u0006 שמכיון שלא חלה עליו עדיין מצות מילה אינו קרוי ערל לענין זה?!","\u0003אמר ר' זירא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר ממה ששנינו בברייתא: \u0003אין לי אלא מילת זכריו\u0004 המעכבת \u0003בשעת עשיה\u0004 של קרבן הפסח (שנאמר: \"המול לו כל זכר ואז יקרב לעשותו\". שמות יב, מח) מילת \u0003עבדיו\u0004 מעכבת \u0003בשעת אכילה\u0004 של קרבן פסח (שנאמר: \"וכל עבד איש... ומלתה אותו אז יאכל בו\". שם מד), \u0003מנין ליתן את האמור של זה בזה, ואת האמור של זה בזה,\u0004 שבין זכרים ובין עבדים מילתם מעכבת הן בעשייה הן באכילה — \u0003תלמוד לומר: \"אז\" \"אז\" לגזירה שוה.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003עבדיו משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא אותה]\u0006 אפשרות \u0003דאיתנהו\u0004 \u0005[ש\u0006הם \u0005מצויים]\u0006 \u0003בשעת אכילה וליתנהו\u0004 \u0005[ואינם מצויים]\u0006 \u0003בשעת עשיה,\u0004 ו\u0003כגון דזבנינהו ביני ביני\u0004 \u0005[שקנה אותם בינתיים],\u0006 שקנה אותם לאחר עשיית הפסח, לפני זמן אכילתו,","\u0003אלא זכריו דאיתנהו\u0004 \u0005[שישנם]\u0006 \u0003בשעת אכילה וליתנהו\u0004 \u0005[ואינם]\u0006 \u0003בשעת עשיה היכי משכחת לה\u0004 \u0005[איך אתה\u0006 יכול \u0005למצוא אותה\u0006 אפשרות\u0005] —\u0006 \u0003לאו דאתילוד\u0004 \u0005[\u0006האם \u0005לא\u0006 במקרה \u0005שנולדו]\u0006 \u0003בין עשיה לאכילה,\u0004 ו\u0003שמע מינה\u0004 \u0005[למד ממנה\u0006 מכאן\u0005]\u0006 פתרון לספק שהעלינו כי \u0003ערלות\u0004 אף \u0003שלא בזמנה הויא\u0004 \u0005[הריהי]\u0006 \u0003ערלות\u0004 ומעכבת את הפסח!","\u0003אמר רבא: ותסברא\u0004 \u0005[ו\u0006יכול אתה \u0005לסבור\u0006 כן\u0005]\u0006 שמילה של קטנים לפני זמנה מעכבת? הלא \u0003\"המול לו כל זכר\"\u0004 (שמות יב, מח) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 \u0003\"ואז יקרב לעשתו\"\u0004 (שם), \u0003והאי לאו בר מהילא\u0004 \u0005[וזה,\u0006 הקטן, \u0005לא בן מילה]\u0006 \u0003הוא,\u0004 שעדיין אי אפשר למולו, ובודאי אינו יכול לעכב. \u0003אלא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003שחלצתו חמה\u0004 (עזבו החום ונתרפא) כלומר, שקודם היה התינוק חולה והיה לו חום, ולא יכלו למולו, ולכשנתרפא לאחר שמונה ימים חלה עליו מצות מילה, ולכן אם לא מל אותו — מילת התינוק מעכבתו.","ומקשים: אם מדובר במקרה שהבריא התינוק מהמחלה \u0003וניתוב ליה\u0004 \u0005[וניתן לו]\u0006 \u0003כל שבעה\u0004 מאותו זמן שהבריא, כדי למולו. שהרי \u0003אמר שמואל:\u0004 תינוק שחלה בתוך שמונת הימים הראשונים ללידתו ואי אפשר היה למול אותו ו\u0003חלצתו חמה\u0004 — \u0003נותנין לו כל שבעה\u0004 ימים אחר כך, ומלים אותו רק בסופם, ולא מיד כשהבריא, ואם כן, אף שהבריא, כל אותם שבעה ימים, כיון שאסור למולו בהם, הריהו נחשב כזה שעדיין לא הגיע זמן מילתו ואינו בן חיוב! ומשיבים: \u0003דיהבינן ליה\u0004 \u0005[שאנו נותנים לו]\u0006 באמת את \u0003כל\u0004 ה\u0003שבעה\u0004 ימים הללו אלא ששבעת הימים הללו נגמרו יום לפני ערב פסח. ושואלים: אם אמנם נסתיימו שבעת הימים הללו לפני ערב פסח, מדוע המתין לו עד זמן אכילת הפסח \u0003ונימהליה מצפרא\u0004 \u0005[ושימול אותו מ\u0006שעות ה\u0005בוקר]!\u0006 קודם זמן הקרבת הפסח! ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006"],["\u0003מעת לעת,\u0004 כלומר, שתהיינה שבע יממות שלימות, ואם הבריא ממחלתו רק בשעה מסויימת אחר הצהרים ביום מסויים, צריך להמתין עד אותה שעה לאחר שבע יממות כדי למול אותו.","אולם \u0003והתני לודאה\u0004 \u0005[והרי שנה\u0006 החכם \u0005מלוד]:\u0006 \u0003יום הבראתו כיום הולדו. מאי לאו\u0004 \u0005[האם לא]\u0006 התכוון לומר: \u0003מה יום הולדו לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעת לעת,\u0004 שיהיו שמונה ימים שלמים משעה לשעה מרגע לידתו, \u0003אף יום הבראתו לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 למנות שבעה ימים \u0003מעת לעת?\u0004","ודוחים: \u0003לא, עדיף יום הבראתו מיום הולדו.\u0004 ש\u0003אילו\u0004 לענין \u0003יום הולדו לא בעינן\u0004 \u0005[צריכים אנו]\u0006 למנות את הימים \u0003מעת לעת,\u0004 וכשמגיע יום השמיני, לפי חשבון הימים, אפשר למולו, \u0003ואילו יום הבראתו\u0004 כן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003מעת לעת.\u0004","\u0003רב פפא אמר: כגון דכאיב ליה עיניה לינוקא\u0004 \u0005[שכאבה לו עינו לתינוק]\u0006 ביום השמיני ללידתו שהיה בערב פסח \u0003ואיתפח ביני וביני\u0004 \u0005[והבריא בינתיים]\u0006 בין עשיית הקרבן לזמן אכילתו. שבמחלה קלה, כגון כאב עיניים, אף שאין מלים אותו באותה שעה, מכל מקום אין צורך להמתין לו שבעה ימים שלמים ומלים אותו מיד כשמבריא.","\u0003רבא אמר: כגון שהיו אביו ואמו חבושין בבית האסורין\u0004 בשעת עשיית הפסח ושחטו פסחם באמצעות שליח, ולא היה מי שימול אותו, ונשתחררו מכלאם כשהגיע זמן אכילת הפסח.","\u0003רב כהנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמיה אמר: כגון טומטום שנקרע.\u0004 שהיה הילד מתחילתו טומטום, שהיה אברו מכוסה קרום בשעת לידתו ולא היתה לו זכרות, ואי אפשר היה למולו, ואחר כך נקרע הכיסוי, \u0003ונמצא זכר ביני וביני\u0004 \u0005[בינתיים]\u0006 בין זמן עשיית הפסח לזמן אכילתו, ואז חלה עליו חובת המילה.","\u0003רב שרביא אמר: כגון שהוציא ראשו חוץ לפרוזדור\u0004 הרחם לפני שבעה ימים ולא יצא כל גופו החוצה אף בזה כבר נחשב הוא לילוד, ונגמרה לידתו, שיצא כל גופו, ביום השמיני, בדיוק בזמן שבין עשיית הפסח ואכילתו ואז ראוי למולו.","ושואלים: במקרה כזה \u0003ומי חיי\u0004 \u0005[והאם\u0006 יכול הוולד \u0005לחיות]\u0006 זמן רב כל כך במצב זה שרק ראשו בחוץ? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיון שיצא\u0004 התינוק \u0003לאויר העולם — נפתח\u0004 בו מה שהיה \u0003הסתום,\u0004 פיו ונחיריו, \u0003ונסתם הפתוח\u0004 הטבור שממנו היה ניזון בהיותו עובר. \u0003שאלמלא\u0004 היה קורה \u0003כן אין יכול לחיות אפילו שעה אחת,\u0004 שאין לו דרך אחרת להיזון. ואם כן ילד זה שיצא רק ראשו מרחם אמו ועדיין איננו יכול להיזון ודאי ימות מרעב!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון דזנתיה אישתא\u0004 \u0005[שהזינתו הקדחת],\u0006 כלומר, מחמת חום הקדחת, אינו צריך אכילה. ושואלים: \u0003אישתא דמאן\u0004 \u0005[קדחת של מי]\u0006 \u0003אילימא אישתא דידיה\u0004 \u0005[אם תאמר קדחת שלו]\u0006 שהתינוק עצמו היה לו חום, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כל שבעה\u0004 ימים \u0003בעי\u0004 \u0005[\u0006היה \u0005צריך]\u0006 להמתין מאז שיצא כל גופו כדי למולו, שהרי, כאמור, תינוק שחלה והבריא, מונים לו שבעה ימים עד שמלים אותו? \u0003אלא דזנתיה אישתא דאימיה\u0004 \u0005[שזנה אותו קדחת של אמו].\u0006 \u0003ואיבעית אימא הני מילי היכא דלא מעוי\u0004 \u0005[ואם תרצה אמור: דברים אלה,\u0006 שהילד אינו יכול לחיות, אמורים \u0005במקום שאינו צועק],\u0006 \u0003אבל היכא דמעוי\u0004 \u0005[במקום שצועק],\u0006 \u0003מחייא חיי\u0004 \u0005[\u0006יכול \u0005הוא לחיות]\u0006 כי הצעקה מוכיחה שהתחיל כבר לנשום.","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' בנאה:\u0004 ישראל שהוא \u0003ערל — מקבל הזאה\u0004 לטומאת המת, ואין אנו אומרים שהזאה בשעת ערילות אינה נחשבת. \u0003שכן מצינו באבותינו שקבלו הזאה כשהן ערלים, שנאמר: \"והעם עלו מן הירדן בעשור לחדש הראשון\"\u0004 (יהושע ד, יט), ומסופר כי לאחר מכן נימולו כולם, וביום ארבעה עשר עשו את הפסח (שם ה, י).","ונברר מתי נימולו: \u0003ב\u0004יום \u0003עשרה\u0004 עצמו \u0003לא מהילי\u0004 \u0005[מלו],\u0006 \u0003משום חולשא דאורחא\u0004 \u0005[חולשת הדרך],\u0006 ואם כן, \u0003הזאה אימת עביד להו\u0004 \u0005[מתי עשה להם]\u0006 לטהרם מטומאת המת כדי שיהיו ראויים לפסח, שבשביל להיטהר צריך להמתין ארבעה ימים בין הזאה ראשונה לשניה?! — \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר שהיזו עליהם \u0003כשהן ערלים?\u0004 והרי הוכחה שמזים גם על ערלים!","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא עבוד\u0004 \u0005[עשו]\u0006 \u0003פסח כלל?\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דכתיב\u0004 \u0005[ש\u0006הלא \u0005נאמר]\u0006 \u0003\"ויעשו את הפסח\"\u0004 (שם ה, י).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003פסח הבא בטומאה היה?\u0004 שהרי אם כל הציבור טמא — מביאים כולם קרבן פסח בטומאה, ולא נזקקו כלל להזאה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: תניא בהדיא\u0004 \u0005[שנינו במפורש\u0006 בברייתא\u0005]:\u0006 \u0003מלו, וטבלו, ועשו פסחיהן בטהרה.\u0004","\u0003אמר רבה בר יצחק אמר רב: לא ניתנה פריעת מילה לאברהם אבינו.\u0004 כלומר, כשניתנה מצות מילה לאברהם — היתה המצוה רק מילה בלבד ולא פריעת הערלה, \u0003שנאמר: \"בעת ההיא אמר ה' אל יהושע עשה לך חרבות צרים\u0004 ושוב מול את בני ישראל שנית","\u0003\"\u0004(שם ה, ב) ומדוע הוצרך למולם? אלא כיון שחלק מהם היו מולים מלפני מתן תורה בסיני, ומילה זו לא היתה מילה כדת ישראל, אלא מילה רק כדרך שהיתה לאברהם, בלא פריעה, לכן הוצרכו לפרוע, והיא המילה השניה. ושואלים: ומניין יודעים שמלו שנית את אלו שהיו כבר נימולים, \u0003ודלמא הנך\u0004 \u0005[ושמא\u0006 מלו את \u0005אלה]\u0006 ש\u0003לא מהול\u0004 \u0005[מלו]\u0006 כלל, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי מלים היו כל העם היצאים וכל העם הילדים\u0004 במדבר בדרך בצאתם ממצרים לא מלו\u0003\"\u0004(שם ה, ה).","ומשיבים: \u0003אם כן,\u0004 שהמילה היתה רק לאלה שלא נימולו כלל, \u0003מאי\u0004 \u0005[מה]\u0006 אם כן פירוש \"ו\u0003שוב\u0004 מול\"? שמשמע שצריכים למול אותם שנית. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה \u0003לפריעה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"שנית\"\u0004 שנאמר שם, שהוא מיותר שהרי כבר נאמר \"שוב\" — ללמדנו דבר נוסף","\u0003לאקושי\u0004 \u0005[להקיש,\u0006 להשוות\u0005]\u0006 \u0003סוף מילה,\u0004 שלעתים יש צורך למול שנית כדי לתקן מילה שנעשתה שלא כדין \u0003לתחלת מילה; מה תחלת מילה מעכבת,\u0004 אם לא נעשתה המילה כדין — \u0003אף סוף מילה,\u0004 אם לא נחתכה הערלה כראוי \u0003מעכבין בו. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו הן ציצין\u0004 (שאריות עור) \u0003המעכבין את המילה\u0004 שאם לא נחתכו אין זו מילה כשרה — \u0003בשר\u0004 הערלה \u0003החופה את רוב העטרה, ואין אוכל בתרומה\u0004 כשלא הסירו את החלקים הללו של הערלה.","ולענין זה \u0003אמר רבינא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב ירמיה בר אבא אמר רב:\u0004 שהוא \u0003בשר החופה את רוב גובהה של עטרה,\u0004 ולא רק רוב היקפה.","לגופו של מעשה המילה על ידי יהושע שואלים: \u0003ובמדבר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא מהול\u0004 \u0005[מלו]\u0006 לאחר מתן תורה? משיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שלא מלו אז \u0003משום חולשא דאורחא\u0004 \u0005[חולשת הדרך],\u0006 שכיון שהיו צריכים כל הזמן ללכת בדרך, לא יכלו למול מחמת חולשה,"],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003משום\u0004 ש\u0003לא נשיב להו\u0004 \u0005[נשבה להם]\u0006 \u0003רוח צפונית,\u0004 וכיון שהיה מזג האויר חם מדי עלול היה לגרום לסיבוך במילה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל אותן ארבעים שנה שהיו ישראל במדבר לא נשבה להם רוח צפונית.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003משום\u0004 ש\u0003נזופים הוו\u0004 \u0005[היו]\u0006 אחר חטא המרגלים, ולא היו ראויים לרוח נוחה זו. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 כדי ש\u0003לא נבדור\u0004 \u0005[יתפזרו]\u0006 \u0003ענני\u0004 ה\u0003כבוד\u0004 שהיו על המשכן.","\u0003אמר רב פפא: הלכך\u0004 \u0005[על כן]\u0006 מכאן נלמד כי \u0003יומא דעיבא\u0004 \u0005[יום מעונן]\u0006 \u0003ויומא דשותא\u0004 \u0005[ויום של רוח דרומית]\u0006 שהיא הקשה שבין הרוחות — \u0003לא מהלינן ביה\u0004 \u0005[אין אנו מלים בו],\u0006 \u0003ולא מסוכרינן ביה\u0004 \u0005[ואין אנו מקיזים בו\u0006 דם\u0005],\u0006 משום שהדבר מסוכן. ומעירים: \u0003והאידנא דדשו בה\u0004 \u0005[ובזמננו ש\u0006כבר \u0005התרגלו בכך]\u0006 \u0003רבים\u0004 ואינם מקפידים, אפשר לומר על כך \u0003\"שומר פתאים ה'\"\u0004 (תהלים קטז, ה), שלא ייגרם נזק על ידי כך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל אותן ארבעים שנה שהיו ישראל במדבר לא היה יום שלא נשבה בו רוח צפונית בחצי הלילה, שנאמר: \"ויהי בחצי הלילה וה' הכה כל בכור\"\u0004 (שמות יב, כט). ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד],\u0006 איך אפשר ללמוד כן מפסוק זה, מה הקשר בין הדברים, והרי פסוק זה נאמר ביציאת מצרים? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003עת רצון — מילתא היא\u0004 \u0005[דבר הוא],\u0006 שכיון שהיתה פעם עת רצון בחצות — נמשכה עת רצון כעין זו באותה שעה כל הארבעים שנה ששהו במדבר.","\u0003אמר רב הונא: דבר תורה, משוך\u0004 כלומר, מי שהיה נימול ואחר כך נמשכה ערלתו מאליה, או משך הוא את ערלתו שתכסה את אברו — \u0003אוכל בתרומה,\u0004 כי הוא נחשב לנימול, \u0003ו\u0004אולם \u0003מדבריהם\u0004 (של חכמים) \u0003גזרו עליו\u0004 שימול שנית, \u0003מפני שנראה כערל.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003משוך צריך שימול!\u0004 ומשיבים: הכוונה היא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006 ותוהים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ומי שהקשה אותה מה הקשה אותה]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 לשון \u0003\"צריך\" קתני\u0004 \u0005[שנה]\u0006 ואילו היה הדבר חובה מן התורה היה אומר \"חייב\"!","ומסבירים: \u0003קטעי בסיפא\u0004 \u0005[טעה ב\u0006גלל \u0005סופה]\u0006 של אותה ברייתא, שנאמר בה, \u0003ר' יהודה אומר: לא ימול, מפני שסכנה היא לו. אמרו לו: והלא הרבה\u0004 שהיו משוכים ו\u0003מלו בימי בן כוזיבא\u0004 (בר כוכבא) \u0003והולידו בנים ובנות, שנאמר: \"המול ימול\"\u0004 (בראשית יז, יג), וכפל הלשון בא ללמד: \u0003אפילו מאה פעמים, ואומר: \"את בריתי הפר\"\u0004 (שם יד) — \u0003לרבות את המשוך.\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואומר\",\u0004 כלומר, מדוע צריך להביא ראיה נוספת לאותו דבר — מטעם זה? \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"המול ימול\"\u0004 בא רק \u0003לרבות ציצין\u0004 (פיסות בשר קטנות) \u0003המעכבים את המילה\u0004 שצריך לחזור ולמולם — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003\"את בריתי הפר\" — לרבות את המשוך,\u0004 לרבות את זה שעשה מעשה והפר בכך את הברית בזה שמשך את ערלתו.","ו\u0003הוא,\u0004 המקשה שהקשה מראש הברייתא, \u0003סבר: מדקא נסיב לה תלמודא קרא\u0004 \u0005[מכיון שמביא\u0006 בסוף הברייתא \u0005לימוד\u0006 מן \u0005הכתוב]\u0006 — משמע כי ההלכה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא. ו\u0004באמת, \u0003לא היא,\u0004 לא כן, והדבר הוא רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 הוא רק \u0005סמך בלבד]\u0006 ולא מקור ההלכה.","\u0003מיתיבי\u0004 ממקור אחר: כהן \u0003טומטום\u0004 שאין ניכר בו אם הוא זכר או נקיבה — \u0003אין אוכל בתרומה,\u0004 אבל \u0003נשיו ועבדיו אוכלין\u0004 בתרומה. כהן \u0003משוך, ו\u0004כן מי ש\u0003נולד כשהוא מהול — הרי אלו אוכלים. אנדרוגינוס\u0004 שיש לו אברי מין של זכר ונקבה ונימול — \u0003אוכל בתרומה,\u0004 שהרי כהן הוא, ובין שהוא זכר בין שהוא נקיבה זכאי בתרומה, \u0003ואין אוכל בקדשים\u0004 כזכרי כהונה, שמא אינו זכר. \u0003טומטום אינו אוכל לא בתרומה ולא בקדשים\u0004 שמא הוא זכר וכיון שאין זכרותו ניכרת אי אפשר למולו, והרי הוא ערל.","\u0003קתני מיהת\u0004 \u0005[על כל פנים שנה]\u0006 ש\u0003משוך ונולד כשהוא מהול הרי אלו אוכלין\u0004 בתרומה, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב הונא!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003טומטום אינו אוכל בתרומה, נשיו ועבדיו אוכלים.\u0004 ותוהים: \u0003נשיו לטומטום מנא ליה\u0004 \u0005[מניין לו],\u0006 שהרי אין לו אבר זכרות כלל ואיך יכול לשאת אשה? \u0003אילימא דקדיש\u0004 \u0005[אם תאמר ש\u0006רק \u0005קידש\u0006 אשה\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טומטום שקידש\u0004 — לפי שהוא ספק זכר \u0003קדושיו קדושין,\u0004 וכך אם \u0003נתקדש\u0004 על ידי גבר — \u0003קדושיו קדושין\u0004 שהרי הוא גם ספק נקיבה — אולם","\u0003אימר דאמר לחומרא\u0004 \u0005[אמור שאמר\u0006 זאת \u0005להחמיר]\u0006 שאנחנו חוששים שמא זכר הוא ואינו נפטר אלא בגט, אבל \u0003לקולא מי אמרינן\u0004 \u0005[להקל,\u0006 להאכיל אשתו בתרומה, \u0005האם אנחנו אומרים\u0006 כן\u0005]?\u0006 והלא \u0003ספק אשה הוא, ואין אשה מקדשת אשה?\u0004","\u0003אמר אביי:\u0004 אמנם הכוונה לטומטום שזכרותו אינה נראית, אלא שמדובר כאן \u0003כשביציו ניכרות מבחוץ,\u0004 ומשום כך יודעים בו שזכר הוא, ויכול לקדש אשה, אף שאינו יכול לבוא עליה.","\u0003רבא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נשיו\"\u0004 — הכוונה היא ל\u0003אמו\u0004 שמת בעלה הכהן, שהיא אוכלת בשבילו בתרומה. ותוהים: \u0003אמו, פשיטא\u0004 \u0005[פשוט],\u0006 מובן מאליו שהיא אוכלת בגללו, שהרי הוא זרעה מן הכהן, בין אם הוא זכר בין אם הוא נקיבה! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי מי ש\u0003מוליד — מאכיל,\u0004 ומי \u0003שאין מוליד — אינו מאכיל,\u0004 וטומטום שאינו יכול להוליד אינו מאכיל את אמו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003טומטום אינו אוכל לא בתרומה ולא בקדשים, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי תנא רישא\u0004 \u0005[שנה\u0006 ב\u0005תחילת\u0006 הברייתא\u0005]\u0006 טומטום שהוא \u0003ערל ודאי\u0004 כשביציו מבחוץ שאינו אוכל, \u0003וקתני סיפא\u0004 \u0005[ושנה\u0006 ב\u0005סוף]\u0006 \u0003ספק ערל,\u0004 שהרי הטומטום הזה כשהוא מכוסה לגמרי ספק ערל הוא.","\u0003אלא לרבא טומטום דסיפא\u0004 \u0005[שבסופה]\u0006 \u0003למה לי\u0004 לחזור ולדבר בו? הרי כבר הוזכר בתחילה! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003טומטום\u0004 שאמרנו — \u0003ערל,\u0004 כלומר, שברור לנו שהוא ערל.","ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003ספק ערל לא אכיל\u0004 \u0005[אינו אוכל],\u0006 שהוא טומטום האמור בתחילה — \u0003ודאי ערל אכיל\u0004 \u0005[אוכל]?!\u0006 ומשיבים: בסגנון \u0003מה טעם קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין: \u0003מה טעם טומטום אינו אוכל בתרומה — מפני שספק ערל הוא, וערל אינו אוכל לא בתרומה ולא בקדשים.\u0004","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בשאלה אם משוך נחשב כערל מדין תורה. ששנינו בתוספתא: \u0003משוך, ו\u0004כן מי ש\u0003נולד כשהוא מהול, וגר שנתגייר כשהוא מהול\u0004 כבר, \u0003וקטן שעבר זמנו\u0004 ולא נימול, \u0003ושאר כל הנימולים,\u0004 ומסבירים: \u0003לאיתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 על ידי ביטוי זה \u0003מי שיש לו שתי ערלות,\u0004 שני עורות ערלה, שצריך להסיר את שניהם — כל אלה \u0003אינן נימולין אלא ביום. ר' אלעזר בר שמעון אומר:\u0004 אם היו נימולים \u0003בזמנו,\u0004 ביום השמיני —"],["\u0003אין נימולין אלא ביום,\u0004 ואם נימולים \u0003שלא בזמנו — נימולין ביום ובלילה. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 שחובת מילה ל\u0003משוך דאורייתא\u0004 \u0005[מן התורה]\u0006 ולכן נימול ביום בלבד אף שזה לאחר זמנו, \u0003ומר\u0004 \u0005[וחכם\u0006 זה, ר' אלעזר בר' שמעון\u0005]\u0006 \u0003סבר\u0004 כי חובת מילה ב\u0003משוך\u0004 היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי יכול אתה ל\u0005סבור]\u0006 שבכך נחלקו? והרי \u0003קטן שעבר זמנו מי איכא למאן דאמר דרבנן\u0004 \u0005[האם יש למי שאומר ש\u0006זה רק \u0005מדברי סופרים]?\u0006 הרי ודאי שחובת מילה חלה עליו מן התורה גם מן היום השמיני והלאה ולדעת הכל צריך למולו רק ביום!","\u0003אלא, דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 חובת ה\u0003משוך\u0004 למול היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וקטן שעבר זמנו — דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר: דרשינן\u0004 \u0005[דורשים אנו]\u0006 את הייתור \u0003\"וביום\",\u0004 שנאמר: \"וביום השמיני ימול בשר ערלתו\" (ויקרא יב, ג), וה־ו' היתירה באה לרבות שגם אם נימול שלא ביום השמיני — מכל מקום מילתו ביום דווקא. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר בר' שמעון\u0005]\u0006 \u0003סבר: לא דרשינן\u0004 \u0005[אין אנו דורשים]\u0006 \u0003\"וביום\",\u0004 אלא רק אם נימול ביום השמיני, מילתו ביום ולא בלילה, אך לאחר מכן יכולה להיעשות בכל שעה.","וראיה לדבר: \u0003כי הא דיתיב\u0004 \u0005[כמו זה שישב]\u0006 \u0003ר' יוחנן וקדריש\u0004 \u0005[ודרש]:\u0006 \u0003נותר,\u0004 שנשתייר מן הקרבנות לאחר זמן אכילתם וטעון שריפה — כשהוא \u0003בזמנו,\u0004 כלומר, באותו יום שבו נעשה נותר — \u0003אינו נשרף אלא ביום, שלא בזמנו — נשרף בין ביום בין בלילה.\u0004","\u0003ואיתיביה\u0004 \u0005[והקשה לו]\u0006 \u0003ר' אלעזר לר' יוחנן\u0004 מברייתא זו: \u0003אין לי אלא נימול לשמיני שאין נימול אלא ביום, מנין לרבות\u0004 הנימול \u0003לתשעה, לעשרה, לאחד עשר\u0004 ו\u0003לשנים עשר, מנין? תלמוד לומר: \"וביום\"\u0004 משמע שמלשון ריבוי זו אנו דורשים שחובת העשייה ביום קיימת לא רק ביום שמדובר בו.","\u0003ואפילו למאן דלא דריש\u0004 \u0005[למי שאינו דורש]\u0006 \u0003וא\"ו\u0004 כייתור האותיות, \u0003וא\"ו וה\"י\u0004 הבאות יחד, לכל הדעות \u0003דריש\u0004 \u0005[דורש]\u0006 לריבוי, ובנותר נאמר: \"והנותר מבשר הזבח ביום השלישי באש ישרף\" (ויקרא ז, יז), משמע שלמדים מן הריבוי גם בימים שאינם בזמנו. \u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' יוחנן.","\u0003בתר דנפק\u0004 \u0005[אחרי שיצא]\u0006 ר' אלעזר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש: ראיתי לבן פדת שיושב ודורש\u0004 בתורה \u0003כמשה מפי הגבורה,\u0004 שהתפעל מדרשתו של ר' אלעזר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש:\u0004 וכי \u0003דידיה\u0004 \u0005[שלו]\u0006 דרשה זו? הלא \u0003מתניתא\u0004 \u0005[ברייתא]\u0006 \u0003היא.\u0004 שאל אותו: \u0003היכא תנא ליה\u0004 \u0005[היכן שנויה לה\u0006 ברייתא זו\u0005]?\u0006 אמר לו: \u0003בתורת כהנים\u0004 (ספרא, מדרש ההלכה לספר ויקרא). \u0003נפק תנייה בתלתא יומי\u0004 \u0005[יצא\u0006 ר' יוחנן ו\u0005שנה\u0006 את כל ספר תורת כהנים \u0005בשלושה ימים]\u0006 \u0003וסברה בתלתא ירחי\u0004 \u0005[והבין אותה,\u0006 הגיע לידי סברה והבנה בה, \u0005בשלושה חודשים].\u0006","\u0003אמר ר' אלעזר:\u0004 כהן \u0003ערל שהזה\u0004 מי חטאת לטהר מטומאת המת — \u0003הזאתו כשרה. מידי דהוה\u0004 \u0005[כמו שהוא\u0006 בדבר\u0005]\u0006 \u0003טבול יום, שאף על פי שאסור ב\u0004אכילת \u0003תרומה, כשר בפרה\u0004 אדומה.","ומקשים: \u0003מה לטבול יום — שכן מותר ב\u0004אכילת \u0003מעשר\u0004 והוא חמור פחות מן הערל האסור במעשר! ומשיבים: \u0003אטו אנן\u0004 \u0005[וכי אנו]\u0006 \u0003לאכילה קאמרינן\u0004 \u0005[אמרנו],\u0006 \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003לנגיעה קאמרינן\u0004 \u0005[אמרנו]\u0006 וכך היתה ההוכחה: \u0003ומה טבול יום שאסור בנגיעה\u0004 ב\u0003תרומה\u0004 ואם נוגע בה פוסל אותה — \u0003מותר בפרה, ערל שמותר בנגיעה\u0004 לכל הדעות — \u0003אינו דין שמותר בפרה?!\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 כהן \u0003ערל שהזה — הזאתו כשרה. ומעשה היה\u0004 שכהן ערל היזה \u0003והכשירו חכמים\u0004 את \u0003הזאתו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003טומטום שקידש,\u0004 כלומר, שעירב אפר פרה אדומה במים — \u0003קידושו פסול, מפני שהוא ספק ערל, וערל פסול לקדש. ואנדרוגינוס\u0004 מהול \u0003שקידש\u0004 אפר פרה במים — \u0003קידושו כשר. ר' יהודה אומר: אף אנדרוגינוס שקידש קדושיו פסולים, מפני שספק אשה\u0004 הוא, \u0003ואשה פסולה מלקדש. קתני מיהא\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003ערל וספק ערל פסול מלקדש!\u0004","\u0003אמר רב יוסף: האי תנא\u0004 \u0005[תנא זה]\u0006 של הברייתא הפוסלת ערל — \u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' עקיבא הוא דמרבי ליה\u0004 \u0005[שמרבה אותו]\u0006 את ה\u0003ערל\u0004 שיהיה דינו לענין זה \u0003כטמא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' עקיבא אומר: \"איש איש\u0004 מזרע אהרן והוא צרוע או זב בקדשים לא יאכל...\u0003\"\u0004 (שם כב, ד) — \u0003לרבות\u0004 את \u0003הערל\u0004 שאף הוא אסור באכילת קדשים.","\u0003אמר רבא: הוה יתיבנא\u0004 \u0005[הייתי יושב]\u0006 באותו זמן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף וקשיא\u0004 \u0005[ו\u0006היה \u0005קשה]\u0006 \u0003לי:\u0004 וכי \u0003לא לישתמיט\u0004 \u0005[ישמט,\u0006 ימצא\u0005]\u0006 \u0003תנא וליתני\u0004 \u0005[ושישנה]\u0006 \u0003הערל והטמא\u0004 יחד, \u0003ולימא\u0004 \u0005[ונאמר]\u0006 כי שיטת \u0003ר' עקיבא היא\u0004 לפי דעת רב יוסף שהערל והטמא נחשבים כענין אחד, ואם כן צריך שיימצא מקור כלשהו שמביע דעה זו.","ושואלים: \u0003ולא?\u0004 וכי אין דבר כזה? \u0003והא קתני\u0004 \u0005[והרי שנה]:\u0006 \u0003הערל והטמא פטורים מן הראייה!\u0004 ודוחים: זו אינה ראיה, כי \u0003התם\u0004 \u0005[שם]\u0006 אפשר לומר \u0003משום דמאיס\u0004 \u0005[ש\u0006הוא \u0005מאוס],\u0006 שהערלה מגונה, ואין זה כבוד שייראה הערל בעזרה, אבל לא משום טומאה.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והלכו\u0006 חכמים ור' יהודה \u0005לטעמם,\u0006 לשיטתם\u0005]\u0006 בענין אנדרוגינוס. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכל כשרים לקדש\u0004 מי חטאת — \u0003חוץ מחרש שוטה וקטן, ר' יהודה מכשיר בקטן ופוסל באשה ובאנדרוגינוס.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחו לטמא מעפר שרפת החטאת\u0004 ונתן עליו מים חיים אל כלי\u0003\"\u0004 (במדבר יט, יז), לומר: כיון שנתינת המים נסמכה לאסיפת אפר שריפת הפרה, הרי זה בא ללמד שדינם שווה: \u0003הנך דפסלי\u0004 \u0005[אלו שפסולים]\u0006 \u0003באסיפה\u0004 של האפר \u0005—\u0006 \u0003פסולין\u0004 גם \u0003בקידוש\u0004 האפר, \u0003הנך\u0004 \u0005[אלה]\u0006 ש\u0003כשרין באסיפה — כשרים בקידוש,\u0004 ואשה שכשירה באסיפת האפר — כשירה גם בקידוש המים.","\u0003ור' יהודה אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"ולקח\"\u0004 לטמא, \u0003מאי\u0004 \u0005[מה]\u0006 הוא \u0003\"ולקחו\"\u0004 שעובר מלשון יחיד לרבים ש\u0003אפילו הנך\u0004 \u0005[אלה]\u0006 ש\u0003פסולין התם\u0004 \u0005[שם],\u0006 \u0003כשרים הכא\u0004 \u0005[כאן],\u0006 ואין דינם שוה, ולכן הוא מרבה את הקטן שכשר לקידוש.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אשה נמי\u0004 \u0005[גם כן]\u0006 תהיה כשירה אף לדעת ר' יהודה! ומשיבים: לדעת ר' יהודה יש לדייק בלשון: \u0003\"ונתן\" ולא \"ונתנה\".\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? — \u0003אי כתיב\u0004 \u0005[אילו\u0006 \u0005נאמר]\u0006 \u0003\"ולקח\" \"ונתן\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שלפי הדין \u0003שקיל חד ויהיב חד\u0004 \u0005[לוקח אחד\u0006 את האפר \u0005ונותן\u0006 אותו \u0005אחד\u0006 את המים\u0005]\u0006 — משום כך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ולקחו\"\u0004 ללמד שגם אם עושים זאת אנשים שונים כשר.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005אומרת התורה]\u0006 רק \u0003\"ולקחו\" \"ונתנו\" — הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003דשקלי תרי ויהבי תרי\u0004 \u0005[שלוקחים שניים ונותנים שניים]\u0006 ובפחות מזה אינו ראוי, על כן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ולקחו\" \"ונתן\" —\u0004 ש\u0003אפילו שקלי תרי ויהיב חד\u0004 \u0005[לוקחים שניים ונותן אחד]\u0006 גם כשר. וכיון שיש צורך לדייק ולכתוב בלשון זו, אין איפוא לדייק מהמלה \"ונתן\" שבאה למעט אשה."],["\u0003\"והזה הטהר על הטמא\"\u0004 (במדבר יט, יט), \u0003\"טהור\" — מכלל שהוא טמא,\u0004 כלומר, מדובר באיש שהוא קרוי טהור רק בהשוואה לטמא, שאם לא כן לא היה צורך להזכיר כלל שצריך שיהא טהור, והיינו מבינים מעצמנו שבדבר הקרוי \"חטאת\" ומקפידים על טהרתו חייב להיות המטהר טהור, ולכן יש לומר ש\"טהור\" זה אינו טהור גמור לכל ענין, \u0003לימד על טבול יום שכשר בפרה\u0004 אדומה.","ולענין ראשון, \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ששת: ערל מהו במעשר?\u0004 האם נאמר \u0003כי היכי דיליף\u0004 \u0005[כפי שלמד]\u0006 \u0003פסח ממעשר לענין אנינות\u0004, שהאונן אסור לאכול בפסח כמו במעשר, \u0003יליף נמי\u0004 \u0005[למד גם כן]\u0006 \u0003מעשר מפסח לענין ערלות\u0004 שהערל אסור במעשר,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003חמור מקל יליף\u0004 \u0005[לומד],\u0006 שפסח שהוא קדשים ודינו חמור נלמד ממעשר, אבל \u0003קל מחמור לא יליף\u0004 \u0005[אינו לומד]\u0006 ואולי רק פסח שחמור, ערל אסור בו?","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 במשנה: \u0003התרומה והבכורים חייבים עליהם מיתה\u0004 אם אוכלים אותם בטומאה, וזרים (מי שאינם כהנים) שאוכלים אותם בשגגה חייבים לשלם את ערכם בתוספת \u0003חומש\u0004 (חמישית) \u0003ואסורין לזרים\u0004 באכילה,","\u0003והן נכסי כהן\u0004 לכל ענין, \u0003ועולין\u0004 (מתבטלים) אם נתערבו בדבר אחר שהוא מרובה בכמות \u0003ב\u0004שיעור של פי \u0003אחד ומאה, וטעונין רחיצת ידים\u0004 לפני אכילתם, \u0003ו\u0004טעונים \u0003הערב שמש,\u0004 אחר טבילה שטבל אדם להיטהר מטומאתו. \u0003הרי\u0004 דינים \u0003אלו בתרומה ובבכורים, מה שאין כן במעשר.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 דין שמותר לערל לאכול במעשר — \u0003ניתני\u0004 \u0005[שישנה]\u0006 גם: \u0003ערל אסור בהן\u0004 בתרומה ובביכורים, \u0003מה שאין כן במעשר!\u0004","ודוחים: מכאן אין ראיה, כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר,\u0004 שלא מנה את כל ההבדלים. ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006גם את \u0005זה]\u0006 \u0003שייר?\u0004","ומשיבים: \u0003שייר דקא תני סיפא\u0004 \u0005[\u0006את מה \u0005ששנה\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003יש במעשר ובבכורים מה שאין כן בתרומה, שהמעשר והבכורים טעונין הבאת מקום\u0004 להעלותם לירושלים ושם הם נאכלים, ואילו התרומה נאכלת בכל מקום, \u0003וטעונין וידוי\u0004, שיש צורך לומר וידוי על המעשר בסוף כמה שנים כשמבער מביתו את כל מה שהיה חייב לתת, וכן כשמביא ביכורים מתוודה, \u0003ואסור לאונן\u0004 לאכול מהם, \u0003ור' שמעון מתיר\u0004 ביכורים לאונן. \u0003וחייבין\u0004 כל אלה, \u0003בביעור,\u0004 כששהה ולא הביא ביכורים ומעשר עד סוף השנה השלישית משנות השמיטה, מבער אותם מביתו, \u0003ור' שמעון פוטר\u0004 ביכורים מן הביעור.","\u0003ואילו,\u0004 שיש הבדל בין תרומה לבין מעשר וביכורים בזה שאת אלה האחרונים \u0003אסור לבער מהן בטומאה,\u0004 כלומר, שאם נטמאו אסור ליהנות מהם גם בשעת ביעורם (כגון להשתמש בשמן טמא למאור)."],["\u0003ואוכלן\u0004 (ומי שאוכלן) \u0003בטומאת עצמן\u0004 כשהמעשר והביכורים עצמם טמאים, אף על פי שהוא טהור — \u0003לוקה\u0004 על כך, \u0003מה שאין כן בתרומה,\u0004 שביחס אליה \u0003לא קתני\u0004 \u0005[שנה]\u0006 גם את ההבדל הזה. \u0003אלמא תני\u0004 \u0005[מכאן\u0006 ש\u0005שנה]\u0006 \u0003ושייר\u0004 ולא פירט את כל ההבדלים, וממילא אין להסיק ממה שלא נזכר ערל שהוא מותר במעשר.","כיון שהזכרנו ברייתא זו דנים בה עתה לגופה, שנינו שביכורים \u0003אסורים לאונן, ור' שמעון מתיר.\u0004 ושואלים: \u0003מנא להו\u0004 \u0005[מניין להם]\u0006 לחכמים שאסורים? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תוכל לאכל בשעריך מעשר דגנך ותירשך ויצהרך... ותרומת ידך\"\u0004 (דברים יב, יז) \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"תרומת ידך\" — אלו\u0004 ה\u0003בכורים, ו\u0004אם כן \u0003איתקש\u0004 \u0005[הוקשו,\u0006 הושוו\u0005]\u0006 בפסוק זה \u0003בכורים למעשר,\u0004 ללמד: \u0003מה מעשר אסור לאונן — אף בכורים אסור לאונן.\u0004","\u0003ור' שמעון\u0004 אומר: כיון ש\u0003תרומה קרינהו רחמנא\u0004 \u0005[קראה אותם התורה]\u0006 דינם כתרומה, \u0003מה תרומה מותרת לאונן — אף בכורים מותר לאונן. ו\u0004כן מה ששנינו שם שביכורים","\u0003חייבין בביעור, ור' שמעון פוטר.\u0004 ומסבירים: \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003מקיש ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003לא מקיש\u0004 ביכורים למעשר, כפי שאמרנו.","\u0003ואסור לבער מהן בטומאה ו\u0004ה\u0003אוכלן בטומאת עצמן\u0004 אף שהוא טהור, \u0003לוקה, מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר,\u0004 נאמר: \u0003\"\u0004ו\u0003לא בערתי ממנו בטמא\"\u0004 (שם כו, יד) בלשון כללית, וכוונתו: \u0003בין שאני\u0004 האוכל \u0003טמא והוא\u0004 המעשר \u0003טהור, בין שאני טהור והוא טמא.\u0004 שבכל מקרה אסור לבער את המעשר בטומאה, ואכילתו אף היא בכלל ביעור.","ומוסיף התנא: \u0003והיכא\u0004 \u0005[והיכן]\u0006 \u0003מוזהר על אכילתו\u0004 של מעשר בטומאה \u0003איני יודע,\u0004 שאף שמן הפסוק מובן שהדבר אסור, לא ברור היכן נאמר איסור זה במפורש. ותוהים: \u0003טומאת הגוף\u0004 של האוכל הלא \u0003בהדיא כתיב ביה\u0004 \u0005[נאמרה בו],\u0006 שנאמר בטומאת שרץ: \u0003\"נפש אשר תגע בו וטמאה עד הערב ולא יאכל מן הקדשים כי אם רחץ בשרו במים\"\u0004 (ויקרא כב, ו), ומסבירים (להלן יבמות עד, ב), שמדובר כאן במעשר!","ואומרים: \u0003הכי קמיבעיא ליה\u0004 \u0005[כך נשאלה לו]:\u0006 \u0003טומאת עצמו\u0004 של המעשר, \u0003מנין\u0004 שאסור לאכול ממנו כשהוא טמא בטומאת עצמו? \u0003תלמוד לומר: \"לא תוכל לאכל בשעריך מעשר דגנך\"\u0004 (דברים יב, יז), \u0003ולהלן\u0004 (הלאה) בהמשך לגבי קרבנות שנפסלו \u0003הוא אומר \"בשעריך תאכלנו הטמא והטהור יחדו כצבי וכאיל\"\u0004 (שם טו, כב), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אפילו טמא וטהור אוכלין על שולחן אחד בקערה אחת ואינן חוששין, וקאמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003ההוא דאמרי לך התם\u0004 \u0005[אותו\u0006 דבר \u0005שאמרתי לך שם]\u0006 \u0003\"בשעריך תאכלנו\"\u0004 שאין הבדל אם הוא טמא או שהוא טהור והבשר טמא — \u0003הכא\u0004 \u0005[כאן]\u0006 במעשר \u0003לא תיכול\u0004 \u0005[תאכל],\u0006 ואם כן למדנו שאסור לאכול אותם בטומאת עצמן.","שנינו שאסור לבער מעשר בטמא, \u0003מה שאין כן בתרומה.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שאין הדבר כך בתרומה? \u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במעשר: \u0003\"\u0004ו\u0003לא בערתי ממנו בטמא\"\u0004 (שם כו, יד), ויש לראות זאת כהדגשה למעט: \u0003ממנו,\u0004 מן המעשר, \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מבעיר\u0004 בטמא, \u0003אבל אתה מבעיר\u0004 בטומאה דברים אחרים, כגון \u0003שמן של תרומה שנטמא,\u0004 שמותר להשתמש בו.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003ממנו\u0004 מן המעשר \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מבעיר — אבל אתה מבעיר שמן של קדש שנטמא!\u0004 ודוחים: \u0003לאו\u0004 \u0005[\u0006וכי \u0005לא]\u0006 \u0003קל וחומר הוא? ומה\u0004 ב\u0003מעשר הקל אמרה תורה \"\u0004ו\u0003לא בערתי ממנו בטמא\" — קדש\u0004 שהוא \u0003חמור לא כל שכן\u0004 שאסור?!","ואומרים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003קל וחומר הוא,\u0004 שהתרומה בודאי מקודשת מן המעשר! ואומרים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ממנו\"\u0004 למעט!","ושואלים: \u0003ומה ראית\u0004 לומר שקודש אסור לבער בטמא, ותרומה מותרת, ולא להיפך? והרי בכתוב עצמו לא נאמר דבר בענין זה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003קדש לא ממעיטנא\u0004 \u0005[אין אנחנו ממעטים\u0006 מאיסור זה\u0005]\u0006 \u0003שכן פנקעכ\"ס\u0004 שהוא סימן של החומרות שיש בקודש ואין בתרומה:","דין \u0003פגול\u0004 — קרבן שהכהן חשב להקטירו או לאכלו שלא בזמנו נפסל ונאסר באיסור חמור, וכן איסור \u0003נותר,\u0004 שאסור לאוכלו אחרי זמן קצוב, והוא \u0003קרבן\u0004 לשם ה', ומביאים קרבן \u0003מעילה\u0004 אם משתמשים בו בשגגה, ויש איסור \u0003כרת\u0004 על אכילתו בטומאה, \u0003ואסור לאונן.\u0004","ואומרים: \u0003אדרבה\u0004 (להיפך) \u0003תרומה לא ממעיטנא\u0004 \u0005[מיעט]\u0006 \u0003שכן\u0004 יש בה חומרות שסימנן \u0003מחפ\"ז,\u0004 שיש עונש \u0003מיתה\u0004 בידי שמים על טמא שאוכלה במזיד, וזר שאכלה בשגגה צריך תמיד להוסיף \u0003חומש\u0004 לכהן, מה שאין כן בקדשים לאחר שנזרק דמם, \u0003ואין לה פדיון\u0004 כמו שיש לקדשים, \u0003ואסורה לזרים\u0004 — מה שאין כן בקדשים, שיש קרבנות הנאכלים גם לזרים!","ומשיבים: \u0003הנך נפישן\u0004 \u0005[אלה\u0006 החומרות בקודש \u0005מרובות\u0006 יותר\u0005].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 גם בלא נימוק זה: עונש \u0003כרת עדיפא\u0004 \u0005[עדיף]\u0006 וחמור מעונש מיתה בידי שמים.","שנינו שם שה\u0003אוכלן בטומאת עצמן לוקה, מה שאין כן בתרומה.\u0004 ומדייקים מלשון זו: \u0003מילקא\u0004 \u0005[ללקות]\u0006 \u0003הוא דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 כשאוכל תרומה בטומאת עצמה — \u0003הא איסורא איכא\u0004 \u0005[הרי איסור יש\u0006 בכך\u0005] —\u0006 \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שיש בכך איסור? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בשעריך תאכלנו\"\u0004 (שם טו, כב), ויש כאן הדגשה \"תאכלנו\" — אותו בלבד, \u0003לזה ולא לאחר.\u0004 שרק קרבנות שנפסלו מותר לאכול אפילו בטומאה אבל לא קודש אחר. \u0003ו\u0004כלל הוא שכל \u0003לאו הבא מכלל עשה — עשה,\u0004 ומכיון שלא נאמר בלשון איסור לא תעשה, והאיסור נובע רק ממצוה שנאמרה בלשון עשה, הרי איסור זה נחשב רק כעשה, ואין לוקים עליו.","וחוזרים לענין ראשון: הוכחנו כבר שאין להביא ראיה מן המשנה שהביא רב ששת, שכן לא נמנו בה כל ההבדלים שבין המעשר והתרומה, והתנא שנה ושייר. \u0003אמר רב אשי: מרישא נמי שמעת מינה\u0004 \u0005[מראש,\u0006 מתחילת המשנה, \u0005גם כן\u0006 יכול אתה \u0005לשמוע ממנה]\u0006 \u0003דתנא\u0004 \u0005[ששנה]\u0006 \u0003ושייר,\u0004 וראיה לדבר — \u0003מדלא קתני\u0004 \u0005[מ\u0006מה \u0005שלא שנה]\u0006 גם הבדל נוסף זה"]]};
